export default JSON.parse('{"work":{"id":"guanzi","schoolId":"legalism","title":"《管子》","genreStrategy":"argumentative","sourceNote":"版本來源自通行本及校勘附記。","chapterIds":["guanzi_ch-1","guanzi_ch-2","guanzi_ch-3","guanzi_ch-4"],"totalChars":6912},"chapters":[{"id":"guanzi_ch-1","workId":"guanzi","order":1,"title":"牧民","difficulty":4,"estimatedMinutes":10,"passageIds":["guanzi_ch-1_p-1","guanzi_ch-1_p-2","guanzi_ch-1_p-3","guanzi_ch-1_p-4","guanzi_ch-1_p-5","guanzi_ch-1_p-6","guanzi_ch-1_p-7","guanzi_ch-1_p-8","guanzi_ch-1_p-9","guanzi_ch-1_p-10"],"tags":[]},{"id":"guanzi_ch-2","workId":"guanzi","order":2,"title":"形勢","difficulty":4,"estimatedMinutes":10,"passageIds":["guanzi_ch-2_p-1","guanzi_ch-2_p-2","guanzi_ch-2_p-3","guanzi_ch-2_p-4","guanzi_ch-2_p-5","guanzi_ch-2_p-6","guanzi_ch-2_p-7","guanzi_ch-2_p-8","guanzi_ch-2_p-9"],"tags":[]},{"id":"guanzi_ch-3","workId":"guanzi","order":3,"title":"權修","difficulty":4,"estimatedMinutes":10,"passageIds":["guanzi_ch-3_p-1","guanzi_ch-3_p-2","guanzi_ch-3_p-3","guanzi_ch-3_p-4","guanzi_ch-3_p-5","guanzi_ch-3_p-6","guanzi_ch-3_p-7","guanzi_ch-3_p-8","guanzi_ch-3_p-9","guanzi_ch-3_p-10","guanzi_ch-3_p-11","guanzi_ch-3_p-12","guanzi_ch-3_p-13"],"tags":[]},{"id":"guanzi_ch-4","workId":"guanzi","order":4,"title":"立政","difficulty":4,"estimatedMinutes":10,"passageIds":["guanzi_ch-4_p-1","guanzi_ch-4_p-2","guanzi_ch-4_p-3","guanzi_ch-4_p-4","guanzi_ch-4_p-5","guanzi_ch-4_p-6","guanzi_ch-4_p-7","guanzi_ch-4_p-8","guanzi_ch-4_p-9","guanzi_ch-4_p-10","guanzi_ch-4_p-11","guanzi_ch-4_p-12","guanzi_ch-4_p-13","guanzi_ch-4_p-14","guanzi_ch-4_p-15","guanzi_ch-4_p-16","guanzi_ch-4_p-17","guanzi_ch-4_p-18","guanzi_ch-4_p-19","guanzi_ch-4_p-20"],"tags":[]}],"passages":[{"id":"guanzi_ch-1_p-1","chapterId":"guanzi_ch-1","order":1,"canonicalText":"凡有地牧民者，務在四時，守在倉廩。國多財，則遠者來，地闢舉，則民留處；倉廩實，則知禮節；衣食足，則知榮辱；上服度，則六親固。四維張，則君令行。故省刑之要，在禁文巧，守國之度，在飾四維，順民之經，在明鬼神，祇山川，敬宗廟，恭祖舊。不務天時，則財不生；不務地利，則倉廩不盈；野蕪曠，則民乃菅，上無量，則民乃妄。文巧不禁，則民乃淫，不璋兩原，則刑乃繁。不明鬼神，則陋民不悟；不祇山川，則威令不聞；不敬宗廟，則民乃上校；不恭祖舊，則孝悌不備；四維不張，國乃滅亡。","sentenceIds":["guanzi_ch-1_p-1_s-1","guanzi_ch-1_p-1_s-2","guanzi_ch-1_p-1_s-3","guanzi_ch-1_p-1_s-4","guanzi_ch-1_p-1_s-5","guanzi_ch-1_p-1_s-6","guanzi_ch-1_p-1_s-7","guanzi_ch-1_p-1_s-8","guanzi_ch-1_p-1_s-9","guanzi_ch-1_p-1_s-10","guanzi_ch-1_p-1_s-11","guanzi_ch-1_p-1_s-12","guanzi_ch-1_p-1_s-13","guanzi_ch-1_p-1_s-14","guanzi_ch-1_p-1_s-15","guanzi_ch-1_p-1_s-16"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guanzi/zh"}],"readingAid":{"translation":"凡有地牧民者，務在四時，守在倉廩；國多財，則遠者來，地闢舉，則民留處；倉廩實，則知禮節；衣食足，則知榮辱；上服度，則六親固；四維張，則君令行；故省刑之要，在禁文巧，守國之度，在飾四維，順民之經，在明鬼神，祇山川，敬宗廟，恭祖舊；不務天時，則財不生；不務地利，則倉廩不盈；野蕪曠，則民乃菅，上無量，則民乃妄；文巧不禁，則民乃淫，不璋兩原，則刑乃繁；不明鬼神，則陋民不悟；不祇山川，則威令不聞；不敬宗廟，則民乃上校；不恭祖舊，則孝悌不備；四維不張，國乃滅亡。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【主題與背景】\\n本段作為《管子·牧民》篇的總綱，概括了管仲治國的核心理念。管仲輔佐齊桓公，其核心政策即在於經濟與軍事的並重。\\n\\n【詞義與名物】\\n「牧民」：治理人民，如同牧羊人引導羊羣。\\n「倉婞」：即糧倉，指代國家的物資儲備。\\n「輕重」：古代經濟術語，指貨幣與物價的關係，也指國家對經濟的宏觀調控。\\n\\n【法家治道】\\n這段話點出了法家與管仲學派的務實主義：強調物質基礎（倉婞實）是道德與秩序（知禮節）的前提。透過國家對資源（山海）的掌控與經濟調控（輕重），實現富國強兵的終極目標。"}},{"id":"guanzi_ch-1_p-2","chapterId":"guanzi_ch-1","order":2,"canonicalText":"右國頌","sentenceIds":["guanzi_ch-1_p-2_s-1"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guanzi/zh"}],"readingAid":{"translation":"右國頌。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【主題與背景】本段選自《管子》〈牧民〉，記錄先秦秦漢經典思想與歷史實踐之精華。\\n【詞義與名物】文中包含關鍵詞彙如：「右國頌」，展現古代漢語精練優雅之語法結構。\\n【思想與篇章】本篇體現了修德立身、順應天道與治國安民的深遠哲理，具有極高的學術考證與思想啟發價值。"}},{"id":"guanzi_ch-1_p-3","chapterId":"guanzi_ch-1","order":3,"canonicalText":"國有四維，一維絕則傾，二維絕則危，三維絕則覆，四維絕則滅。傾可正也，危可安也，覆可起也，滅不可復錯也。何謂四維？一曰禮、二曰義、三曰廉、四曰恥。禮不踰節，義不自進。廉不蔽惡，恥不從枉。故不踰節，則上位安；不自進，則民無巧軸；不蔽惡，則行自全；不從枉，則邪事不生。","sentenceIds":["guanzi_ch-1_p-3_s-1","guanzi_ch-1_p-3_s-2","guanzi_ch-1_p-3_s-3","guanzi_ch-1_p-3_s-4","guanzi_ch-1_p-3_s-5","guanzi_ch-1_p-3_s-6","guanzi_ch-1_p-3_s-7","guanzi_ch-1_p-3_s-8","guanzi_ch-1_p-3_s-9","guanzi_ch-1_p-3_s-10"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guanzi/zh"}],"readingAid":{"translation":"國有四維，一維絕則傾，二維絕則危，三維絕則覆，四維絕則滅；傾可正也，危可安也，覆可起也，滅不可復錯也；何謂四維；一說：禮、二說：義、三說：廉、四說：恥；禮不踰節，義不自進；廉不蔽惡，恥不從枉；故不踰節，則上位安；不自進，則民無巧軸；不蔽惡，則行自全；不從枉，則邪事不生。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【題解與背景】\\n本段選自《管子》〈牧民〉，為該經典著作之精華章節，呈現先秦兩漢時期深刻的思想觀點與歷史實踐。\\n【詞義與名物】\\n文中經典語句「國有四維，一維絕則傾，二維絕則危，三……」詞意凝練，包含古漢語重要名詞概念與語法句式。\\n【思想與史事脈絡】\\n全段旨在大致闡發道德修養、因時制宜與實踐致用之根本原則，對後世國學研究具備極高的參考價值。"}},{"id":"guanzi_ch-1_p-4","chapterId":"guanzi_ch-1","order":4,"canonicalText":"右四維","sentenceIds":["guanzi_ch-1_p-4_s-1"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guanzi/zh"}],"readingAid":{"translation":"右四維。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【主題與背景】本段選自《管子》〈牧民〉，記錄先秦秦漢經典思想與歷史實踐之精華。\\n【詞義與名物】文中包含關鍵詞彙如：「右四維」，展現古代漢語精練優雅之語法結構。\\n【思想與篇章】本篇體現了修德立身、順應天道與治國安民的深遠哲理，具有極高的學術考證與思想啟發價值。"}},{"id":"guanzi_ch-1_p-5","chapterId":"guanzi_ch-1","order":5,"canonicalText":"政之所興，在順民心。政之所廢，在逆民心。民惡憂勞，我佚樂之。民惡貧賤，我富貴之，民惡危墜，我存安之。民惡滅絕，我生育之。能佚樂之，則民為之憂勞。能富貴之，則民為之貧賤。能存安之，則民為之危墜。能生育之，則民為之滅絕。故刑罰不足以畏其意，殺戮不足以服其心。故刑罰繁而意不恐，則令不行矣。殺戮眾而心不服，則上位危矣。故從其四欲，則遠者自親；行其四惡，則近者叛之，故知「予之為取者，政之寶也」。","sentenceIds":["guanzi_ch-1_p-5_s-1","guanzi_ch-1_p-5_s-2","guanzi_ch-1_p-5_s-3","guanzi_ch-1_p-5_s-4","guanzi_ch-1_p-5_s-5","guanzi_ch-1_p-5_s-6","guanzi_ch-1_p-5_s-7","guanzi_ch-1_p-5_s-8","guanzi_ch-1_p-5_s-9","guanzi_ch-1_p-5_s-10","guanzi_ch-1_p-5_s-11","guanzi_ch-1_p-5_s-12","guanzi_ch-1_p-5_s-13","guanzi_ch-1_p-5_s-14"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guanzi/zh"}],"readingAid":{"translation":"政之所興，在順民心；政之所廢，在逆民心；民惡憂勞，我佚樂之；民惡貧賤，我富貴之，民惡危墜，我存安之；民惡滅絕，我生育之；能佚樂之，則民為之憂勞；能富貴之，則民為之貧賤；能存安之，則民為之危墜。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【主題與背景】本段選自《管子》〈牧民〉，記錄先秦秦漢經典思想與歷史實踐之精華。\\n【詞義與名物】文中包含關鍵詞彙如：「政之所興、在順民心、政之所廢、在逆民心」，展現古代漢語精練優雅之語法結構。\\n【思想與篇章】本篇體現了修德立身、順應天道與治國安民的深遠哲理，具有極高的學術考證與思想啟發價值。"}},{"id":"guanzi_ch-1_p-6","chapterId":"guanzi_ch-1","order":6,"canonicalText":"右四順","sentenceIds":["guanzi_ch-1_p-6_s-1"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guanzi/zh"}],"readingAid":{"translation":"右四順。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【主題與背景】本段選自《管子》〈牧民〉，記錄先秦秦漢經典思想與歷史實踐之精華。\\n【詞義與名物】文中包含關鍵詞彙如：「右四順」，展現古代漢語精練優雅之語法結構。\\n【思想與篇章】本篇體現了修德立身、順應天道與治國安民的深遠哲理，具有極高的學術考證與思想啟發價值。"}},{"id":"guanzi_ch-1_p-7","chapterId":"guanzi_ch-1","order":7,"canonicalText":"錯國於不傾之地，積於不涸之倉，藏於不竭之府，下令於流水之原，使民於不爭之官，明必死之路，開必得之門。不為不可成，不求不可得，不處不可久，不行不可復。錯國於不傾之地者，授有德也；積於不涸之倉者，務五穀也；藏於不竭之府者，養桑麻育六畜也；下令於流水之原者，令順民心也；使民於不爭之官者，使各為其所長也；明必死之路者，嚴刑罰也；開必得之門者，信慶賞也；不為不可成者，量民力也；不求不可得者，不彊民以其所惡也；不處不可久者，不偷取一世也；不行不可復者，不欺其民也；故授有德，則國安；務五穀，則食足；養桑麻，育六畜，則民富；令順民心，則威令行；使民各為其所長，則用備；嚴刑罰，則民遠邪；信慶賞，則民輕難；量民力，則事無不成；不彊民以其所惡，則軸偽不生；不偷取一世，則民無怨心；不欺其民，則下親其上。","sentenceIds":["guanzi_ch-1_p-7_s-1","guanzi_ch-1_p-7_s-2","guanzi_ch-1_p-7_s-3","guanzi_ch-1_p-7_s-4","guanzi_ch-1_p-7_s-5","guanzi_ch-1_p-7_s-6","guanzi_ch-1_p-7_s-7","guanzi_ch-1_p-7_s-8","guanzi_ch-1_p-7_s-9","guanzi_ch-1_p-7_s-10","guanzi_ch-1_p-7_s-11","guanzi_ch-1_p-7_s-12","guanzi_ch-1_p-7_s-13","guanzi_ch-1_p-7_s-14","guanzi_ch-1_p-7_s-15","guanzi_ch-1_p-7_s-16","guanzi_ch-1_p-7_s-17","guanzi_ch-1_p-7_s-18","guanzi_ch-1_p-7_s-19","guanzi_ch-1_p-7_s-20","guanzi_ch-1_p-7_s-21","guanzi_ch-1_p-7_s-22","guanzi_ch-1_p-7_s-23","guanzi_ch-1_p-7_s-24"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guanzi/zh"}],"readingAid":{"translation":"錯國於不傾之地，積於不涸之倉，藏於不竭之府，下令於流水之原，使民於不爭之官，明必死之路，開必得之門；不為不可成，不求不可得，不處不可久，不行不可復；錯國於不傾之地者，授有德也；積於不涸之倉者，務五穀也；藏於不竭之府者，養桑麻育六畜也；下令於流水之原者，令順民心也；使民於不爭之官者，使各為其所長也；明必死之路者，嚴刑罰也；開必得之門者，信慶賞也；不為不可成者，量民力也；不求不可得者，不彊民以其所惡也；不處不可久者，不偷取一世也；不行不可復者，不欺其民也；故授有德，則國安；務五穀，則食足；養桑麻，育六畜，則民富；令順民心，則威令行；使民各為其所長，則用備；嚴刑罰，則民遠邪；信慶賞，則民輕難；量民力，則事無不成；不彊民以其所惡，則軸偽不生；不偷取一世，則民無怨心；不欺其民，則下親其上。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【題解與背景】\\n本段選自《管子》〈牧民〉，為該經典著作之精華章節，呈現先秦兩漢時期深刻的思想觀點與歷史實踐。\\n【詞義與名物】\\n文中經典語句「錯國於不傾之地，積於不涸之倉，藏於不……」詞意凝練，包含古漢語重要名詞概念與語法句式。\\n【思想與史事脈絡】\\n全段旨在大致闡發道德修養、因時制宜與實踐致用之根本原則，對後世國學研究具備極高的參考價值。"}},{"id":"guanzi_ch-1_p-8","chapterId":"guanzi_ch-1","order":8,"canonicalText":"右士經","sentenceIds":["guanzi_ch-1_p-8_s-1"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guanzi/zh"}],"readingAid":{"translation":"右士經。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【主題與背景】本段選自《管子》〈牧民〉，記錄先秦秦漢經典思想與歷史實踐之精華。\\n【詞義與名物】文中包含關鍵詞彙如：「右士經」，展現古代漢語精練優雅之語法結構。\\n【思想與篇章】本篇體現了修德立身、順應天道與治國安民的深遠哲理，具有極高的學術考證與思想啟發價值。"}},{"id":"guanzi_ch-1_p-9","chapterId":"guanzi_ch-1","order":9,"canonicalText":"以家為鄉，鄉不可為也。以鄉為國，國不可為也。以國為天下，天下不可為也。以家為家，以鄉為鄉，以國為國，以天下為天下。毋曰不同生，遠者不聽。毋曰不同鄉，遠者不行。毋曰不同國，遠者不從。如地如天，何私何親？如月如日，唯君之節。御民之轡，在上之所貴。道民之門，在上之所先。召民之路，在上之所好惡。故君求之，則臣得之。君嗜之，則臣食之。君好之，則臣服之。君惡之，則臣匿之。毋蔽汝惡，毋異汝度，賢者將不汝助。言室滿室，言堂滿堂，是謂聖王。城郭溝渠，不足以固守；兵甲彊力，不足以應敵；博地多財，不足以有眾。惟有道者，能備患於未形也，故禍不萌。天下不患無臣，患無君以使之。天下不患無財，患無人以分之。故知時者，可立以為長。無私者，可置以為政。審於時而察於用，而能備官者，可奉以為君也。緩者後於事。吝於財者失所親，信小人者失士。","sentenceIds":["guanzi_ch-1_p-9_s-1","guanzi_ch-1_p-9_s-2","guanzi_ch-1_p-9_s-3","guanzi_ch-1_p-9_s-4","guanzi_ch-1_p-9_s-5","guanzi_ch-1_p-9_s-6","guanzi_ch-1_p-9_s-7","guanzi_ch-1_p-9_s-8","guanzi_ch-1_p-9_s-9","guanzi_ch-1_p-9_s-10","guanzi_ch-1_p-9_s-11","guanzi_ch-1_p-9_s-12","guanzi_ch-1_p-9_s-13","guanzi_ch-1_p-9_s-14","guanzi_ch-1_p-9_s-15","guanzi_ch-1_p-9_s-16","guanzi_ch-1_p-9_s-17","guanzi_ch-1_p-9_s-18","guanzi_ch-1_p-9_s-19","guanzi_ch-1_p-9_s-20","guanzi_ch-1_p-9_s-21","guanzi_ch-1_p-9_s-22","guanzi_ch-1_p-9_s-23","guanzi_ch-1_p-9_s-24","guanzi_ch-1_p-9_s-25","guanzi_ch-1_p-9_s-26","guanzi_ch-1_p-9_s-27","guanzi_ch-1_p-9_s-28","guanzi_ch-1_p-9_s-29"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guanzi/zh"}],"readingAid":{"translation":"以家為鄉，鄉不可為也；以鄉為國，國不可為也；以國為天下，天下不可為也；以家為家，以鄉為鄉，以國為國，以天下為天下；毋說：不同生，遠者不聽；毋說：不同鄉，遠者不行；毋說：不同國，遠者不從；如地如天，何私何親。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【主題與背景】本段選自《管子》〈牧民〉，記錄先秦秦漢經典思想與歷史實踐之精華。\\n【詞義與名物】文中包含關鍵詞彙如：「以家為鄉、鄉不可為、以鄉為國、國不可為」，展現古代漢語精練優雅之語法結構。\\n【思想與篇章】本篇體現了修德立身、順應天道與治國安民的深遠哲理，具有極高的學術考證與思想啟發價值。"}},{"id":"guanzi_ch-1_p-10","chapterId":"guanzi_ch-1","order":10,"canonicalText":"右六親五法","sentenceIds":["guanzi_ch-1_p-10_s-1"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guanzi/zh"}],"readingAid":{"translation":"右六親五法。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【主題與背景】本段選自《管子》〈牧民〉，記錄先秦秦漢經典思想與歷史實踐之精華。\\n【詞義與名物】文中包含關鍵詞彙如：「右六親五」，展現古代漢語精練優雅之語法結構。\\n【思想與篇章】本篇體現了修德立身、順應天道與治國安民的深遠哲理，具有極高的學術考證與思想啟發價值。"}},{"id":"guanzi_ch-2_p-1","chapterId":"guanzi_ch-2","order":1,"canonicalText":"山高而不崩，則祈羊至矣；淵深而不涸，則沈玉極矣，天不變其常，地不易其則，春秋冬夏，不更其節，古今一也。蛟龍得水，而神可立也；虎豹得幽，而威可載也。風雨無鄉，而怨怒不及也。貴有以行令，賤有以忘卑，壽夭貧富，無徒歸也。","sentenceIds":["guanzi_ch-2_p-1_s-1","guanzi_ch-2_p-1_s-2","guanzi_ch-2_p-1_s-3","guanzi_ch-2_p-1_s-4","guanzi_ch-2_p-1_s-5","guanzi_ch-2_p-1_s-6"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guanzi/zh"}],"readingAid":{"translation":"此段大意是說：對於「《管子·」的情境，應當採取相應的具體對策，在軍事行動中必須掌握敵我態勢並靈活調度，對於「倉婞實而」的情境，應當採取相應的具體對策，對於「山海官輕」的情境，應當採取相應的具體對策。這不僅是觀念上的指導，更是實踐中的方針。","analysis":"【主題與背景】\\n本段文字聚焦於古代社會中關於「《管」的理論與實踐。在複雜的政治或戰爭環境下，這是決策者不可忽視的關鍵。\\n\\n【詞義與名物】\\n「《管」：在此處不僅是字面意義，更代表了當時的一種特定管理手段。\\n「山海」：反映了資源分配或戰術部署上的實際考量。\\n\\n【法家治道】\\n從法家務實的角度來看，對於「《管」與「山海」的處理，顯示了其重視制度與國家利益的特質。這為後世提供了重要的實踐參考。"}},{"id":"guanzi_ch-2_p-2","chapterId":"guanzi_ch-2","order":2,"canonicalText":"銜命者，君之尊也。受辭者，名之鉉也。上無事，則民自試。抱蜀不言，而廟堂既修。鴻鵠鏘鏘，唯民歌之。濟濟多士，殷民化之，紂之失也。飛蓬之問，不在所賓；燕雀之集，道行不顧。犧牷圭璧，不足以饗鬼神。主功有素，寶幣奚為？羿之道，非射也；造父之術，非馭也；奚仲之巧，非斲削也。召遠者使無為焉，親近者言無事焉，唯夜行者獨有也。","sentenceIds":["guanzi_ch-2_p-2_s-1","guanzi_ch-2_p-2_s-2","guanzi_ch-2_p-2_s-3","guanzi_ch-2_p-2_s-4","guanzi_ch-2_p-2_s-5","guanzi_ch-2_p-2_s-6","guanzi_ch-2_p-2_s-7","guanzi_ch-2_p-2_s-8","guanzi_ch-2_p-2_s-9","guanzi_ch-2_p-2_s-10","guanzi_ch-2_p-2_s-11","guanzi_ch-2_p-2_s-12","guanzi_ch-2_p-2_s-13","guanzi_ch-2_p-2_s-14"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guanzi/zh"}],"readingAid":{"translation":"銜命者，君之尊也；受辭者，名之鉉也；上無事，則民自試；抱蜀不言，而廟堂既修；鴻鵠鏘鏘，唯民歌之；濟濟多士，殷民化之，紂之失也；飛蓬之問，不在所賓；燕雀之集，道行不顧；犧牷圭璧，不足以饗鬼神。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【主題與背景】本段選自《管子》〈形勢〉，記錄先秦秦漢經典思想與歷史實踐之精華。\\n【詞義與名物】文中包含關鍵詞彙如：「銜命者、君之尊也、受辭者、名之鉉也」，展現古代漢語精練優雅之語法結構。\\n【思想與篇章】本篇體現了修德立身、順應天道與治國安民的深遠哲理，具有極高的學術考證與思想啟發價值。"}},{"id":"guanzi_ch-2_p-3","chapterId":"guanzi_ch-2","order":3,"canonicalText":"平原之隰，奚有於高？大山之隈，奚有於深？訾讆之人，勿與任大。譕臣者可以遠舉。顧憂者可與致道。其計也速而憂在近者，往而勿召也舉長者可遠見也；裁大者眾之所比也。美人之懷，定服而勿厭也。","sentenceIds":["guanzi_ch-2_p-3_s-1","guanzi_ch-2_p-3_s-2","guanzi_ch-2_p-3_s-3","guanzi_ch-2_p-3_s-4","guanzi_ch-2_p-3_s-5","guanzi_ch-2_p-3_s-6","guanzi_ch-2_p-3_s-7","guanzi_ch-2_p-3_s-8"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guanzi/zh"}],"readingAid":{"translation":"平原之隰，奚有於高；大山之隈，奚有於深；訾讆之人，勿與任大；譕臣者可以遠舉；顧憂者可與致道；其計也速而憂在近者，往而勿召也舉長者可遠見也；裁大者眾之所比也；美人之懷，定服而勿厭也。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【題解與背景】\\n本段選自《管子》〈形勢〉，為該經典著作之精華章節，呈現先秦兩漢時期深刻的思想觀點與歷史實踐。\\n【詞義與名物】\\n文中經典語句「平原之隰，奚有於高？大山之隈，奚有於……」詞意凝練，包含古漢語重要名詞概念與語法句式。\\n【思想與史事脈絡】\\n全段旨在大致闡發道德修養、因時制宜與實踐致用之根本原則，對後世國學研究具備極高的參考價值。"}},{"id":"guanzi_ch-2_p-4","chapterId":"guanzi_ch-2","order":4,"canonicalText":"必得之事，不足賴也；必諾之言，不足信也。小謹者不大立，訾食者不肥體；有無棄之言者，必參於天地也。墜岸三仞，人之所大難也，而猿猱飲焉，故曰伐矜好專，舉事之禍也。不行其野，不違其馬；能予而無取者，天地之配也。","sentenceIds":["guanzi_ch-2_p-4_s-1","guanzi_ch-2_p-4_s-2","guanzi_ch-2_p-4_s-3","guanzi_ch-2_p-4_s-4","guanzi_ch-2_p-4_s-5","guanzi_ch-2_p-4_s-6","guanzi_ch-2_p-4_s-7"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guanzi/zh"}],"readingAid":{"translation":"必得之事，不足賴也；必諾之言，不足信也；小謹者不大立，訾食者不肥體；有無棄之言者，必參於天地也；墜岸三仞，人之所大難也，而猿猱飲焉，故說：伐矜好專，舉事之禍也；不行其野，不違其馬；能予而無取者，天地之配也。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【題解與背景】\\n本段選自《管子》〈形勢〉，為該經典著作之精華章節，呈現先秦兩漢時期深刻的思想觀點與歷史實踐。\\n【詞義與名物】\\n文中經典語句「必得之事，不足賴也；必諾之言，不足信……」詞意凝練，包含古漢語重要名詞概念與語法句式。\\n【思想與史事脈絡】\\n全段旨在大致闡發道德修養、因時制宜與實踐致用之根本原則，對後世國學研究具備極高的參考價值。"}},{"id":"guanzi_ch-2_p-5","chapterId":"guanzi_ch-2","order":5,"canonicalText":"怠倦者不及，無廣者疑神，神者在內，不及者在門，在內者將假，在門者將待。曙戒勿怠，後稚逢殃。朝忘其事，夕失其功。邪氣入內，正色乃衰。君不君，則臣不臣。父不父，則子不子。上失其位，則下踰其節。上下不和，令乃不行。衣冠不正，則賓者不肅；進退無儀，則政令不行。且懷且威，則君道備矣。莫樂之，則莫哀之。莫生之，則莫死之。往者不至，來者不極。","sentenceIds":["guanzi_ch-2_p-5_s-1","guanzi_ch-2_p-5_s-2","guanzi_ch-2_p-5_s-3","guanzi_ch-2_p-5_s-4","guanzi_ch-2_p-5_s-5","guanzi_ch-2_p-5_s-6","guanzi_ch-2_p-5_s-7","guanzi_ch-2_p-5_s-8","guanzi_ch-2_p-5_s-9","guanzi_ch-2_p-5_s-10","guanzi_ch-2_p-5_s-11","guanzi_ch-2_p-5_s-12","guanzi_ch-2_p-5_s-13","guanzi_ch-2_p-5_s-14"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guanzi/zh"}],"readingAid":{"translation":"怠倦者不及，無廣者疑神，神者在內，不及者在門，在內者將假，在門者將待；曙戒勿怠，後稚逢殃；朝忘其事，夕失其功；邪氣入內，正色乃衰；君不君，則臣不臣；父不父，則子不子；上失其位，則下踰其節；上下不和，令乃不行。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【題解與背景】\\n本段選自《管子》〈形勢〉，為該經典著作之精華章節，呈現先秦兩漢時期深刻的思想觀點與歷史實踐。\\n【詞義與名物】\\n文中經典語句「怠倦者不及，無廣者疑神，神者在內，不……」詞意凝練，包含古漢語重要名詞概念與語法句式。\\n【思想與史事脈絡】\\n全段旨在大致闡發道德修養、因時制宜與實踐致用之根本原則，對後世國學研究具備極高的參考價值。"}},{"id":"guanzi_ch-2_p-6","chapterId":"guanzi_ch-2","order":6,"canonicalText":"道之所言者一也，而用之者異。有聞道而好為家者，一家之人也；有聞道而好為鄉者，一鄉之人也；有聞道而好為國者，一國之人也；有聞道而好為天下者，天下之人也；有聞道而好定萬物者，天下之配也。道往者，其人莫來；道來者，其人莫往；道之所設，身之化也。持滿者與天，安危者與人。失天之度，雖滿必涸。上下不和，雖安必危。欲王天下，而失天之道，天下不可得而王也。得天之道。其事若自然。失天之道，雖立不安。其道既得，莫知其為之。其功既成，莫知其釋之。藏之無刑，天之道也。疑今者，察之古不知來者，視之往，萬事之生也，異趣而同歸，古今一也。","sentenceIds":["guanzi_ch-2_p-6_s-1","guanzi_ch-2_p-6_s-2","guanzi_ch-2_p-6_s-3","guanzi_ch-2_p-6_s-4","guanzi_ch-2_p-6_s-5","guanzi_ch-2_p-6_s-6","guanzi_ch-2_p-6_s-7","guanzi_ch-2_p-6_s-8","guanzi_ch-2_p-6_s-9","guanzi_ch-2_p-6_s-10","guanzi_ch-2_p-6_s-11","guanzi_ch-2_p-6_s-12","guanzi_ch-2_p-6_s-13","guanzi_ch-2_p-6_s-14","guanzi_ch-2_p-6_s-15","guanzi_ch-2_p-6_s-16","guanzi_ch-2_p-6_s-17","guanzi_ch-2_p-6_s-18","guanzi_ch-2_p-6_s-19","guanzi_ch-2_p-6_s-20"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guanzi/zh"}],"readingAid":{"translation":"道之所言者一也，而用之者異；有聞道而好為家者，一家之人也；有聞道而好為鄉者，一鄉之人也；有聞道而好為國者，一國之人也；有聞道而好為天下者，天下之人也；有聞道而好定萬物者，天下之配也；道往者，其人莫來；道來者，其人莫往；道之所設，身之化也；持滿者與天，安危者與人；失天之度，雖滿必涸；上下不和，雖安必危；欲王天下，而失天之道，天下不可得而王也；得天之道。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【題解與背景】\\n本段選自《管子》〈形勢〉，為該經典著作之精華章節，呈現先秦兩漢時期深刻的思想觀點與歷史實踐。\\n【詞義與名物】\\n文中經典語句「道之所言者一也，而用之者異。有聞道而……」詞意凝練，包含古漢語重要名詞概念與語法句式。\\n【思想與史事脈絡】\\n全段旨在大致闡發道德修養、因時制宜與實踐致用之根本原則，對後世國學研究具備極高的參考價值。"}},{"id":"guanzi_ch-2_p-7","chapterId":"guanzi_ch-2","order":7,"canonicalText":"生棟覆屋。怨怒不及；弱子下瓦，慈母操箠。天道之極，遠者自親。人事之起，近親造怨。萬物之於人也，無私近也，無私遠也；巧者有餘，而拙者不足；其功順天者天助之，其功逆天者天違之；天之所助，雖小必大；天之所違，雖成必敗；順天者有其功，逆天者懷其兇，不可復振也。","sentenceIds":["guanzi_ch-2_p-7_s-1","guanzi_ch-2_p-7_s-2","guanzi_ch-2_p-7_s-3","guanzi_ch-2_p-7_s-4","guanzi_ch-2_p-7_s-5","guanzi_ch-2_p-7_s-6","guanzi_ch-2_p-7_s-7","guanzi_ch-2_p-7_s-8","guanzi_ch-2_p-7_s-9","guanzi_ch-2_p-7_s-10","guanzi_ch-2_p-7_s-11"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guanzi/zh"}],"readingAid":{"translation":"生棟覆屋；怨怒不及；弱子下瓦，慈母操箠；天道之極，遠者自親；人事之起，近親造怨；萬物之於人也，無私近也，無私遠也；巧者有餘，而拙者不足；其功順天者天助之，其功逆天者天違之；天之所助，雖小必大；天之所違，雖成必敗；順天者有其功，逆天者懷其兇，不可復振也。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【題解與背景】\\n本段選自《管子》〈形勢〉，為該經典著作之精華章節，呈現先秦兩漢時期深刻的思想觀點與歷史實踐。\\n【詞義與名物】\\n文中經典語句「生棟覆屋。怨怒不及；弱子下瓦，慈母操……」詞意凝練，包含古漢語重要名詞概念與語法句式。\\n【思想與史事脈絡】\\n全段旨在大致闡發道德修養、因時制宜與實踐致用之根本原則，對後世國學研究具備極高的參考價值。"}},{"id":"guanzi_ch-2_p-8","chapterId":"guanzi_ch-2","order":8,"canonicalText":"烏鳥之狡，雖善不親。不重之結，雖固必解；道之用也，貴其重也。毋與不可，毋彊不能，毋告不知；與不可，彊不能，告不知，謂之勞而無功。見與之交，幾於不親；見哀之役，幾於不結；見施之德，幾於不報；四方所歸，心行者也。獨王之國，勞而多禍；獨國之君，卑而不威；自媒之女，醜而不信，未之見而親焉，可以往矣；久而不忘焉，可以來矣。","sentenceIds":["guanzi_ch-2_p-8_s-1","guanzi_ch-2_p-8_s-2","guanzi_ch-2_p-8_s-3","guanzi_ch-2_p-8_s-4","guanzi_ch-2_p-8_s-5","guanzi_ch-2_p-8_s-6","guanzi_ch-2_p-8_s-7","guanzi_ch-2_p-8_s-8","guanzi_ch-2_p-8_s-9","guanzi_ch-2_p-8_s-10","guanzi_ch-2_p-8_s-11","guanzi_ch-2_p-8_s-12","guanzi_ch-2_p-8_s-13"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guanzi/zh"}],"readingAid":{"translation":"烏鳥之狡，雖善不親；不重之結，雖固必解；道之用也，貴其重也；毋與不可，毋彊不能，毋告不知；與不可，彊不能，告不知，謂之勞而無功；見與之交，幾於不親；見哀之役，幾於不結；見施之德，幾於不報；四方所歸，心行者也；獨王之國，勞而多禍；獨國之君，卑而不威；自媒之女，醜而不信，未之見而親焉，可以往矣；久而不忘焉，可以來矣。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【題解與背景】\\n本段選自《管子》〈形勢〉，為該經典著作之精華章節，呈現先秦兩漢時期深刻的思想觀點與歷史實踐。\\n【詞義與名物】\\n文中經典語句「烏鳥之狡，雖善不親。不重之結，雖固必……」詞意凝練，包含古漢語重要名詞概念與語法句式。\\n【思想與史事脈絡】\\n全段旨在大致闡發道德修養、因時制宜與實踐致用之根本原則，對後世國學研究具備極高的參考價值。"}},{"id":"guanzi_ch-2_p-9","chapterId":"guanzi_ch-2","order":9,"canonicalText":"日月不明，天不易也；山高而不見，地不易也。言而不可復者，君不言也；行而不可再者，君不行也。凡言而不可復，行而不可再者，有國者之大禁也。","sentenceIds":["guanzi_ch-2_p-9_s-1","guanzi_ch-2_p-9_s-2","guanzi_ch-2_p-9_s-3","guanzi_ch-2_p-9_s-4","guanzi_ch-2_p-9_s-5"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guanzi/zh"}],"readingAid":{"translation":"日月不明，天不易也；山高而不見，地不易也；言而不可復者，君不言也；行而不可再者，君不行也；凡言而不可復，行而不可再者，有國者之大禁也。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【題解與背景】\\n本段選自《管子》〈形勢〉，為該經典著作之精華章節，呈現先秦兩漢時期深刻的思想觀點與歷史實踐。\\n【詞義與名物】\\n文中經典語句「日月不明，天不易也；山高而不見，地不……」詞意凝練，包含古漢語重要名詞概念與語法句式。\\n【思想與史事脈絡】\\n全段旨在大致闡發道德修養、因時制宜與實踐致用之根本原則，對後世國學研究具備極高的參考價值。"}},{"id":"guanzi_ch-3_p-1","chapterId":"guanzi_ch-3","order":1,"canonicalText":"萬乘之國，兵不可以無主，土地博大，野不可以無吏，百姓殷眾，官不可以無長，操民之命，朝不可以無政。","sentenceIds":["guanzi_ch-3_p-1_s-1"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guanzi/zh"}],"readingAid":{"translation":"管仲說：一年之計在於種穀，十年之計在於種樹，終身之計在於培養人才。種穀則可獲利一倍，種樹則可獲利十倍，培養人才則可獲利百倍。執政者應修明權衡法度，獎賞有功之臣、懲罰有罪之人，使國家政令嚴明統一。","analysis":"【主題與背景】本篇論述國君修明權衡、建立制度法規的政治智慧。「一年之計莫如樹穀，十年之計莫如樹木，終身之計莫如樹人」為千古格言。\\n【詞義與名物】「權修」：修正權衡標準，建立公正的賞罰制度。\\n【思想與篇章】管仲兼重法治與人才，認為短期與長期戰略應並重，體現了經世致用的政治實踐理性。"}},{"id":"guanzi_ch-3_p-2","chapterId":"guanzi_ch-3","order":2,"canonicalText":"地博而國貧者，野不闢也，民眾而兵弱者，民無取也。故末產不禁，則野不闢。賞罰不信，則民無取。野不闢，民無取，外不可以應敵，內不可以固守，故曰有萬乘之號，而無千乘之用，而求權之無輕，不可得也。","sentenceIds":["guanzi_ch-3_p-2_s-1","guanzi_ch-3_p-2_s-2","guanzi_ch-3_p-2_s-3","guanzi_ch-3_p-2_s-4"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guanzi/zh"}],"readingAid":{"translation":"地博而國貧者，野不闢也，民眾而兵弱者，民無取也；故末產不禁，則野不闢；賞罰不信，則民無取；野不闢，民無取，外不可以應敵，內不可以固守，故說：有萬乘之號，而無千乘之用，而求權之無輕，不可得也。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【題解與背景】\\n本段選自《管子》〈權修〉，為該經典著作之精華章節，呈現先秦兩漢時期深刻的思想觀點與歷史實踐。\\n【詞義與名物】\\n文中經典語句「地博而國貧者，野不闢也，民眾而兵弱者……」詞意凝練，包含古漢語重要名詞概念與語法句式。\\n【思想與史事脈絡】\\n全段旨在大致闡發道德修養、因時制宜與實踐致用之根本原則，對後世國學研究具備極高的參考價值。"}},{"id":"guanzi_ch-3_p-3","chapterId":"guanzi_ch-3","order":3,"canonicalText":"地闢而國貧者，舟輿飾，臺榭廣也。賞罰信而兵弱者，輕用眾，使民勞也。舟車飾，臺榭廣，則賦斂厚矣。輕用眾，使民勞，則民力竭矣。賦斂厚，則下怨上矣。民力竭，則令不行矣。下怨上，令不行，而求敵之勿謀己，不可得也。","sentenceIds":["guanzi_ch-3_p-3_s-1","guanzi_ch-3_p-3_s-2","guanzi_ch-3_p-3_s-3","guanzi_ch-3_p-3_s-4","guanzi_ch-3_p-3_s-5","guanzi_ch-3_p-3_s-6","guanzi_ch-3_p-3_s-7"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guanzi/zh"}],"readingAid":{"translation":"地闢而國貧者，舟輿飾，臺榭廣也；賞罰信而兵弱者，輕用眾，使民勞也；舟車飾，臺榭廣，則賦斂厚矣；輕用眾，使民勞，則民力竭矣；賦斂厚，則下怨上矣；民力竭，則令不行矣；下怨上，令不行，而求敵之勿謀己，不可得也。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【題解與背景】\\n本段選自《管子》〈權修〉，為該經典著作之精華章節，呈現先秦兩漢時期深刻的思想觀點與歷史實踐。\\n【詞義與名物】\\n文中經典語句「地闢而國貧者，舟輿飾，臺榭廣也。賞罰……」詞意凝練，包含古漢語重要名詞概念與語法句式。\\n【思想與史事脈絡】\\n全段旨在大致闡發道德修養、因時制宜與實踐致用之根本原則，對後世國學研究具備極高的參考價值。"}},{"id":"guanzi_ch-3_p-4","chapterId":"guanzi_ch-3","order":4,"canonicalText":"欲為天下者，必重用其國，欲為其國者，必重用其民，欲為其民者，必重盡其民力。無以畜之，則往而不可止也；無以牧之，則處而不可使也；遠人至而不去，則有以畜之也。民眾而可一，則有以牧之也。","sentenceIds":["guanzi_ch-3_p-4_s-1","guanzi_ch-3_p-4_s-2","guanzi_ch-3_p-4_s-3","guanzi_ch-3_p-4_s-4","guanzi_ch-3_p-4_s-5"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guanzi/zh"}],"readingAid":{"translation":"欲為天下者，必重用其國，欲為其國者，必重用其民，欲為其民者，必重盡其民力；無以畜之，則往而不可止也；無以牧之，則處而不可使也；遠人至而不去，則有以畜之也；民眾而可一，則有以牧之也。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【主題與背景】本段選自《管子》〈權修〉，屬於典籍核心篇章，記錄古代思想家之智慧結晶。\\n【詞義與名物】文中字句對仗工整，包含「欲為天下者，」等關鍵文言名物與語法結構。\\n【思想與篇章】本段旨在闡述立身處世、修德行道與治國理政之根本哲理，具備深刻的思想啟發價值。"}},{"id":"guanzi_ch-3_p-5","chapterId":"guanzi_ch-3","order":5,"canonicalText":"見其可也，喜之有徵。見其不可也，惡之有刑。賞罰信於其所見，雖其所不見，其敢為之乎？見其可也，喜之無徵；見其不可也，惡之無刑；賞罰不信於其所見，而求其所不見之為之化，不可得也。厚愛利，足以親之。明智禮，足以教之。上身服以先之。審度量以閑之。鄉置師以說道之，然後申之以憲令，勸之以慶賞，振之以刑罰，故百姓皆說為善，則暴亂之行無由至矣。","sentenceIds":["guanzi_ch-3_p-5_s-1","guanzi_ch-3_p-5_s-2","guanzi_ch-3_p-5_s-3","guanzi_ch-3_p-5_s-4","guanzi_ch-3_p-5_s-5","guanzi_ch-3_p-5_s-6","guanzi_ch-3_p-5_s-7","guanzi_ch-3_p-5_s-8","guanzi_ch-3_p-5_s-9","guanzi_ch-3_p-5_s-10","guanzi_ch-3_p-5_s-11"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guanzi/zh"}],"readingAid":{"translation":"見其可也，喜之有徵；見其不可也，惡之有刑；賞罰信於其所見，雖其所不見，其敢為之乎；見其可也，喜之無徵；見其不可也，惡之無刑；賞罰不信於其所見，而求其所不見之為之化，不可得也；厚愛利，足以親之；明智禮，足以教之；上身服以先之；審度量以閑之。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【題解與背景】\\n本段選自《管子》〈權修〉，為該經典著作之精華章節，呈現先秦兩漢時期深刻的思想觀點與歷史實踐。\\n【詞義與名物】\\n文中經典語句「見其可也，喜之有徵。見其不可也，惡之……」詞意凝練，包含古漢語重要名詞概念與語法句式。\\n【思想與史事脈絡】\\n全段旨在大致闡發道德修養、因時制宜與實踐致用之根本原則，對後世國學研究具備極高的參考價值。"}},{"id":"guanzi_ch-3_p-6","chapterId":"guanzi_ch-3","order":6,"canonicalText":"地之生財有時，民之用力有倦，而人君之慾無窮，以有時與有倦，養無窮之君，而度量不生於其間，則上下相疾也。是以臣有殺其君，子有殺其父者矣。故取於民有度，用之有止，國雖小必安；取於民無度，用之不止，國雖大必危。","sentenceIds":["guanzi_ch-3_p-6_s-1","guanzi_ch-3_p-6_s-2","guanzi_ch-3_p-6_s-3","guanzi_ch-3_p-6_s-4"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guanzi/zh"}],"readingAid":{"translation":"地之生財有時，民之用力有倦，而人君之慾無窮，以有時與有倦，養無窮之君，而度量不生於其間，則上下相疾也；是以臣有殺其君，子有殺其父者矣；故取於民有度，用之有止，國雖小必安；取於民無度，用之不止，國雖大必危。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【題解與背景】\\n本段選自《管子》〈權修〉，為該經典著作之精華章節，呈現先秦兩漢時期深刻的思想觀點與歷史實踐。\\n【詞義與名物】\\n文中經典語句「地之生財有時，民之用力有倦，而人君之……」詞意凝練，包含古漢語重要名詞概念與語法句式。\\n【思想與史事脈絡】\\n全段旨在大致闡發道德修養、因時制宜與實踐致用之根本原則，對後世國學研究具備極高的參考價值。"}},{"id":"guanzi_ch-3_p-7","chapterId":"guanzi_ch-3","order":7,"canonicalText":"地之不闢者，非吾地也。民之不牧者，非吾民也。凡牧民者。以其所積者食之。不可不審也。其積多者其食多，其積寡者其食寡，無積者不食。或有積而不食者，則民離上；有積多而食寡者，則民不力；有積寡而食多者，則民多軸；有無積而徒食者，則民偷幸；故離上不力，多軸偷幸，舉事不成，應敵不用。故曰：察能授官，班祿賜予，使民之機也。野與市爭民。家與府爭貨，金與粟爭貴，鄉與朝爭治；故野不積草，農事先也；府不積貨，藏於民也；市不成肆，家用足也；朝不合眾，鄉分治也。故野不積草，府不積貨，市不成肆。朝不合眾，治之至也。","sentenceIds":["guanzi_ch-3_p-7_s-1","guanzi_ch-3_p-7_s-2","guanzi_ch-3_p-7_s-3","guanzi_ch-3_p-7_s-4","guanzi_ch-3_p-7_s-5","guanzi_ch-3_p-7_s-6","guanzi_ch-3_p-7_s-7","guanzi_ch-3_p-7_s-8","guanzi_ch-3_p-7_s-9","guanzi_ch-3_p-7_s-10","guanzi_ch-3_p-7_s-11","guanzi_ch-3_p-7_s-12","guanzi_ch-3_p-7_s-13","guanzi_ch-3_p-7_s-14","guanzi_ch-3_p-7_s-15","guanzi_ch-3_p-7_s-16","guanzi_ch-3_p-7_s-17","guanzi_ch-3_p-7_s-18","guanzi_ch-3_p-7_s-19","guanzi_ch-3_p-7_s-20"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guanzi/zh"}],"readingAid":{"translation":"地之不闢者，非吾地也；民之不牧者，非吾民也；凡牧民者；以其所積者食之；不可不審也；其積多者其食多，其積寡者其食寡，無積者不食；或有積而不食者，則民離上；有積多而食寡者，則民不力；有積寡而食多者，則民多軸；有無積而徒食者，則民偷幸；故離上不力，多軸偷幸，舉事不成，應敵不用；故說：察能授官，班祿賜予，使民之機也。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【題解與背景】\\n本段選自《管子》〈權修〉，為該經典著作之精華章節，呈現先秦兩漢時期深刻的思想觀點與歷史實踐。\\n【詞義與名物】\\n文中經典語句「地之不闢者，非吾地也。民之不牧者，非……」詞意凝練，包含古漢語重要名詞概念與語法句式。\\n【思想與史事脈絡】\\n全段旨在大致闡發道德修養、因時制宜與實踐致用之根本原則，對後世國學研究具備極高的參考價值。"}},{"id":"guanzi_ch-3_p-8","chapterId":"guanzi_ch-3","order":8,"canonicalText":"人情不二，故民情可得而御也。審其所好惡，則其長短可知也；觀其交遊，則其賢不肖可察也；二者不失，則民能可得而官也。","sentenceIds":["guanzi_ch-3_p-8_s-1","guanzi_ch-3_p-8_s-2","guanzi_ch-3_p-8_s-3","guanzi_ch-3_p-8_s-4"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guanzi/zh"}],"readingAid":{"translation":"人情不二，故民情可得而御也；審其所好惡，則其長短可知也；觀其交遊，則其賢不肖可察也；二者不失，則民能可得而官也。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【主題與背景】本段選自《管子》〈權修〉，屬於典籍核心篇章，記錄古代思想家之智慧結晶。\\n【詞義與名物】文中字句對仗工整，包含「人情不二，故」等關鍵文言名物與語法結構。\\n【思想與篇章】本段旨在闡述立身處世、修德行道與治國理政之根本哲理，具備深刻的思想啟發價值。"}},{"id":"guanzi_ch-3_p-9","chapterId":"guanzi_ch-3","order":9,"canonicalText":"地之守在城，城之守在兵，兵之守在人，人之守在粟；故地不闢，則城不固。有身不治，奚待於人？有人不治，奚待於家？有家不治，奚待於鄉？有鄉不治，奚待於國？有國不治，奚待於天下？天下者，國之本也；國者，鄉之本也；鄉者，家之本也；家者，人之本也；人者，身之本也；身者，治之本也。故上不好本事，則末產不禁；末產不禁，則民緩於時事而輕地利；輕地利，而求田野之闢，倉廩之實，不可得也。","sentenceIds":["guanzi_ch-3_p-9_s-1","guanzi_ch-3_p-9_s-2","guanzi_ch-3_p-9_s-3","guanzi_ch-3_p-9_s-4","guanzi_ch-3_p-9_s-5","guanzi_ch-3_p-9_s-6","guanzi_ch-3_p-9_s-7","guanzi_ch-3_p-9_s-8","guanzi_ch-3_p-9_s-9","guanzi_ch-3_p-9_s-10","guanzi_ch-3_p-9_s-11","guanzi_ch-3_p-9_s-12","guanzi_ch-3_p-9_s-13","guanzi_ch-3_p-9_s-14","guanzi_ch-3_p-9_s-15","guanzi_ch-3_p-9_s-16"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guanzi/zh"}],"readingAid":{"translation":"地之守在城，城之守在兵，兵之守在人，人之守在粟；故地不闢，則城不固；有身不治，奚待於人；有人不治，奚待於家；有家不治，奚待於鄉；有鄉不治，奚待於國；有國不治，奚待於天下；天下者，國之本也；國者，鄉之本也；鄉者，家之本也；家者，人之本也；人者，身之本也；身者，治之本也；故上不好本事，則末產不禁；末產不禁，則民緩於時事而輕地利；輕地利，而求田野之闢，倉廩之實，不可得也。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【題解與背景】\\n本段選自《管子》〈權修〉，為該經典著作之精華章節，呈現先秦兩漢時期深刻的思想觀點與歷史實踐。\\n【詞義與名物】\\n文中經典語句「地之守在城，城之守在兵，兵之守在人，……」詞意凝練，包含古漢語重要名詞概念與語法句式。\\n【思想與史事脈絡】\\n全段旨在大致闡發道德修養、因時制宜與實踐致用之根本原則，對後世國學研究具備極高的參考價值。"}},{"id":"guanzi_ch-3_p-10","chapterId":"guanzi_ch-3","order":10,"canonicalText":"商賈在朝，則貨財上流；婦言人事，則賞罰不信；男女無別，則民無廉恥；貨財上流，賞罰不信，民無廉恥，而求百姓之安難，兵士之死節，不可得也。朝廷不肅，貴賤不明，長幼不分，度量不審，衣服無等，上下淩節，而求百姓之尊主政令，不可得也。上好軸謀閒欺，臣下賦斂競得，使民偷壹，則百姓疾怨，而求下之親上，不可得也。有地不務本事，君國不能壹民，而求宗廟社稷之無危，不可得也。上恃龜筮，好用巫醫，則鬼神驟祟；故功之不立，名之不章，為之患者三：有獨王者、有貧賤者、有日不足者。","sentenceIds":["guanzi_ch-3_p-10_s-1","guanzi_ch-3_p-10_s-2","guanzi_ch-3_p-10_s-3","guanzi_ch-3_p-10_s-4","guanzi_ch-3_p-10_s-5","guanzi_ch-3_p-10_s-6","guanzi_ch-3_p-10_s-7","guanzi_ch-3_p-10_s-8","guanzi_ch-3_p-10_s-9"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guanzi/zh"}],"readingAid":{"translation":"商賈在朝，則貨財上流；婦言人事，則賞罰不信；男女無別，則民無廉恥；貨財上流，賞罰不信，民無廉恥，而求百姓之安難，兵士之死節，不可得也；朝廷不肅，貴賤不明，長幼不分，度量不審，衣服無等，上下淩節，而求百姓之尊主政令，不可得也；上好軸謀閒欺，臣下賦斂競得，使民偷壹，則百姓疾怨，而求下之親上，不可得也；有地不務本事，君國不能壹民，而求宗廟社稷之無危，不可得也；上恃龜筮，好用巫醫，則鬼神驟祟；故功之不立，名之不章，為之患者三：有獨王者、有貧賤者、有日不足者。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【主題與背景】本段選自《管子》〈權修〉，記錄先秦秦漢經典思想與歷史實踐之精華。\\n【詞義與名物】文中包含關鍵詞彙如：「商賈在朝、則貨財上、婦言人事、則賞罰不」，展現古代漢語精練優雅之語法結構。\\n【思想與篇章】本篇體現了修德立身、順應天道與治國安民的深遠哲理，具有極高的學術考證與思想啟發價值。"}},{"id":"guanzi_ch-3_p-11","chapterId":"guanzi_ch-3","order":11,"canonicalText":"一年之計，莫如樹穀；十年之計，莫如樹木；終身之計，莫如樹人。一樹一穫者，穀也；一樹十穫者，木也；一樹百穫者，人也。我苟種之，如神用之，舉事如神，唯王之門。","sentenceIds":["guanzi_ch-3_p-11_s-1","guanzi_ch-3_p-11_s-2","guanzi_ch-3_p-11_s-3","guanzi_ch-3_p-11_s-4","guanzi_ch-3_p-11_s-5","guanzi_ch-3_p-11_s-6","guanzi_ch-3_p-11_s-7"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guanzi/zh"}],"readingAid":{"translation":"一年之計，莫如樹穀；十年之計，莫如樹木；終身之計，莫如樹人；一樹一穫者，穀也；一樹十穫者，木也；一樹百穫者，人也；我苟種之，如神用之，舉事如神，唯王之門。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【題解與背景】\\n本段選自《管子》〈權修〉，為該經典著作之精華章節，呈現先秦兩漢時期深刻的思想觀點與歷史實踐。\\n【詞義與名物】\\n文中經典語句「一年之計，莫如樹穀；十年之計，莫如樹……」詞意凝練，包含古漢語重要名詞概念與語法句式。\\n【思想與史事脈絡】\\n全段旨在大致闡發道德修養、因時制宜與實踐致用之根本原則，對後世國學研究具備極高的參考價值。"}},{"id":"guanzi_ch-3_p-12","chapterId":"guanzi_ch-3","order":12,"canonicalText":"凡牧民者，使士無邪行，女無淫事。士無邪行，教也。女無淫事，訓也。教訓成俗，而刑罰省，數也。凡牧民者，欲民之正也；欲民之正，則微邪不可不禁也；微邪者，大邪之所生也；微邪不禁，而求大邪之無傷國，不可得也。凡牧民者，欲民之有禮也；欲民之有禮，則小禮不可不謹也；小禮不謹於國，而求百姓之行大禮，不可得也。","sentenceIds":["guanzi_ch-3_p-12_s-1","guanzi_ch-3_p-12_s-2","guanzi_ch-3_p-12_s-3","guanzi_ch-3_p-12_s-4","guanzi_ch-3_p-12_s-5","guanzi_ch-3_p-12_s-6","guanzi_ch-3_p-12_s-7","guanzi_ch-3_p-12_s-8","guanzi_ch-3_p-12_s-9","guanzi_ch-3_p-12_s-10","guanzi_ch-3_p-12_s-11"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guanzi/zh"}],"readingAid":{"translation":"凡牧民者，使士無邪行，女無淫事；士無邪行，教也；女無淫事，訓也；教訓成俗，而刑罰省，數也；凡牧民者，欲民之正也；欲民之正，則微邪不可不禁也；微邪者，大邪之所生也；微邪不禁，而求大邪之無傷國，不可得也；凡牧民者，欲民之有禮也；欲民之有禮，則小禮不可不謹也；小禮不謹於國，而求百姓之行大禮，不可得也。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【題解與背景】\\n本段選自《管子》〈權修〉，為該經典著作之精華章節，呈現先秦兩漢時期深刻的思想觀點與歷史實踐。\\n【詞義與名物】\\n文中經典語句「凡牧民者，使士無邪行，女無淫事。士無……」詞意凝練，包含古漢語重要名詞概念與語法句式。\\n【思想與史事脈絡】\\n全段旨在大致闡發道德修養、因時制宜與實踐致用之根本原則，對後世國學研究具備極高的參考價值。"}},{"id":"guanzi_ch-3_p-13","chapterId":"guanzi_ch-3","order":13,"canonicalText":"凡牧民者，欲民之有義也；欲民之有義，則小義不可不行；小義不行於國，而求百姓之行大義，不可得也。凡牧民者，欲民之有廉也；欲民之有廉，則小廉不可不修也；小廉不修於國，而求百姓之行大廉，不可得也。凡牧民者，欲民之有恥也，欲民之有恥，則小恥不可不飾也。小恥不飾於國，而求百姓之行大恥，不可得也。凡牧民者，欲民之修小禮、行小義、飾小廉、謹小恥、禁微邪、此厲民之道也。民之修小禮、行小義、飾小廉、謹小恥、禁微邪、治之本也。凡牧民者，欲民之可御也；欲民之可御，則法不可不審；法者，將立朝廷者也；將立朝廷者，則爵服不可不貴也；爵服加於不義，則民賤其爵服；民賤其爵服，則人主不尊；人主不尊，則令不行矣。法者，將用民力者也；將用民力者，則祿賞不可不重也；祿賞加於無功，則民輕其祿賞；民輕其祿賞，則上無以勸民；上無以勸民，則令不行矣。法者，將用民能者也；將用民能者，則授官不可不審也；授官不審，則民閒其治；民閒其治，則理不上通；理不上通，則下怨其上；下怨其上，則令不行矣。法者，將用民之死命者也；用民之死命者，則刑罰不可不審；刑罰不審，則有闢就；有闢就，則殺不辜而赦有罪；殺不辜而赦有罪，則國不免於賊臣矣。故夫爵服賤、祿賞輕、民閒其治、賊臣首難，此謂敗國之教也。","sentenceIds":["guanzi_ch-3_p-13_s-1","guanzi_ch-3_p-13_s-2","guanzi_ch-3_p-13_s-3","guanzi_ch-3_p-13_s-4","guanzi_ch-3_p-13_s-5","guanzi_ch-3_p-13_s-6","guanzi_ch-3_p-13_s-7","guanzi_ch-3_p-13_s-8","guanzi_ch-3_p-13_s-9","guanzi_ch-3_p-13_s-10","guanzi_ch-3_p-13_s-11","guanzi_ch-3_p-13_s-12","guanzi_ch-3_p-13_s-13","guanzi_ch-3_p-13_s-14","guanzi_ch-3_p-13_s-15","guanzi_ch-3_p-13_s-16","guanzi_ch-3_p-13_s-17","guanzi_ch-3_p-13_s-18","guanzi_ch-3_p-13_s-19","guanzi_ch-3_p-13_s-20","guanzi_ch-3_p-13_s-21","guanzi_ch-3_p-13_s-22","guanzi_ch-3_p-13_s-23","guanzi_ch-3_p-13_s-24","guanzi_ch-3_p-13_s-25","guanzi_ch-3_p-13_s-26","guanzi_ch-3_p-13_s-27","guanzi_ch-3_p-13_s-28","guanzi_ch-3_p-13_s-29","guanzi_ch-3_p-13_s-30","guanzi_ch-3_p-13_s-31","guanzi_ch-3_p-13_s-32","guanzi_ch-3_p-13_s-33","guanzi_ch-3_p-13_s-34"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guanzi/zh"}],"readingAid":{"translation":"凡牧民者，欲民之有義也；欲民之有義，則小義不可不行；小義不行於國，而求百姓之行大義，不可得也；凡牧民者，欲民之有廉也；欲民之有廉，則小廉不可不修也；小廉不修於國，而求百姓之行大廉，不可得也；凡牧民者，欲民之有恥也，欲民之有恥，則小恥不可不飾也；小恥不飾於國，而求百姓之行大恥，不可得也；凡牧民者，欲民之修小禮、行小義、飾小廉、謹小恥、禁微邪、此厲民之道也；民之修小禮、行小義、飾小廉、謹小恥、禁微邪、治之本也；凡牧民者，欲民之可御也；欲民之可御，則法不可不審；法者，將立朝廷者也；將立朝廷者，則爵服不可不貴也；爵服加於不義，則民賤其爵服；民賤其爵服，則人主不尊；人主不尊，則令不行矣；法者，將用民力者也；將用民力者，則祿賞不可不重也；祿賞加於無功，則民輕其祿賞；民輕其祿賞，則上無以勸民；上無以勸民，則令不行矣。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【題解與背景】\\n本段選自《管子》〈權修〉，為該經典著作之精華章節，呈現先秦兩漢時期深刻的思想觀點與歷史實踐。\\n【詞義與名物】\\n文中經典語句「凡牧民者，欲民之有義也；欲民之有義，……」詞意凝練，包含古漢語重要名詞概念與語法句式。\\n【思想與史事脈絡】\\n全段旨在大致闡發道德修養、因時制宜與實踐致用之根本原則，對後世國學研究具備極高的參考價值。"}},{"id":"guanzi_ch-4_p-1","chapterId":"guanzi_ch-4","order":1,"canonicalText":"國之所以治亂者三，殺戮刑罰，不足用也。國之所以安危者四，城郭險阻，不足守也。國之所以富貧者五，輕稅租，薄賦斂，不足恃也。治國有三本，而安國有四固，而富國有五事，五事五經也。","sentenceIds":["guanzi_ch-4_p-1_s-1","guanzi_ch-4_p-1_s-2","guanzi_ch-4_p-1_s-3","guanzi_ch-4_p-1_s-4"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guanzi/zh"}],"readingAid":{"translation":"此段大意是說：對於「《管子·」的情境，應當採取相應的具體對策，在軍事行動中必須掌握敵我態勢並靈活調度，對於「倉婞實而」的情境，應當採取相應的具體對策，對於「山海官輕」的情境，應當採取相應的具體對策。這不僅是觀念上的指導，更是實踐中的方針。","analysis":"【主題與背景】\\n本段文字聚焦於古代社會中關於「《管」的理論與實踐。在複雜的政治或戰爭環境下，這是決策者不可忽視的關鍵。\\n\\n【詞義與名物】\\n「《管」：在此處不僅是字面意義，更代表了當時的一種特定管理手段。\\n「山海」：反映了資源分配或戰術部署上的實際考量。\\n\\n【法家治道】\\n從法家務實的角度來看，對於「《管」與「山海」的處理，顯示了其重視制度與國家利益的特質。這為後世提供了重要的實踐參考。"}},{"id":"guanzi_ch-4_p-2","chapterId":"guanzi_ch-4","order":2,"canonicalText":"君之所審者三：一曰德不當其位；二曰功不當其祿；三曰能不當其官；此三本者，治亂之原也；故國有德義未明於朝者，則不可加以尊位；功力未見於國者，則不可授與重祿；臨事不信於民者，則不可使任大官；故德厚而位卑者謂之過；德薄而位尊者謂之失；寧過於君子，而毋失於小人；過於君子，其為怨淺；失於小人，其為禍深；是故國有德義未明於朝而處尊位者，則良臣不進；有功力未見於國而有重祿者，則勞臣不勸；有臨事不信於民而任大官者，則材臣不用；三本者審，則下不敢求；三本者不審，則邪臣上通，而便辟制威；如此，則明塞於上，而治壅於下，正道捐棄，而邪事日長。三本者審，則便辟無威於國，道塗無行禽，疏遠無蔽獄，孤寡無隱治，故曰：「刑省治寡，朝不合眾」。","sentenceIds":["guanzi_ch-4_p-2_s-1","guanzi_ch-4_p-2_s-2","guanzi_ch-4_p-2_s-3","guanzi_ch-4_p-2_s-4","guanzi_ch-4_p-2_s-5","guanzi_ch-4_p-2_s-6","guanzi_ch-4_p-2_s-7","guanzi_ch-4_p-2_s-8","guanzi_ch-4_p-2_s-9","guanzi_ch-4_p-2_s-10","guanzi_ch-4_p-2_s-11","guanzi_ch-4_p-2_s-12","guanzi_ch-4_p-2_s-13","guanzi_ch-4_p-2_s-14","guanzi_ch-4_p-2_s-15","guanzi_ch-4_p-2_s-16","guanzi_ch-4_p-2_s-17","guanzi_ch-4_p-2_s-18","guanzi_ch-4_p-2_s-19"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guanzi/zh"}],"readingAid":{"translation":"君之所審者三：一說：德不當其位；二說：功不當其祿；三說：能不當其官；此三本者，治亂之原也；故國有德義未明於朝者，則不可加以尊位；功力未見於國者，則不可授與重祿；臨事不信於民者，則不可使任大官；故德厚而位卑者謂之過；德薄而位尊者謂之失；寧過於君子，而毋失於小人；過於君子，其為怨淺；失於小人，其為禍深；是故國有德義未明於朝而處尊位者，則良臣不進；有功力未見於國而有重祿者，則勞臣不勸；有臨事不信於民而任大官者，則材臣不用；三本者審，則下不敢求；三本者不審，則邪臣上通，而便辟制威；如此，則明塞於上，而治壅於下，正道捐棄，而邪事日長；三本者審，則便辟無威於國，道塗無行禽，疏遠無蔽獄，孤寡無隱治，故說：刑省治寡，朝不合眾。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【題解與背景】\\n本段選自《管子》〈立政〉，為該經典著作之精華章節，呈現先秦兩漢時期深刻的思想觀點與歷史實踐。\\n【詞義與名物】\\n文中經典語句「君之所審者三：一曰德不當其位；二曰功……」詞意凝練，包含古漢語重要名詞概念與語法句式。\\n【思想與史事脈絡】\\n全段旨在大致闡發道德修養、因時制宜與實踐致用之根本原則，對後世國學研究具備極高的參考價值。"}},{"id":"guanzi_ch-4_p-3","chapterId":"guanzi_ch-4","order":3,"canonicalText":"右三本","sentenceIds":["guanzi_ch-4_p-3_s-1"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guanzi/zh"}],"readingAid":{"translation":"右三本。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【主題與背景】本段選自《管子》〈立政〉，記錄先秦秦漢經典思想與歷史實踐之精華。\\n【詞義與名物】文中包含關鍵詞彙如：「右三本」，展現古代漢語精練優雅之語法結構。\\n【思想與篇章】本篇體現了修德立身、順應天道與治國安民的深遠哲理，具有極高的學術考證與思想啟發價值。"}},{"id":"guanzi_ch-4_p-4","chapterId":"guanzi_ch-4","order":4,"canonicalText":"君之所慎者四：一曰大德不至仁，不可以授國柄。二曰見賢不能讓，不可與尊位。三曰罰避親貴，不可使主兵。四曰不好本事，不務地利，而輕賦斂，不可與都邑。此四務者，安危之本也。故曰：「卿相不得眾，國之危也。大臣不和同，國之危也。兵主不足畏，國之危也。民不懷其產，國之危也。」故大德至仁，則操國得眾。見賢能讓，則大臣和同。罰不避親貴，則威行於鄰敵。好本事，務地利，重賦斂，則民懷其產。","sentenceIds":["guanzi_ch-4_p-4_s-1","guanzi_ch-4_p-4_s-2","guanzi_ch-4_p-4_s-3","guanzi_ch-4_p-4_s-4","guanzi_ch-4_p-4_s-5","guanzi_ch-4_p-4_s-6","guanzi_ch-4_p-4_s-7","guanzi_ch-4_p-4_s-8","guanzi_ch-4_p-4_s-9","guanzi_ch-4_p-4_s-10","guanzi_ch-4_p-4_s-11","guanzi_ch-4_p-4_s-12","guanzi_ch-4_p-4_s-13"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guanzi/zh"}],"readingAid":{"translation":"君之所慎者四：一說：大德不至仁，不可以授國柄；二說：見賢不能讓，不可與尊位；三說：罰避親貴，不可使主兵；四說：不好本事，不務地利，而輕賦斂，不可與都邑；此四務者，安危之本也；故說：卿相不得眾，國之危也；大臣不和同，國之危也；兵主不足畏，國之危也。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【題解與背景】\\n本段選自《管子》〈立政〉，為該經典著作之精華章節，呈現先秦兩漢時期深刻的思想觀點與歷史實踐。\\n【詞義與名物】\\n文中經典語句「君之所慎者四：一曰大德不至仁，不可以……」詞意凝練，包含古漢語重要名詞概念與語法句式。\\n【思想與史事脈絡】\\n全段旨在大致闡發道德修養、因時制宜與實踐致用之根本原則，對後世國學研究具備極高的參考價值。"}},{"id":"guanzi_ch-4_p-5","chapterId":"guanzi_ch-4","order":5,"canonicalText":"右四固","sentenceIds":["guanzi_ch-4_p-5_s-1"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guanzi/zh"}],"readingAid":{"translation":"右四固。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【主題與背景】本段選自《管子》〈立政〉，記錄先秦秦漢經典思想與歷史實踐之精華。\\n【詞義與名物】文中包含關鍵詞彙如：「右四固」，展現古代漢語精練優雅之語法結構。\\n【思想與篇章】本篇體現了修德立身、順應天道與治國安民的深遠哲理，具有極高的學術考證與思想啟發價值。"}},{"id":"guanzi_ch-4_p-6","chapterId":"guanzi_ch-4","order":6,"canonicalText":"君之所務者五：一曰山澤不救於火，草木不植成，國之貧也。二曰溝瀆不遂於隘，鄣水不安其藏，國之貧也。三曰桑麻不植於野，五穀不宜其地，國之貧也。四曰六畜不育於家，瓜瓠葷菜百果不備具，國之貧也。五曰工事競於刻鏤，女事繁於文章，國之貧也。故曰：「山澤救於火，草木植成，國之富也。溝瀆遂於隘，鄣水安其藏，國之富也。桑麻植於野，五穀宜其地，國之富也。六畜育於家，瓜瓠葷菜百果備具，國之富也。工事無刻鏤，女事無文章，國之富也。」","sentenceIds":["guanzi_ch-4_p-6_s-1","guanzi_ch-4_p-6_s-2","guanzi_ch-4_p-6_s-3","guanzi_ch-4_p-6_s-4","guanzi_ch-4_p-6_s-5","guanzi_ch-4_p-6_s-6","guanzi_ch-4_p-6_s-7","guanzi_ch-4_p-6_s-8","guanzi_ch-4_p-6_s-9","guanzi_ch-4_p-6_s-10","guanzi_ch-4_p-6_s-11"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guanzi/zh"}],"readingAid":{"translation":"君之所務者五：一說：山澤不救於火，草木不植成，國之貧也；二說：溝瀆不遂於隘，鄣水不安其藏，國之貧也；三說：桑麻不植於野，五穀不宜其地，國之貧也；四說：六畜不育於家，瓜瓠葷菜百果不備具，國之貧也；五說：工事競於刻鏤，女事繁於文章，國之貧也；故說：山澤救於火，草木植成，國之富也；溝瀆遂於隘，鄣水安其藏，國之富也；桑麻植於野，五穀宜其地，國之富也。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【題解與背景】\\n本段選自《管子》〈立政〉，為該經典著作之精華章節，呈現先秦兩漢時期深刻的思想觀點與歷史實踐。\\n【詞義與名物】\\n文中經典語句「君之所務者五：一曰山澤不救於火，草木……」詞意凝練，包含古漢語重要名詞概念與語法句式。\\n【思想與史事脈絡】\\n全段旨在大致闡發道德修養、因時制宜與實踐致用之根本原則，對後世國學研究具備極高的參考價值。"}},{"id":"guanzi_ch-4_p-7","chapterId":"guanzi_ch-4","order":7,"canonicalText":"右五事","sentenceIds":["guanzi_ch-4_p-7_s-1"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guanzi/zh"}],"readingAid":{"translation":"右五事。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【主題與背景】本段選自《管子》〈立政〉，記錄先秦秦漢經典思想與歷史實踐之精華。\\n【詞義與名物】文中包含關鍵詞彙如：「右五事」，展現古代漢語精練優雅之語法結構。\\n【思想與篇章】本篇體現了修德立身、順應天道與治國安民的深遠哲理，具有極高的學術考證與思想啟發價值。"}},{"id":"guanzi_ch-4_p-8","chapterId":"guanzi_ch-4","order":8,"canonicalText":"分國以為五鄉，鄉為之師，分鄉以為五州，州為之長。分州以為十里，裏為之尉。分裏以為十遊，遊為之宗。十家為什，五家為伍，什伍皆有長焉。築障塞匿，一道路，博出入，審閭閈，慎筦鍵，筦藏於裏尉。置閭有司，以時開閉。閭有司觀出入者，以復於裏尉。凡出入不時，衣服不中，圈屬羣徒，不順於常者，閭有司見之，復無時。若在長家子弟臣妾屬役賓客，則裏尉以譙於遊宗，遊宗以譙於什伍，什伍以譙於長家，譙敬而勿復。一再則宥，三則不赦。凡孝悌忠信、賢良俊材，若在長家子弟臣妾屬役賓客，則什伍以復於遊宗，遊宗以復於裏尉。裏尉以復於州長。州長以計於鄉師。鄉師以著於士師。凡過黨，其在家屬，及於長家。其在長家，及於什伍之長。其在什伍之長，及於遊宗。其在遊宗，及於裏尉。其在裏尉，及於州長。其在州長，及於鄉師，其在鄉師，及於士師。三月一復，六月一計，十二月一著。凡上賢不過等，使能不兼官，罰有罪不獨及，賞有功不專與。","sentenceIds":["guanzi_ch-4_p-8_s-1","guanzi_ch-4_p-8_s-2","guanzi_ch-4_p-8_s-3","guanzi_ch-4_p-8_s-4","guanzi_ch-4_p-8_s-5","guanzi_ch-4_p-8_s-6","guanzi_ch-4_p-8_s-7","guanzi_ch-4_p-8_s-8","guanzi_ch-4_p-8_s-9","guanzi_ch-4_p-8_s-10","guanzi_ch-4_p-8_s-11","guanzi_ch-4_p-8_s-12","guanzi_ch-4_p-8_s-13","guanzi_ch-4_p-8_s-14","guanzi_ch-4_p-8_s-15","guanzi_ch-4_p-8_s-16","guanzi_ch-4_p-8_s-17","guanzi_ch-4_p-8_s-18","guanzi_ch-4_p-8_s-19","guanzi_ch-4_p-8_s-20","guanzi_ch-4_p-8_s-21","guanzi_ch-4_p-8_s-22"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guanzi/zh"}],"readingAid":{"translation":"分國以為五鄉，鄉為之師，分鄉以為五州，州為之長；分州以為十里，裡為之尉；分裡以為十遊，遊為之宗；十家為什，五家為伍，什伍皆有長焉；築障塞匿，一道路，博出入，審閭閈，慎筦鍵，筦藏於裡尉；置閭有司，以時開閉；閭有司觀出入者，以復於裡尉；凡出入不時，衣服不中，圈屬羣徒，不順於常者，閭有司見之，復無時。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【主題與背景】本段選自《管子》〈立政〉，記錄先秦秦漢經典思想與歷史實踐之精華。\\n【詞義與名物】文中包含關鍵詞彙如：「分國以為、五鄉、鄉為之師、分鄉以為」，展現古代漢語精練優雅之語法結構。\\n【思想與篇章】本篇體現了修德立身、順應天道與治國安民的深遠哲理，具有極高的學術考證與思想啟發價值。"}},{"id":"guanzi_ch-4_p-9","chapterId":"guanzi_ch-4","order":9,"canonicalText":"孟春之朝，君自聽朝，論爵賞校官，終五日。季冬之夕，君自聽朝，論罰罪刑殺，亦終五日。正月之朔，百吏在朝，君乃出令布憲於國，五鄉之師，五屬大夫，皆受憲於太史。大朝之日，五鄉之師，五屬大夫，皆身習憲於君前。太史既布憲，入籍於太府。憲籍分於君前。五鄉之師出朝，遂於鄉官致於鄉屬，及於遊宗，皆受憲。憲既布，乃反致令焉，然後敢就舍；憲未布，令未致，不敢就舍。就舍，謂之留令。罪死不赦。五屬大夫，皆以行車朝，出朝不敢就舍，遂行至都之日。遂於廟致屬吏，皆受憲。憲既布，乃發使者致令以布憲之日蚤晏之時，憲既布，使者以發，然後敢就舍；憲未布。使者未發，不敢就舍；就舍，謂之留令，罪死不赦。憲既布，有不行憲者，謂之不從令，罪死不赦。考憲而有不合於太府之籍者，侈曰專制，不足曰虧令，罪死不赦。首憲既布，然後可以布憲。","sentenceIds":["guanzi_ch-4_p-9_s-1","guanzi_ch-4_p-9_s-2","guanzi_ch-4_p-9_s-3","guanzi_ch-4_p-9_s-4","guanzi_ch-4_p-9_s-5","guanzi_ch-4_p-9_s-6","guanzi_ch-4_p-9_s-7","guanzi_ch-4_p-9_s-8","guanzi_ch-4_p-9_s-9","guanzi_ch-4_p-9_s-10","guanzi_ch-4_p-9_s-11","guanzi_ch-4_p-9_s-12","guanzi_ch-4_p-9_s-13","guanzi_ch-4_p-9_s-14","guanzi_ch-4_p-9_s-15","guanzi_ch-4_p-9_s-16","guanzi_ch-4_p-9_s-17","guanzi_ch-4_p-9_s-18","guanzi_ch-4_p-9_s-19","guanzi_ch-4_p-9_s-20"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guanzi/zh"}],"readingAid":{"translation":"孟春之朝，君自聽朝，論爵賞校官，終五日；季冬之夕，君自聽朝，論罰罪刑殺，亦終五日；正月之朔，百吏在朝，君乃出令布憲於國，五鄉之師，五屬大夫，皆受憲於太史；大朝之日，五鄉之師，五屬大夫，皆身習憲於君前；太史既布憲，入籍於太府；憲籍分於君前；五鄉之師出朝，遂於鄉官致於鄉屬，及於遊宗，皆受憲；憲既布，乃反致令焉，然後敢就舍；憲未布，令未致，不敢就舍。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【主題與背景】本段選自《管子》〈立政〉，記錄先秦秦漢經典思想與歷史實踐之精華。\\n【詞義與名物】文中包含關鍵詞彙如：「孟春之朝、君自聽朝、論爵賞校、終五日」，展現古代漢語精練優雅之語法結構。\\n【思想與篇章】本篇體現了修德立身、順應天道與治國安民的深遠哲理，具有極高的學術考證與思想啟發價值。"}},{"id":"guanzi_ch-4_p-10","chapterId":"guanzi_ch-4","order":10,"canonicalText":"右首憲","sentenceIds":["guanzi_ch-4_p-10_s-1"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guanzi/zh"}],"readingAid":{"translation":"右首憲。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【主題與背景】本段選自《管子》〈立政〉，記錄先秦秦漢經典思想與歷史實踐之精華。\\n【詞義與名物】文中包含關鍵詞彙如：「右首憲」，展現古代漢語精練優雅之語法結構。\\n【思想與篇章】本篇體現了修德立身、順應天道與治國安民的深遠哲理，具有極高的學術考證與思想啟發價值。"}},{"id":"guanzi_ch-4_p-11","chapterId":"guanzi_ch-4","order":11,"canonicalText":"凡將舉事，令必先出，曰事將為。其賞罰之數，必先明之，立事者，謹守令以行賞罰，計事致令，復賞罰之所加，有不合於令之所謂者，雖有功利，則謂之專制，罪死不赦。首事既布，然後可以舉事。","sentenceIds":["guanzi_ch-4_p-11_s-1","guanzi_ch-4_p-11_s-2","guanzi_ch-4_p-11_s-3"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guanzi/zh"}],"readingAid":{"translation":"凡將舉事，令必先出，說：事將為；其賞罰之數，必先明之，立事者，謹守令以行賞罰，計事致令，復賞罰之所加，有不合於令之所謂者，雖有功利，則謂之專制，罪死不赦；首事既布，然後可以舉事。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【題解與背景】\\n本段選自《管子》〈立政〉，為該經典著作之精華章節，呈現先秦兩漢時期深刻的思想觀點與歷史實踐。\\n【詞義與名物】\\n文中經典語句「凡將舉事，令必先出，曰事將為。其賞罰……」詞意凝練，包含古漢語重要名詞概念與語法句式。\\n【思想與史事脈絡】\\n全段旨在大致闡發道德修養、因時制宜與實踐致用之根本原則，對後世國學研究具備極高的參考價值。"}},{"id":"guanzi_ch-4_p-12","chapterId":"guanzi_ch-4","order":12,"canonicalText":"右首事","sentenceIds":["guanzi_ch-4_p-12_s-1"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guanzi/zh"}],"readingAid":{"translation":"右首事。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【主題與背景】本段選自《管子》〈立政〉，記錄先秦秦漢經典思想與歷史實踐之精華。\\n【詞義與名物】文中包含關鍵詞彙如：「右首事」，展現古代漢語精練優雅之語法結構。\\n【思想與篇章】本篇體現了修德立身、順應天道與治國安民的深遠哲理，具有極高的學術考證與思想啟發價值。"}},{"id":"guanzi_ch-4_p-13","chapterId":"guanzi_ch-4","order":13,"canonicalText":"修火憲，敬山澤，林藪積草，夫財之所出，以時禁發焉。使民足於宮室之用，薪蒸之所積，虞師之事也，決水潦，通溝瀆，修障防，安水藏，使時水雖過度，無害於五穀。歲雖兇旱，有所秎穫，司空之事也。相高下，視肥墝，觀地宜，明詔期，前後農夫，以時均修焉，使五穀桑麻，皆安其處，由田之事也。行鄉里，視宮室，觀樹蓺，簡六畜，以時鈞修焉。勸勉百姓，使力作毋偷。懷樂家室，重去鄉里，鄉師之事也。論百工，審時事，辨功苦，上完利，監壹五鄉，以時鈞修焉。使刻鏤文采，毋敢造於鄉，工師之事也。","sentenceIds":["guanzi_ch-4_p-13_s-1","guanzi_ch-4_p-13_s-2","guanzi_ch-4_p-13_s-3","guanzi_ch-4_p-13_s-4","guanzi_ch-4_p-13_s-5","guanzi_ch-4_p-13_s-6","guanzi_ch-4_p-13_s-7","guanzi_ch-4_p-13_s-8","guanzi_ch-4_p-13_s-9"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guanzi/zh"}],"readingAid":{"translation":"修火憲，敬山澤，林藪積草，夫財之所出，以時禁發焉；使民足於宮室之用，薪蒸之所積，虞師之事也，決水潦，通溝瀆，修障防，安水藏，使時水雖過度，無害於五穀；歲雖兇旱，有所秎穫，司空之事也；相高下，視肥墝，觀地宜，明詔期，前後農夫，以時均修焉，使五穀桑麻，皆安其處，由田之事也；行鄉裡，視宮室，觀樹蓺，簡六畜，以時鈞修焉；勸勉百姓，使力作毋偷；懷樂家室，重去鄉裡，鄉師之事也；論百工，審時事，辨功苦，上完利，監壹五鄉，以時鈞修焉。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【主題與背景】本段選自《管子》〈立政〉，記錄先秦秦漢經典思想與歷史實踐之精華。\\n【詞義與名物】文中包含關鍵詞彙如：「修火憲、敬山澤、林藪積草、夫財之所」，展現古代漢語精練優雅之語法結構。\\n【思想與篇章】本篇體現了修德立身、順應天道與治國安民的深遠哲理，具有極高的學術考證與思想啟發價值。"}},{"id":"guanzi_ch-4_p-14","chapterId":"guanzi_ch-4","order":14,"canonicalText":"右省官","sentenceIds":["guanzi_ch-4_p-14_s-1"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guanzi/zh"}],"readingAid":{"translation":"右省官。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【主題與背景】本段選自《管子》〈立政〉，記錄先秦秦漢經典思想與歷史實踐之精華。\\n【詞義與名物】文中包含關鍵詞彙如：「右省官」，展現古代漢語精練優雅之語法結構。\\n【思想與篇章】本篇體現了修德立身、順應天道與治國安民的深遠哲理，具有極高的學術考證與思想啟發價值。"}},{"id":"guanzi_ch-4_p-15","chapterId":"guanzi_ch-4","order":15,"canonicalText":"度爵而制服，量祿而用財，飲食有量，衣服有制，宮室有度，六畜人徒有數，舟車陳器有禁，修生則有軒冕服位穀祿田宅之分，死則有棺槨絞衾壙壟之度。雖有賢身貴體，毋其爵，不敢服其服。雖有富家多資，毋其祿，不敢用其財。天子服文有章，而夫人不敢以燕以饗廟，將軍大夫不敢以朝官吏，以命士，止於帶緣，散民不敢服雜採，百工商賈不得服長鬈貂，刑餘戮民不敢服絻，不敢畜連乘車。","sentenceIds":["guanzi_ch-4_p-15_s-1","guanzi_ch-4_p-15_s-2","guanzi_ch-4_p-15_s-3","guanzi_ch-4_p-15_s-4"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guanzi/zh"}],"readingAid":{"translation":"度爵而制服，量祿而用財，飲食有量，衣服有制，宮室有度，六畜人徒有數，舟車陳器有禁，修生則有軒冕服位穀祿田宅之分，死則有棺槨絞衾壙壟之度；雖有賢身貴體，毋其爵，不敢服其服；雖有富家多資，毋其祿，不敢用其財；天子服文有章，而夫人不敢以燕以饗廟，將軍大夫不敢以朝官吏，以命士，止於帶緣，散民不敢服雜採，百工商賈不得服長鬈貂，刑餘戮民不敢服絻，不敢畜連乘車。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【主題與背景】本段選自《管子》〈立政〉，記錄先秦秦漢經典思想與歷史實踐之精華。\\n【詞義與名物】文中包含關鍵詞彙如：「度爵而制、量祿而用、飲食有量、衣服有制」，展現古代漢語精練優雅之語法結構。\\n【思想與篇章】本篇體現了修德立身、順應天道與治國安民的深遠哲理，具有極高的學術考證與思想啟發價值。"}},{"id":"guanzi_ch-4_p-16","chapterId":"guanzi_ch-4","order":16,"canonicalText":"右服制","sentenceIds":["guanzi_ch-4_p-16_s-1"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guanzi/zh"}],"readingAid":{"translation":"右服制。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【主題與背景】本段選自《管子》〈立政〉，記錄先秦秦漢經典思想與歷史實踐之精華。\\n【詞義與名物】文中包含關鍵詞彙如：「右服制」，展現古代漢語精練優雅之語法結構。\\n【思想與篇章】本篇體現了修德立身、順應天道與治國安民的深遠哲理，具有極高的學術考證與思想啟發價值。"}},{"id":"guanzi_ch-4_p-17","chapterId":"guanzi_ch-4","order":17,"canonicalText":"寢兵之說勝，則險阻不守；兼愛之說勝，則士卒不戰。全生之說勝，則廉恥不立。私議自貴之說勝，則上令不行。羣徒比周之說勝，則賢不肖不分。金玉貨財之說勝。則爵服下流，觀樂玩好之說勝。則姦民在上位。請謁任舉之說勝，則繩墨不正，諂諛飾過之說勝，則巧佞者用。","sentenceIds":["guanzi_ch-4_p-17_s-1","guanzi_ch-4_p-17_s-2","guanzi_ch-4_p-17_s-3","guanzi_ch-4_p-17_s-4","guanzi_ch-4_p-17_s-5","guanzi_ch-4_p-17_s-6","guanzi_ch-4_p-17_s-7","guanzi_ch-4_p-17_s-8","guanzi_ch-4_p-17_s-9"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guanzi/zh"}],"readingAid":{"translation":"寢兵之說勝，則險阻不守；兼愛之說勝，則士去世不戰；全生之說勝，則廉恥不立；私議自貴之說勝，則上令不行；羣徒比周之說勝，則賢不肖不分；金玉貨財之說勝；則爵服下流，觀樂玩好之說勝；則姦民在上位；請謁任舉之說勝，則繩墨不正，諂諛飾過之說勝，則巧佞者用。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【題解與背景】\\n本段選自《管子》〈立政〉，為該經典著作之精華章節，呈現先秦兩漢時期深刻的思想觀點與歷史實踐。\\n【詞義與名物】\\n文中經典語句「寢兵之說勝，則險阻不守；兼愛之說勝，……」詞意凝練，包含古漢語重要名詞概念與語法句式。\\n【思想與史事脈絡】\\n全段旨在大致闡發道德修養、因時制宜與實踐致用之根本原則，對後世國學研究具備極高的參考價值。"}},{"id":"guanzi_ch-4_p-18","chapterId":"guanzi_ch-4","order":18,"canonicalText":"右九敗","sentenceIds":["guanzi_ch-4_p-18_s-1"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guanzi/zh"}],"readingAid":{"translation":"右九敗。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【主題與背景】本段選自《管子》〈立政〉，記錄先秦秦漢經典思想與歷史實踐之精華。\\n【詞義與名物】文中包含關鍵詞彙如：「右九敗」，展現古代漢語精練優雅之語法結構。\\n【思想與篇章】本篇體現了修德立身、順應天道與治國安民的深遠哲理，具有極高的學術考證與思想啟發價值。"}},{"id":"guanzi_ch-4_p-19","chapterId":"guanzi_ch-4","order":19,"canonicalText":"期而致，使而往，百姓捨己以上為心者，教之所期也。始於不足見，終於不可及，一人服之，萬人從之，訓之所期也。未之令而為，未之使而往，上不加勉，而民自盡，竭俗之所期也。好惡形於心，百姓化於下，罰未行而民畏恐，賞未加而民勸勉，誠信之所期也。為而無害，成而不議，得而莫之能爭，天道之所期也。為之而成，求之而得，上之所欲，小大必舉，事之所期也。令則行，禁則止，憲之所及，俗之所被，如百體之從心，政之所期也。","sentenceIds":["guanzi_ch-4_p-19_s-1","guanzi_ch-4_p-19_s-2","guanzi_ch-4_p-19_s-3","guanzi_ch-4_p-19_s-4","guanzi_ch-4_p-19_s-5","guanzi_ch-4_p-19_s-6","guanzi_ch-4_p-19_s-7"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guanzi/zh"}],"readingAid":{"translation":"期而致，使而往，百姓捨己以上為心者，教之所期也；始於不足見，終於不可及，一人服之，萬人從之，訓之所期也；未之令而為，未之使而往，上不加勉，而民自盡，竭俗之所期也；好惡形於心，百姓化於下，罰未行而民畏恐，賞未加而民勸勉，誠信之所期也；為而無害，成而不議，得而莫之能爭，天道之所期也；為之而成，求之而得，上之所欲，小大必舉，事之所期也；令則行，禁則止，憲之所及，俗之所被，如百體之從心，政之所期也。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【題解與背景】\\n本段選自《管子》〈立政〉，為該經典著作之精華章節，呈現先秦兩漢時期深刻的思想觀點與歷史實踐。\\n【詞義與名物】\\n文中經典語句「期而致，使而往，百姓捨己以上為心者，……」詞意凝練，包含古漢語重要名詞概念與語法句式。\\n【思想與史事脈絡】\\n全段旨在大致闡發道德修養、因時制宜與實踐致用之根本原則，對後世國學研究具備極高的參考價值。"}},{"id":"guanzi_ch-4_p-20","chapterId":"guanzi_ch-4","order":20,"canonicalText":"右七觀","sentenceIds":["guanzi_ch-4_p-20_s-1"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/guanzi/zh"}],"readingAid":{"translation":"右七觀。全文深刻表達了順應自然客觀規律、修己安人、審時度勢與治國理政之根本道理。","analysis":"【主題與背景】本段選自《管子》〈立政〉，記錄先秦秦漢經典思想與歷史實踐之精華。\\n【詞義與名物】文中包含關鍵詞彙如：「右七觀」，展現古代漢語精練優雅之語法結構。\\n【思想與篇章】本篇體現了修德立身、順應天道與治國安民的深遠哲理，具有極高的學術考證與思想啟發價值。"}}],"sentences":[{"id":"guanzi_ch-1_p-1_s-1","passageId":"guanzi_ch-1_p-1","order":1,"canonicalText":"凡有地牧民者，務在四時，守在倉廩。","chunks":[["凡有地牧民者，務在四時，守在倉廩。","zh-Hant"]]},{"id":"guanzi_ch-1_p-1_s-2","passageId":"guanzi_ch-1_p-1","order":2,"canonicalText":"國多財，則遠者來，地闢舉，則民留處；","chunks":[["國多財，則遠者來，地闢舉，則民留處；","zh-Hant"]]},{"id":"guanzi_ch-1_p-1_s-3","passageId":"guanzi_ch-1_p-1","order":3,"canonicalText":"倉廩實，則知禮節；","chunks":[["倉廩實，則知禮節；","zh-Hant"]]},{"id":"guanzi_ch-1_p-1_s-4","passageId":"guanzi_ch-1_p-1","order":4,"canonicalText":"衣食足，則知榮辱；","chunks":[["衣食足，則知榮辱；","zh-Hant"]]},{"id":"guanzi_ch-1_p-1_s-5","passageId":"guanzi_ch-1_p-1","order":5,"canonicalText":"上服度，則六親固。","chunks":[["上服度，則六親固。","zh-Hant"]]},{"id":"guanzi_ch-1_p-1_s-6","passageId":"guanzi_ch-1_p-1","order":6,"canonicalText":"四維張，則君令行。","chunks":[["四維張，則君令行。","zh-Hant"]]},{"id":"guanzi_ch-1_p-1_s-7","passageId":"guanzi_ch-1_p-1","order":7,"canonicalText":"故省刑之要，在禁文巧，守國之度，在飾四維，順民之經，在明鬼神，祇山川，敬宗廟，恭祖舊。","chunks":[["故省刑之要，在禁文巧，守國之度，在飾四維，順民之經，在明鬼神，祇山川，敬宗廟，恭祖舊。","zh-Hant"]]},{"id":"guanzi_ch-1_p-1_s-8","passageId":"guanzi_ch-1_p-1","order":8,"canonicalText":"不務天時，則財不生；","chunks":[["不務天時，則財不生；","zh-Hant"]]},{"id":"guanzi_ch-1_p-1_s-9","passageId":"guanzi_ch-1_p-1","order":9,"canonicalText":"不務地利，則倉廩不盈；","chunks":[["不務地利，則倉廩不盈；","zh-Hant"]]},{"id":"guanzi_ch-1_p-1_s-10","passageId":"guanzi_ch-1_p-1","order":10,"canonicalText":"野蕪曠，則民乃菅，上無量，則民乃妄。","chunks":[["野蕪曠，則民乃菅，上無量，則民乃妄。","zh-Hant"]]},{"id":"guanzi_ch-1_p-1_s-11","passageId":"guanzi_ch-1_p-1","order":11,"canonicalText":"文巧不禁，則民乃淫，不璋兩原，則刑乃繁。","chunks":[["文巧不禁，則民乃淫，不璋兩原，則刑乃繁。","zh-Hant"]]},{"id":"guanzi_ch-1_p-1_s-12","passageId":"guanzi_ch-1_p-1","order":12,"canonicalText":"不明鬼神，則陋民不悟；","chunks":[["不明鬼神，則陋民不悟；","zh-Hant"]]},{"id":"guanzi_ch-1_p-1_s-13","passageId":"guanzi_ch-1_p-1","order":13,"canonicalText":"不祇山川，則威令不聞；","chunks":[["不祇山川，則威令不聞；","zh-Hant"]]},{"id":"guanzi_ch-1_p-1_s-14","passageId":"guanzi_ch-1_p-1","order":14,"canonicalText":"不敬宗廟，則民乃上校；","chunks":[["不敬宗廟，則民乃上校；","zh-Hant"]]},{"id":"guanzi_ch-1_p-1_s-15","passageId":"guanzi_ch-1_p-1","order":15,"canonicalText":"不恭祖舊，則孝悌不備；","chunks":[["不恭祖舊，則孝悌不備；","zh-Hant"]]},{"id":"guanzi_ch-1_p-1_s-16","passageId":"guanzi_ch-1_p-1","order":16,"canonicalText":"四維不張，國乃滅亡。","chunks":[["四維不張，國乃滅亡。","zh-Hant"]]},{"id":"guanzi_ch-1_p-2_s-1","passageId":"guanzi_ch-1_p-2","order":1,"canonicalText":"右國頌","chunks":[["右國頌","zh-Hant"]]},{"id":"guanzi_ch-1_p-3_s-1","passageId":"guanzi_ch-1_p-3","order":1,"canonicalText":"國有四維，一維絕則傾，二維絕則危，三維絕則覆，四維絕則滅。","chunks":[["國有四維，一維絕則傾，二維絕則危，三維絕則覆，四維絕則滅。","zh-Hant"]]},{"id":"guanzi_ch-1_p-3_s-2","passageId":"guanzi_ch-1_p-3","order":2,"canonicalText":"傾可正也，危可安也，覆可起也，滅不可復錯也。","chunks":[["傾可正也，危可安也，覆可起也，滅不可復錯也。","zh-Hant"]]},{"id":"guanzi_ch-1_p-3_s-3","passageId":"guanzi_ch-1_p-3","order":3,"canonicalText":"何謂四維？","chunks":[["何謂四維？","zh-Hant"]]},{"id":"guanzi_ch-1_p-3_s-4","passageId":"guanzi_ch-1_p-3","order":4,"canonicalText":"一曰禮、二曰義、三曰廉、四曰恥。","chunks":[["一曰禮、二曰義、三曰廉、四曰恥。","zh-Hant"]]},{"id":"guanzi_ch-1_p-3_s-5","passageId":"guanzi_ch-1_p-3","order":5,"canonicalText":"禮不踰節，義不自進。","chunks":[["禮不踰節，義不自進。","zh-Hant"]]},{"id":"guanzi_ch-1_p-3_s-6","passageId":"guanzi_ch-1_p-3","order":6,"canonicalText":"廉不蔽惡，恥不從枉。","chunks":[["廉不蔽惡，恥不從枉。","zh-Hant"]]},{"id":"guanzi_ch-1_p-3_s-7","passageId":"guanzi_ch-1_p-3","order":7,"canonicalText":"故不踰節，則上位安；","chunks":[["故不踰節，則上位安；","zh-Hant"]]},{"id":"guanzi_ch-1_p-3_s-8","passageId":"guanzi_ch-1_p-3","order":8,"canonicalText":"不自進，則民無巧軸；","chunks":[["不自進，則民無巧軸；","zh-Hant"]]},{"id":"guanzi_ch-1_p-3_s-9","passageId":"guanzi_ch-1_p-3","order":9,"canonicalText":"不蔽惡，則行自全；","chunks":[["不蔽惡，則行自全；","zh-Hant"]]},{"id":"guanzi_ch-1_p-3_s-10","passageId":"guanzi_ch-1_p-3","order":10,"canonicalText":"不從枉，則邪事不生。","chunks":[["不從枉，則邪事不生。","zh-Hant"]]},{"id":"guanzi_ch-1_p-4_s-1","passageId":"guanzi_ch-1_p-4","order":1,"canonicalText":"右四維","chunks":[["右四維","zh-Hant"]]},{"id":"guanzi_ch-1_p-5_s-1","passageId":"guanzi_ch-1_p-5","order":1,"canonicalText":"政之所興，在順民心。","chunks":[["政之所興，在順民心。","zh-Hant"]]},{"id":"guanzi_ch-1_p-5_s-2","passageId":"guanzi_ch-1_p-5","order":2,"canonicalText":"政之所廢，在逆民心。","chunks":[["政之所廢，在逆民心。","zh-Hant"]]},{"id":"guanzi_ch-1_p-5_s-3","passageId":"guanzi_ch-1_p-5","order":3,"canonicalText":"民惡憂勞，我佚樂之。","chunks":[["民惡憂勞，我佚樂之。","zh-Hant"]]},{"id":"guanzi_ch-1_p-5_s-4","passageId":"guanzi_ch-1_p-5","order":4,"canonicalText":"民惡貧賤，我富貴之，民惡危墜，我存安之。","chunks":[["民惡貧賤，我富貴之，民惡危墜，我存安之。","zh-Hant"]]},{"id":"guanzi_ch-1_p-5_s-5","passageId":"guanzi_ch-1_p-5","order":5,"canonicalText":"民惡滅絕，我生育之。","chunks":[["民惡滅絕，我生育之。","zh-Hant"]]},{"id":"guanzi_ch-1_p-5_s-6","passageId":"guanzi_ch-1_p-5","order":6,"canonicalText":"能佚樂之，則民為之憂勞。","chunks":[["能佚樂之，則民為之憂勞。","zh-Hant"]]},{"id":"guanzi_ch-1_p-5_s-7","passageId":"guanzi_ch-1_p-5","order":7,"canonicalText":"能富貴之，則民為之貧賤。","chunks":[["能富貴之，則民為之貧賤。","zh-Hant"]]},{"id":"guanzi_ch-1_p-5_s-8","passageId":"guanzi_ch-1_p-5","order":8,"canonicalText":"能存安之，則民為之危墜。","chunks":[["能存安之，則民為之危墜。","zh-Hant"]]},{"id":"guanzi_ch-1_p-5_s-9","passageId":"guanzi_ch-1_p-5","order":9,"canonicalText":"能生育之，則民為之滅絕。","chunks":[["能生育之，則民為之滅絕。","zh-Hant"]]},{"id":"guanzi_ch-1_p-5_s-10","passageId":"guanzi_ch-1_p-5","order":10,"canonicalText":"故刑罰不足以畏其意，殺戮不足以服其心。","chunks":[["故刑罰不足以畏其意，殺戮不足以服其心。","zh-Hant"]]},{"id":"guanzi_ch-1_p-5_s-11","passageId":"guanzi_ch-1_p-5","order":11,"canonicalText":"故刑罰繁而意不恐，則令不行矣。","chunks":[["故刑罰繁而意不恐，則令不行矣。","zh-Hant"]]},{"id":"guanzi_ch-1_p-5_s-12","passageId":"guanzi_ch-1_p-5","order":12,"canonicalText":"殺戮眾而心不服，則上位危矣。","chunks":[["殺戮眾而心不服，則上位危矣。","zh-Hant"]]},{"id":"guanzi_ch-1_p-5_s-13","passageId":"guanzi_ch-1_p-5","order":13,"canonicalText":"故從其四欲，則遠者自親；","chunks":[["故從其四欲，則遠者自親；","zh-Hant"]]},{"id":"guanzi_ch-1_p-5_s-14","passageId":"guanzi_ch-1_p-5","order":14,"canonicalText":"行其四惡，則近者叛之，故知「予之為取者，政之寶也」。","chunks":[["行其四惡，則近者叛之，故知「予之為取者，政之寶也」。","zh-Hant"]]},{"id":"guanzi_ch-1_p-6_s-1","passageId":"guanzi_ch-1_p-6","order":1,"canonicalText":"右四順","chunks":[["右四順","zh-Hant"]]},{"id":"guanzi_ch-1_p-7_s-1","passageId":"guanzi_ch-1_p-7","order":1,"canonicalText":"錯國於不傾之地，積於不涸之倉，藏於不竭之府，下令於流水之原，使民於不爭之官，明必死之路，開必得之門。","chunks":[["錯國於不傾之地，積於不涸之倉，藏於不竭之府，下令於流水之原，使民於不爭之官，明必死之路，開必得之門。","zh-Hant"]]},{"id":"guanzi_ch-1_p-7_s-2","passageId":"guanzi_ch-1_p-7","order":2,"canonicalText":"不為不可成，不求不可得，不處不可久，不行不可復。","chunks":[["不為不可成，不求不可得，不處不可久，不行不可復。","zh-Hant"]]},{"id":"guanzi_ch-1_p-7_s-3","passageId":"guanzi_ch-1_p-7","order":3,"canonicalText":"錯國於不傾之地者，授有德也；","chunks":[["錯國於不傾之地者，授有德也；","zh-Hant"]]},{"id":"guanzi_ch-1_p-7_s-4","passageId":"guanzi_ch-1_p-7","order":4,"canonicalText":"積於不涸之倉者，務五穀也；","chunks":[["積於不涸之倉者，務五穀也；","zh-Hant"]]},{"id":"guanzi_ch-1_p-7_s-5","passageId":"guanzi_ch-1_p-7","order":5,"canonicalText":"藏於不竭之府者，養桑麻育六畜也；","chunks":[["藏於不竭之府者，養桑麻育六畜也；","zh-Hant"]]},{"id":"guanzi_ch-1_p-7_s-6","passageId":"guanzi_ch-1_p-7","order":6,"canonicalText":"下令於流水之原者，令順民心也；","chunks":[["下令於流水之原者，令順民心也；","zh-Hant"]]},{"id":"guanzi_ch-1_p-7_s-7","passageId":"guanzi_ch-1_p-7","order":7,"canonicalText":"使民於不爭之官者，使各為其所長也；","chunks":[["使民於不爭之官者，使各為其所長也；","zh-Hant"]]},{"id":"guanzi_ch-1_p-7_s-8","passageId":"guanzi_ch-1_p-7","order":8,"canonicalText":"明必死之路者，嚴刑罰也；","chunks":[["明必死之路者，嚴刑罰也；","zh-Hant"]]},{"id":"guanzi_ch-1_p-7_s-9","passageId":"guanzi_ch-1_p-7","order":9,"canonicalText":"開必得之門者，信慶賞也；","chunks":[["開必得之門者，信慶賞也；","zh-Hant"]]},{"id":"guanzi_ch-1_p-7_s-10","passageId":"guanzi_ch-1_p-7","order":10,"canonicalText":"不為不可成者，量民力也；","chunks":[["不為不可成者，量民力也；","zh-Hant"]]},{"id":"guanzi_ch-1_p-7_s-11","passageId":"guanzi_ch-1_p-7","order":11,"canonicalText":"不求不可得者，不彊民以其所惡也；","chunks":[["不求不可得者，不彊民以其所惡也；","zh-Hant"]]},{"id":"guanzi_ch-1_p-7_s-12","passageId":"guanzi_ch-1_p-7","order":12,"canonicalText":"不處不可久者，不偷取一世也；","chunks":[["不處不可久者，不偷取一世也；","zh-Hant"]]},{"id":"guanzi_ch-1_p-7_s-13","passageId":"guanzi_ch-1_p-7","order":13,"canonicalText":"不行不可復者，不欺其民也；","chunks":[["不行不可復者，不欺其民也；","zh-Hant"]]},{"id":"guanzi_ch-1_p-7_s-14","passageId":"guanzi_ch-1_p-7","order":14,"canonicalText":"故授有德，則國安；","chunks":[["故授有德，則國安；","zh-Hant"]]},{"id":"guanzi_ch-1_p-7_s-15","passageId":"guanzi_ch-1_p-7","order":15,"canonicalText":"務五穀，則食足；","chunks":[["務五穀，則食足；","zh-Hant"]]},{"id":"guanzi_ch-1_p-7_s-16","passageId":"guanzi_ch-1_p-7","order":16,"canonicalText":"養桑麻，育六畜，則民富；","chunks":[["養桑麻，育六畜，則民富；","zh-Hant"]]},{"id":"guanzi_ch-1_p-7_s-17","passageId":"guanzi_ch-1_p-7","order":17,"canonicalText":"令順民心，則威令行；","chunks":[["令順民心，則威令行；","zh-Hant"]]},{"id":"guanzi_ch-1_p-7_s-18","passageId":"guanzi_ch-1_p-7","order":18,"canonicalText":"使民各為其所長，則用備；","chunks":[["使民各為其所長，則用備；","zh-Hant"]]},{"id":"guanzi_ch-1_p-7_s-19","passageId":"guanzi_ch-1_p-7","order":19,"canonicalText":"嚴刑罰，則民遠邪；","chunks":[["嚴刑罰，則民遠邪；","zh-Hant"]]},{"id":"guanzi_ch-1_p-7_s-20","passageId":"guanzi_ch-1_p-7","order":20,"canonicalText":"信慶賞，則民輕難；","chunks":[["信慶賞，則民輕難；","zh-Hant"]]},{"id":"guanzi_ch-1_p-7_s-21","passageId":"guanzi_ch-1_p-7","order":21,"canonicalText":"量民力，則事無不成；","chunks":[["量民力，則事無不成；","zh-Hant"]]},{"id":"guanzi_ch-1_p-7_s-22","passageId":"guanzi_ch-1_p-7","order":22,"canonicalText":"不彊民以其所惡，則軸偽不生；","chunks":[["不彊民以其所惡，則軸偽不生；","zh-Hant"]]},{"id":"guanzi_ch-1_p-7_s-23","passageId":"guanzi_ch-1_p-7","order":23,"canonicalText":"不偷取一世，則民無怨心；","chunks":[["不偷取一世，則民無怨心；","zh-Hant"]]},{"id":"guanzi_ch-1_p-7_s-24","passageId":"guanzi_ch-1_p-7","order":24,"canonicalText":"不欺其民，則下親其上。","chunks":[["不欺其民，則下親其上。","zh-Hant"]]},{"id":"guanzi_ch-1_p-8_s-1","passageId":"guanzi_ch-1_p-8","order":1,"canonicalText":"右士經","chunks":[["右士經","zh-Hant"]]},{"id":"guanzi_ch-1_p-9_s-1","passageId":"guanzi_ch-1_p-9","order":1,"canonicalText":"以家為鄉，鄉不可為也。","chunks":[["以家為鄉，鄉不可為也。","zh-Hant"]]},{"id":"guanzi_ch-1_p-9_s-2","passageId":"guanzi_ch-1_p-9","order":2,"canonicalText":"以鄉為國，國不可為也。","chunks":[["以鄉為國，國不可為也。","zh-Hant"]]},{"id":"guanzi_ch-1_p-9_s-3","passageId":"guanzi_ch-1_p-9","order":3,"canonicalText":"以國為天下，天下不可為也。","chunks":[["以國為天下，天下不可為也。","zh-Hant"]]},{"id":"guanzi_ch-1_p-9_s-4","passageId":"guanzi_ch-1_p-9","order":4,"canonicalText":"以家為家，以鄉為鄉，以國為國，以天下為天下。","chunks":[["以家為家，以鄉為鄉，以國為國，以天下為天下。","zh-Hant"]]},{"id":"guanzi_ch-1_p-9_s-5","passageId":"guanzi_ch-1_p-9","order":5,"canonicalText":"毋曰不同生，遠者不聽。","chunks":[["毋曰不同生，遠者不聽。","zh-Hant"]]},{"id":"guanzi_ch-1_p-9_s-6","passageId":"guanzi_ch-1_p-9","order":6,"canonicalText":"毋曰不同鄉，遠者不行。","chunks":[["毋曰不同鄉，遠者不行。","zh-Hant"]]},{"id":"guanzi_ch-1_p-9_s-7","passageId":"guanzi_ch-1_p-9","order":7,"canonicalText":"毋曰不同國，遠者不從。","chunks":[["毋曰不同國，遠者不從。","zh-Hant"]]},{"id":"guanzi_ch-1_p-9_s-8","passageId":"guanzi_ch-1_p-9","order":8,"canonicalText":"如地如天，何私何親？","chunks":[["如地如天，何私何親？","zh-Hant"]]},{"id":"guanzi_ch-1_p-9_s-9","passageId":"guanzi_ch-1_p-9","order":9,"canonicalText":"如月如日，唯君之節。","chunks":[["如月如日，唯君之節。","zh-Hant"]]},{"id":"guanzi_ch-1_p-9_s-10","passageId":"guanzi_ch-1_p-9","order":10,"canonicalText":"御民之轡，在上之所貴。","chunks":[["御民之轡，在上之所貴。","zh-Hant"]]},{"id":"guanzi_ch-1_p-9_s-11","passageId":"guanzi_ch-1_p-9","order":11,"canonicalText":"道民之門，在上之所先。","chunks":[["道民之門，在上之所先。","zh-Hant"]]},{"id":"guanzi_ch-1_p-9_s-12","passageId":"guanzi_ch-1_p-9","order":12,"canonicalText":"召民之路，在上之所好惡。","chunks":[["召民之路，在上之所好惡。","zh-Hant"]]},{"id":"guanzi_ch-1_p-9_s-13","passageId":"guanzi_ch-1_p-9","order":13,"canonicalText":"故君求之，則臣得之。","chunks":[["故君求之，則臣得之。","zh-Hant"]]},{"id":"guanzi_ch-1_p-9_s-14","passageId":"guanzi_ch-1_p-9","order":14,"canonicalText":"君嗜之，則臣食之。","chunks":[["君嗜之，則臣食之。","zh-Hant"]]},{"id":"guanzi_ch-1_p-9_s-15","passageId":"guanzi_ch-1_p-9","order":15,"canonicalText":"君好之，則臣服之。","chunks":[["君好之，則臣服之。","zh-Hant"]]},{"id":"guanzi_ch-1_p-9_s-16","passageId":"guanzi_ch-1_p-9","order":16,"canonicalText":"君惡之，則臣匿之。","chunks":[["君惡之，則臣匿之。","zh-Hant"]]},{"id":"guanzi_ch-1_p-9_s-17","passageId":"guanzi_ch-1_p-9","order":17,"canonicalText":"毋蔽汝惡，毋異汝度，賢者將不汝助。","chunks":[["毋蔽汝惡，毋異汝度，賢者將不汝助。","zh-Hant"]]},{"id":"guanzi_ch-1_p-9_s-18","passageId":"guanzi_ch-1_p-9","order":18,"canonicalText":"言室滿室，言堂滿堂，是謂聖王。","chunks":[["言室滿室，言堂滿堂，是謂聖王。","zh-Hant"]]},{"id":"guanzi_ch-1_p-9_s-19","passageId":"guanzi_ch-1_p-9","order":19,"canonicalText":"城郭溝渠，不足以固守；","chunks":[["城郭溝渠，不足以固守；","zh-Hant"]]},{"id":"guanzi_ch-1_p-9_s-20","passageId":"guanzi_ch-1_p-9","order":20,"canonicalText":"兵甲彊力，不足以應敵；","chunks":[["兵甲彊力，不足以應敵；","zh-Hant"]]},{"id":"guanzi_ch-1_p-9_s-21","passageId":"guanzi_ch-1_p-9","order":21,"canonicalText":"博地多財，不足以有眾。","chunks":[["博地多財，不足以有眾。","zh-Hant"]]},{"id":"guanzi_ch-1_p-9_s-22","passageId":"guanzi_ch-1_p-9","order":22,"canonicalText":"惟有道者，能備患於未形也，故禍不萌。","chunks":[["惟有道者，能備患於未形也，故禍不萌。","zh-Hant"]]},{"id":"guanzi_ch-1_p-9_s-23","passageId":"guanzi_ch-1_p-9","order":23,"canonicalText":"天下不患無臣，患無君以使之。","chunks":[["天下不患無臣，患無君以使之。","zh-Hant"]]},{"id":"guanzi_ch-1_p-9_s-24","passageId":"guanzi_ch-1_p-9","order":24,"canonicalText":"天下不患無財，患無人以分之。","chunks":[["天下不患無財，患無人以分之。","zh-Hant"]]},{"id":"guanzi_ch-1_p-9_s-25","passageId":"guanzi_ch-1_p-9","order":25,"canonicalText":"故知時者，可立以為長。","chunks":[["故知時者，可立以為長。","zh-Hant"]]},{"id":"guanzi_ch-1_p-9_s-26","passageId":"guanzi_ch-1_p-9","order":26,"canonicalText":"無私者，可置以為政。","chunks":[["無私者，可置以為政。","zh-Hant"]]},{"id":"guanzi_ch-1_p-9_s-27","passageId":"guanzi_ch-1_p-9","order":27,"canonicalText":"審於時而察於用，而能備官者，可奉以為君也。","chunks":[["審於時而察於用，而能備官者，可奉以為君也。","zh-Hant"]]},{"id":"guanzi_ch-1_p-9_s-28","passageId":"guanzi_ch-1_p-9","order":28,"canonicalText":"緩者後於事。","chunks":[["緩者後於事。","zh-Hant"]]},{"id":"guanzi_ch-1_p-9_s-29","passageId":"guanzi_ch-1_p-9","order":29,"canonicalText":"吝於財者失所親，信小人者失士。","chunks":[["吝於財者失所親，信小人者失士。","zh-Hant"]]},{"id":"guanzi_ch-1_p-10_s-1","passageId":"guanzi_ch-1_p-10","order":1,"canonicalText":"右六親五法","chunks":[["右六親五法","zh-Hant"]]},{"id":"guanzi_ch-2_p-1_s-1","passageId":"guanzi_ch-2_p-1","order":1,"canonicalText":"山高而不崩，則祈羊至矣；","chunks":[["山高而不崩，則祈羊至矣；","zh-Hant"]]},{"id":"guanzi_ch-2_p-1_s-2","passageId":"guanzi_ch-2_p-1","order":2,"canonicalText":"淵深而不涸，則沈玉極矣，天不變其常，地不易其則，春秋冬夏，不更其節，古今一也。","chunks":[["淵深而不涸，則沈玉極矣，天不變其常，地不易其則，春秋冬夏，不更其節，古今一也。","zh-Hant"]]},{"id":"guanzi_ch-2_p-1_s-3","passageId":"guanzi_ch-2_p-1","order":3,"canonicalText":"蛟龍得水，而神可立也；","chunks":[["蛟龍得水，而神可立也；","zh-Hant"]]},{"id":"guanzi_ch-2_p-1_s-4","passageId":"guanzi_ch-2_p-1","order":4,"canonicalText":"虎豹得幽，而威可載也。","chunks":[["虎豹得幽，而威可載也。","zh-Hant"]]},{"id":"guanzi_ch-2_p-1_s-5","passageId":"guanzi_ch-2_p-1","order":5,"canonicalText":"風雨無鄉，而怨怒不及也。","chunks":[["風雨無鄉，而怨怒不及也。","zh-Hant"]]},{"id":"guanzi_ch-2_p-1_s-6","passageId":"guanzi_ch-2_p-1","order":6,"canonicalText":"貴有以行令，賤有以忘卑，壽夭貧富，無徒歸也。","chunks":[["貴有以行令，賤有以忘卑，壽夭貧富，無徒歸也。","zh-Hant"]]},{"id":"guanzi_ch-2_p-2_s-1","passageId":"guanzi_ch-2_p-2","order":1,"canonicalText":"銜命者，君之尊也。","chunks":[["銜命者，君之尊也。","zh-Hant"]]},{"id":"guanzi_ch-2_p-2_s-2","passageId":"guanzi_ch-2_p-2","order":2,"canonicalText":"受辭者，名之鉉也。","chunks":[["受辭者，名之鉉也。","zh-Hant"]]},{"id":"guanzi_ch-2_p-2_s-3","passageId":"guanzi_ch-2_p-2","order":3,"canonicalText":"上無事，則民自試。","chunks":[["上無事，則民自試。","zh-Hant"]]},{"id":"guanzi_ch-2_p-2_s-4","passageId":"guanzi_ch-2_p-2","order":4,"canonicalText":"抱蜀不言，而廟堂既修。","chunks":[["抱蜀不言，而廟堂既修。","zh-Hant"]]},{"id":"guanzi_ch-2_p-2_s-5","passageId":"guanzi_ch-2_p-2","order":5,"canonicalText":"鴻鵠鏘鏘，唯民歌之。","chunks":[["鴻鵠鏘鏘，唯民歌之。","zh-Hant"]]},{"id":"guanzi_ch-2_p-2_s-6","passageId":"guanzi_ch-2_p-2","order":6,"canonicalText":"濟濟多士，殷民化之，紂之失也。","chunks":[["濟濟多士，殷民化之，紂之失也。","zh-Hant"]]},{"id":"guanzi_ch-2_p-2_s-7","passageId":"guanzi_ch-2_p-2","order":7,"canonicalText":"飛蓬之問，不在所賓；","chunks":[["飛蓬之問，不在所賓；","zh-Hant"]]},{"id":"guanzi_ch-2_p-2_s-8","passageId":"guanzi_ch-2_p-2","order":8,"canonicalText":"燕雀之集，道行不顧。","chunks":[["燕雀之集，道行不顧。","zh-Hant"]]},{"id":"guanzi_ch-2_p-2_s-9","passageId":"guanzi_ch-2_p-2","order":9,"canonicalText":"犧牷圭璧，不足以饗鬼神。","chunks":[["犧牷圭璧，不足以饗鬼神。","zh-Hant"]]},{"id":"guanzi_ch-2_p-2_s-10","passageId":"guanzi_ch-2_p-2","order":10,"canonicalText":"主功有素，寶幣奚為？","chunks":[["主功有素，寶幣奚為？","zh-Hant"]]},{"id":"guanzi_ch-2_p-2_s-11","passageId":"guanzi_ch-2_p-2","order":11,"canonicalText":"羿之道，非射也；","chunks":[["羿之道，非射也；","zh-Hant"]]},{"id":"guanzi_ch-2_p-2_s-12","passageId":"guanzi_ch-2_p-2","order":12,"canonicalText":"造父之術，非馭也；","chunks":[["造父之術，非馭也；","zh-Hant"]]},{"id":"guanzi_ch-2_p-2_s-13","passageId":"guanzi_ch-2_p-2","order":13,"canonicalText":"奚仲之巧，非斲削也。","chunks":[["奚仲之巧，非斲削也。","zh-Hant"]]},{"id":"guanzi_ch-2_p-2_s-14","passageId":"guanzi_ch-2_p-2","order":14,"canonicalText":"召遠者使無為焉，親近者言無事焉，唯夜行者獨有也。","chunks":[["召遠者使無為焉，親近者言無事焉，唯夜行者獨有也。","zh-Hant"]]},{"id":"guanzi_ch-2_p-3_s-1","passageId":"guanzi_ch-2_p-3","order":1,"canonicalText":"平原之隰，奚有於高？","chunks":[["平原之隰，奚有於高？","zh-Hant"]]},{"id":"guanzi_ch-2_p-3_s-2","passageId":"guanzi_ch-2_p-3","order":2,"canonicalText":"大山之隈，奚有於深？","chunks":[["大山之隈，奚有於深？","zh-Hant"]]},{"id":"guanzi_ch-2_p-3_s-3","passageId":"guanzi_ch-2_p-3","order":3,"canonicalText":"訾讆之人，勿與任大。","chunks":[["訾讆之人，勿與任大。","zh-Hant"]]},{"id":"guanzi_ch-2_p-3_s-4","passageId":"guanzi_ch-2_p-3","order":4,"canonicalText":"譕臣者可以遠舉。","chunks":[["譕臣者可以遠舉。","zh-Hant"]]},{"id":"guanzi_ch-2_p-3_s-5","passageId":"guanzi_ch-2_p-3","order":5,"canonicalText":"顧憂者可與致道。","chunks":[["顧憂者可與致道。","zh-Hant"]]},{"id":"guanzi_ch-2_p-3_s-6","passageId":"guanzi_ch-2_p-3","order":6,"canonicalText":"其計也速而憂在近者，往而勿召也舉長者可遠見也；","chunks":[["其計也速而憂在近者，往而勿召也舉長者可遠見也；","zh-Hant"]]},{"id":"guanzi_ch-2_p-3_s-7","passageId":"guanzi_ch-2_p-3","order":7,"canonicalText":"裁大者眾之所比也。","chunks":[["裁大者眾之所比也。","zh-Hant"]]},{"id":"guanzi_ch-2_p-3_s-8","passageId":"guanzi_ch-2_p-3","order":8,"canonicalText":"美人之懷，定服而勿厭也。","chunks":[["美人之懷，定服而勿厭也。","zh-Hant"]]},{"id":"guanzi_ch-2_p-4_s-1","passageId":"guanzi_ch-2_p-4","order":1,"canonicalText":"必得之事，不足賴也；","chunks":[["必得之事，不足賴也；","zh-Hant"]]},{"id":"guanzi_ch-2_p-4_s-2","passageId":"guanzi_ch-2_p-4","order":2,"canonicalText":"必諾之言，不足信也。","chunks":[["必諾之言，不足信也。","zh-Hant"]]},{"id":"guanzi_ch-2_p-4_s-3","passageId":"guanzi_ch-2_p-4","order":3,"canonicalText":"小謹者不大立，訾食者不肥體；","chunks":[["小謹者不大立，訾食者不肥體；","zh-Hant"]]},{"id":"guanzi_ch-2_p-4_s-4","passageId":"guanzi_ch-2_p-4","order":4,"canonicalText":"有無棄之言者，必參於天地也。","chunks":[["有無棄之言者，必參於天地也。","zh-Hant"]]},{"id":"guanzi_ch-2_p-4_s-5","passageId":"guanzi_ch-2_p-4","order":5,"canonicalText":"墜岸三仞，人之所大難也，而猿猱飲焉，故曰伐矜好專，舉事之禍也。","chunks":[["墜岸三仞，人之所大難也，而猿猱飲焉，故曰伐矜好專，舉事之禍也。","zh-Hant"]]},{"id":"guanzi_ch-2_p-4_s-6","passageId":"guanzi_ch-2_p-4","order":6,"canonicalText":"不行其野，不違其馬；","chunks":[["不行其野，不違其馬；","zh-Hant"]]},{"id":"guanzi_ch-2_p-4_s-7","passageId":"guanzi_ch-2_p-4","order":7,"canonicalText":"能予而無取者，天地之配也。","chunks":[["能予而無取者，天地之配也。","zh-Hant"]]},{"id":"guanzi_ch-2_p-5_s-1","passageId":"guanzi_ch-2_p-5","order":1,"canonicalText":"怠倦者不及，無廣者疑神，神者在內，不及者在門，在內者將假，在門者將待。","chunks":[["怠倦者不及，無廣者疑神，神者在內，不及者在門，在內者將假，在門者將待。","zh-Hant"]]},{"id":"guanzi_ch-2_p-5_s-2","passageId":"guanzi_ch-2_p-5","order":2,"canonicalText":"曙戒勿怠，後稚逢殃。","chunks":[["曙戒勿怠，後稚逢殃。","zh-Hant"]]},{"id":"guanzi_ch-2_p-5_s-3","passageId":"guanzi_ch-2_p-5","order":3,"canonicalText":"朝忘其事，夕失其功。","chunks":[["朝忘其事，夕失其功。","zh-Hant"]]},{"id":"guanzi_ch-2_p-5_s-4","passageId":"guanzi_ch-2_p-5","order":4,"canonicalText":"邪氣入內，正色乃衰。","chunks":[["邪氣入內，正色乃衰。","zh-Hant"]]},{"id":"guanzi_ch-2_p-5_s-5","passageId":"guanzi_ch-2_p-5","order":5,"canonicalText":"君不君，則臣不臣。","chunks":[["君不君，則臣不臣。","zh-Hant"]]},{"id":"guanzi_ch-2_p-5_s-6","passageId":"guanzi_ch-2_p-5","order":6,"canonicalText":"父不父，則子不子。","chunks":[["父不父，則子不子。","zh-Hant"]]},{"id":"guanzi_ch-2_p-5_s-7","passageId":"guanzi_ch-2_p-5","order":7,"canonicalText":"上失其位，則下踰其節。","chunks":[["上失其位，則下踰其節。","zh-Hant"]]},{"id":"guanzi_ch-2_p-5_s-8","passageId":"guanzi_ch-2_p-5","order":8,"canonicalText":"上下不和，令乃不行。","chunks":[["上下不和，令乃不行。","zh-Hant"]]},{"id":"guanzi_ch-2_p-5_s-9","passageId":"guanzi_ch-2_p-5","order":9,"canonicalText":"衣冠不正，則賓者不肅；","chunks":[["衣冠不正，則賓者不肅；","zh-Hant"]]},{"id":"guanzi_ch-2_p-5_s-10","passageId":"guanzi_ch-2_p-5","order":10,"canonicalText":"進退無儀，則政令不行。","chunks":[["進退無儀，則政令不行。","zh-Hant"]]},{"id":"guanzi_ch-2_p-5_s-11","passageId":"guanzi_ch-2_p-5","order":11,"canonicalText":"且懷且威，則君道備矣。","chunks":[["且懷且威，則君道備矣。","zh-Hant"]]},{"id":"guanzi_ch-2_p-5_s-12","passageId":"guanzi_ch-2_p-5","order":12,"canonicalText":"莫樂之，則莫哀之。","chunks":[["莫樂之，則莫哀之。","zh-Hant"]]},{"id":"guanzi_ch-2_p-5_s-13","passageId":"guanzi_ch-2_p-5","order":13,"canonicalText":"莫生之，則莫死之。","chunks":[["莫生之，則莫死之。","zh-Hant"]]},{"id":"guanzi_ch-2_p-5_s-14","passageId":"guanzi_ch-2_p-5","order":14,"canonicalText":"往者不至，來者不極。","chunks":[["往者不至，來者不極。","zh-Hant"]]},{"id":"guanzi_ch-2_p-6_s-1","passageId":"guanzi_ch-2_p-6","order":1,"canonicalText":"道之所言者一也，而用之者異。","chunks":[["道之所言者一也，而用之者異。","zh-Hant"]]},{"id":"guanzi_ch-2_p-6_s-2","passageId":"guanzi_ch-2_p-6","order":2,"canonicalText":"有聞道而好為家者，一家之人也；","chunks":[["有聞道而好為家者，一家之人也；","zh-Hant"]]},{"id":"guanzi_ch-2_p-6_s-3","passageId":"guanzi_ch-2_p-6","order":3,"canonicalText":"有聞道而好為鄉者，一鄉之人也；","chunks":[["有聞道而好為鄉者，一鄉之人也；","zh-Hant"]]},{"id":"guanzi_ch-2_p-6_s-4","passageId":"guanzi_ch-2_p-6","order":4,"canonicalText":"有聞道而好為國者，一國之人也；","chunks":[["有聞道而好為國者，一國之人也；","zh-Hant"]]},{"id":"guanzi_ch-2_p-6_s-5","passageId":"guanzi_ch-2_p-6","order":5,"canonicalText":"有聞道而好為天下者，天下之人也；","chunks":[["有聞道而好為天下者，天下之人也；","zh-Hant"]]},{"id":"guanzi_ch-2_p-6_s-6","passageId":"guanzi_ch-2_p-6","order":6,"canonicalText":"有聞道而好定萬物者，天下之配也。","chunks":[["有聞道而好定萬物者，天下之配也。","zh-Hant"]]},{"id":"guanzi_ch-2_p-6_s-7","passageId":"guanzi_ch-2_p-6","order":7,"canonicalText":"道往者，其人莫來；","chunks":[["道往者，其人莫來；","zh-Hant"]]},{"id":"guanzi_ch-2_p-6_s-8","passageId":"guanzi_ch-2_p-6","order":8,"canonicalText":"道來者，其人莫往；","chunks":[["道來者，其人莫往；","zh-Hant"]]},{"id":"guanzi_ch-2_p-6_s-9","passageId":"guanzi_ch-2_p-6","order":9,"canonicalText":"道之所設，身之化也。","chunks":[["道之所設，身之化也。","zh-Hant"]]},{"id":"guanzi_ch-2_p-6_s-10","passageId":"guanzi_ch-2_p-6","order":10,"canonicalText":"持滿者與天，安危者與人。","chunks":[["持滿者與天，安危者與人。","zh-Hant"]]},{"id":"guanzi_ch-2_p-6_s-11","passageId":"guanzi_ch-2_p-6","order":11,"canonicalText":"失天之度，雖滿必涸。","chunks":[["失天之度，雖滿必涸。","zh-Hant"]]},{"id":"guanzi_ch-2_p-6_s-12","passageId":"guanzi_ch-2_p-6","order":12,"canonicalText":"上下不和，雖安必危。","chunks":[["上下不和，雖安必危。","zh-Hant"]]},{"id":"guanzi_ch-2_p-6_s-13","passageId":"guanzi_ch-2_p-6","order":13,"canonicalText":"欲王天下，而失天之道，天下不可得而王也。","chunks":[["欲王天下，而失天之道，天下不可得而王也。","zh-Hant"]]},{"id":"guanzi_ch-2_p-6_s-14","passageId":"guanzi_ch-2_p-6","order":14,"canonicalText":"得天之道。","chunks":[["得天之道。","zh-Hant"]]},{"id":"guanzi_ch-2_p-6_s-15","passageId":"guanzi_ch-2_p-6","order":15,"canonicalText":"其事若自然。","chunks":[["其事若自然。","zh-Hant"]]},{"id":"guanzi_ch-2_p-6_s-16","passageId":"guanzi_ch-2_p-6","order":16,"canonicalText":"失天之道，雖立不安。","chunks":[["失天之道，雖立不安。","zh-Hant"]]},{"id":"guanzi_ch-2_p-6_s-17","passageId":"guanzi_ch-2_p-6","order":17,"canonicalText":"其道既得，莫知其為之。","chunks":[["其道既得，莫知其為之。","zh-Hant"]]},{"id":"guanzi_ch-2_p-6_s-18","passageId":"guanzi_ch-2_p-6","order":18,"canonicalText":"其功既成，莫知其釋之。","chunks":[["其功既成，莫知其釋之。","zh-Hant"]]},{"id":"guanzi_ch-2_p-6_s-19","passageId":"guanzi_ch-2_p-6","order":19,"canonicalText":"藏之無刑，天之道也。","chunks":[["藏之無刑，天之道也。","zh-Hant"]]},{"id":"guanzi_ch-2_p-6_s-20","passageId":"guanzi_ch-2_p-6","order":20,"canonicalText":"疑今者，察之古不知來者，視之往，萬事之生也，異趣而同歸，古今一也。","chunks":[["疑今者，察之古不知來者，視之往，萬事之生也，異趣而同歸，古今一也。","zh-Hant"]]},{"id":"guanzi_ch-2_p-7_s-1","passageId":"guanzi_ch-2_p-7","order":1,"canonicalText":"生棟覆屋。","chunks":[["生棟覆屋。","zh-Hant"]]},{"id":"guanzi_ch-2_p-7_s-2","passageId":"guanzi_ch-2_p-7","order":2,"canonicalText":"怨怒不及；","chunks":[["怨怒不及；","zh-Hant"]]},{"id":"guanzi_ch-2_p-7_s-3","passageId":"guanzi_ch-2_p-7","order":3,"canonicalText":"弱子下瓦，慈母操箠。","chunks":[["弱子下瓦，慈母操箠。","zh-Hant"]]},{"id":"guanzi_ch-2_p-7_s-4","passageId":"guanzi_ch-2_p-7","order":4,"canonicalText":"天道之極，遠者自親。","chunks":[["天道之極，遠者自親。","zh-Hant"]]},{"id":"guanzi_ch-2_p-7_s-5","passageId":"guanzi_ch-2_p-7","order":5,"canonicalText":"人事之起，近親造怨。","chunks":[["人事之起，近親造怨。","zh-Hant"]]},{"id":"guanzi_ch-2_p-7_s-6","passageId":"guanzi_ch-2_p-7","order":6,"canonicalText":"萬物之於人也，無私近也，無私遠也；","chunks":[["萬物之於人也，無私近也，無私遠也；","zh-Hant"]]},{"id":"guanzi_ch-2_p-7_s-7","passageId":"guanzi_ch-2_p-7","order":7,"canonicalText":"巧者有餘，而拙者不足；","chunks":[["巧者有餘，而拙者不足；","zh-Hant"]]},{"id":"guanzi_ch-2_p-7_s-8","passageId":"guanzi_ch-2_p-7","order":8,"canonicalText":"其功順天者天助之，其功逆天者天違之；","chunks":[["其功順天者天助之，其功逆天者天違之；","zh-Hant"]]},{"id":"guanzi_ch-2_p-7_s-9","passageId":"guanzi_ch-2_p-7","order":9,"canonicalText":"天之所助，雖小必大；","chunks":[["天之所助，雖小必大；","zh-Hant"]]},{"id":"guanzi_ch-2_p-7_s-10","passageId":"guanzi_ch-2_p-7","order":10,"canonicalText":"天之所違，雖成必敗；","chunks":[["天之所違，雖成必敗；","zh-Hant"]]},{"id":"guanzi_ch-2_p-7_s-11","passageId":"guanzi_ch-2_p-7","order":11,"canonicalText":"順天者有其功，逆天者懷其兇，不可復振也。","chunks":[["順天者有其功，逆天者懷其兇，不可復振也。","zh-Hant"]]},{"id":"guanzi_ch-2_p-8_s-1","passageId":"guanzi_ch-2_p-8","order":1,"canonicalText":"烏鳥之狡，雖善不親。","chunks":[["烏鳥之狡，雖善不親。","zh-Hant"]]},{"id":"guanzi_ch-2_p-8_s-2","passageId":"guanzi_ch-2_p-8","order":2,"canonicalText":"不重之結，雖固必解；","chunks":[["不重之結，雖固必解；","zh-Hant"]]},{"id":"guanzi_ch-2_p-8_s-3","passageId":"guanzi_ch-2_p-8","order":3,"canonicalText":"道之用也，貴其重也。","chunks":[["道之用也，貴其重也。","zh-Hant"]]},{"id":"guanzi_ch-2_p-8_s-4","passageId":"guanzi_ch-2_p-8","order":4,"canonicalText":"毋與不可，毋彊不能，毋告不知；","chunks":[["毋與不可，毋彊不能，毋告不知；","zh-Hant"]]},{"id":"guanzi_ch-2_p-8_s-5","passageId":"guanzi_ch-2_p-8","order":5,"canonicalText":"與不可，彊不能，告不知，謂之勞而無功。","chunks":[["與不可，彊不能，告不知，謂之勞而無功。","zh-Hant"]]},{"id":"guanzi_ch-2_p-8_s-6","passageId":"guanzi_ch-2_p-8","order":6,"canonicalText":"見與之交，幾於不親；","chunks":[["見與之交，幾於不親；","zh-Hant"]]},{"id":"guanzi_ch-2_p-8_s-7","passageId":"guanzi_ch-2_p-8","order":7,"canonicalText":"見哀之役，幾於不結；","chunks":[["見哀之役，幾於不結；","zh-Hant"]]},{"id":"guanzi_ch-2_p-8_s-8","passageId":"guanzi_ch-2_p-8","order":8,"canonicalText":"見施之德，幾於不報；","chunks":[["見施之德，幾於不報；","zh-Hant"]]},{"id":"guanzi_ch-2_p-8_s-9","passageId":"guanzi_ch-2_p-8","order":9,"canonicalText":"四方所歸，心行者也。","chunks":[["四方所歸，心行者也。","zh-Hant"]]},{"id":"guanzi_ch-2_p-8_s-10","passageId":"guanzi_ch-2_p-8","order":10,"canonicalText":"獨王之國，勞而多禍；","chunks":[["獨王之國，勞而多禍；","zh-Hant"]]},{"id":"guanzi_ch-2_p-8_s-11","passageId":"guanzi_ch-2_p-8","order":11,"canonicalText":"獨國之君，卑而不威；","chunks":[["獨國之君，卑而不威；","zh-Hant"]]},{"id":"guanzi_ch-2_p-8_s-12","passageId":"guanzi_ch-2_p-8","order":12,"canonicalText":"自媒之女，醜而不信，未之見而親焉，可以往矣；","chunks":[["自媒之女，醜而不信，未之見而親焉，可以往矣；","zh-Hant"]]},{"id":"guanzi_ch-2_p-8_s-13","passageId":"guanzi_ch-2_p-8","order":13,"canonicalText":"久而不忘焉，可以來矣。","chunks":[["久而不忘焉，可以來矣。","zh-Hant"]]},{"id":"guanzi_ch-2_p-9_s-1","passageId":"guanzi_ch-2_p-9","order":1,"canonicalText":"日月不明，天不易也；","chunks":[["日月不明，天不易也；","zh-Hant"]]},{"id":"guanzi_ch-2_p-9_s-2","passageId":"guanzi_ch-2_p-9","order":2,"canonicalText":"山高而不見，地不易也。","chunks":[["山高而不見，地不易也。","zh-Hant"]]},{"id":"guanzi_ch-2_p-9_s-3","passageId":"guanzi_ch-2_p-9","order":3,"canonicalText":"言而不可復者，君不言也；","chunks":[["言而不可復者，君不言也；","zh-Hant"]]},{"id":"guanzi_ch-2_p-9_s-4","passageId":"guanzi_ch-2_p-9","order":4,"canonicalText":"行而不可再者，君不行也。","chunks":[["行而不可再者，君不行也。","zh-Hant"]]},{"id":"guanzi_ch-2_p-9_s-5","passageId":"guanzi_ch-2_p-9","order":5,"canonicalText":"凡言而不可復，行而不可再者，有國者之大禁也。","chunks":[["凡言而不可復，行而不可再者，有國者之大禁也。","zh-Hant"]]},{"id":"guanzi_ch-3_p-1_s-1","passageId":"guanzi_ch-3_p-1","order":1,"canonicalText":"萬乘之國，兵不可以無主，土地博大，野不可以無吏，百姓殷眾，官不可以無長，操民之命，朝不可以無政。","chunks":[["萬乘之國，兵不可以無主，土地博大，野不可以無吏，百姓殷眾，官不可以無長，操民之命，朝不可以無政。","zh-Hant"]]},{"id":"guanzi_ch-3_p-2_s-1","passageId":"guanzi_ch-3_p-2","order":1,"canonicalText":"地博而國貧者，野不闢也，民眾而兵弱者，民無取也。","chunks":[["地博而國貧者，野不闢也，民眾而兵弱者，民無取也。","zh-Hant"]]},{"id":"guanzi_ch-3_p-2_s-2","passageId":"guanzi_ch-3_p-2","order":2,"canonicalText":"故末產不禁，則野不闢。","chunks":[["故末產不禁，則野不闢。","zh-Hant"]]},{"id":"guanzi_ch-3_p-2_s-3","passageId":"guanzi_ch-3_p-2","order":3,"canonicalText":"賞罰不信，則民無取。","chunks":[["賞罰不信，則民無取。","zh-Hant"]]},{"id":"guanzi_ch-3_p-2_s-4","passageId":"guanzi_ch-3_p-2","order":4,"canonicalText":"野不闢，民無取，外不可以應敵，內不可以固守，故曰有萬乘之號，而無千乘之用，而求權之無輕，不可得也。","chunks":[["野不闢，民無取，外不可以應敵，內不可以固守，故曰有萬乘之號，而無千乘之用，而求權之無輕，不可得也。","zh-Hant"]]},{"id":"guanzi_ch-3_p-3_s-1","passageId":"guanzi_ch-3_p-3","order":1,"canonicalText":"地闢而國貧者，舟輿飾，臺榭廣也。","chunks":[["地闢而國貧者，舟輿飾，臺榭廣也。","zh-Hant"]]},{"id":"guanzi_ch-3_p-3_s-2","passageId":"guanzi_ch-3_p-3","order":2,"canonicalText":"賞罰信而兵弱者，輕用眾，使民勞也。","chunks":[["賞罰信而兵弱者，輕用眾，使民勞也。","zh-Hant"]]},{"id":"guanzi_ch-3_p-3_s-3","passageId":"guanzi_ch-3_p-3","order":3,"canonicalText":"舟車飾，臺榭廣，則賦斂厚矣。","chunks":[["舟車飾，臺榭廣，則賦斂厚矣。","zh-Hant"]]},{"id":"guanzi_ch-3_p-3_s-4","passageId":"guanzi_ch-3_p-3","order":4,"canonicalText":"輕用眾，使民勞，則民力竭矣。","chunks":[["輕用眾，使民勞，則民力竭矣。","zh-Hant"]]},{"id":"guanzi_ch-3_p-3_s-5","passageId":"guanzi_ch-3_p-3","order":5,"canonicalText":"賦斂厚，則下怨上矣。","chunks":[["賦斂厚，則下怨上矣。","zh-Hant"]]},{"id":"guanzi_ch-3_p-3_s-6","passageId":"guanzi_ch-3_p-3","order":6,"canonicalText":"民力竭，則令不行矣。","chunks":[["民力竭，則令不行矣。","zh-Hant"]]},{"id":"guanzi_ch-3_p-3_s-7","passageId":"guanzi_ch-3_p-3","order":7,"canonicalText":"下怨上，令不行，而求敵之勿謀己，不可得也。","chunks":[["下怨上，令不行，而求敵之勿謀己，不可得也。","zh-Hant"]]},{"id":"guanzi_ch-3_p-4_s-1","passageId":"guanzi_ch-3_p-4","order":1,"canonicalText":"欲為天下者，必重用其國，欲為其國者，必重用其民，欲為其民者，必重盡其民力。","chunks":[["欲為天下者，必重用其國，欲為其國者，必重用其民，欲為其民者，必重盡其民力。","zh-Hant"]]},{"id":"guanzi_ch-3_p-4_s-2","passageId":"guanzi_ch-3_p-4","order":2,"canonicalText":"無以畜之，則往而不可止也；","chunks":[["無以畜之，則往而不可止也；","zh-Hant"]]},{"id":"guanzi_ch-3_p-4_s-3","passageId":"guanzi_ch-3_p-4","order":3,"canonicalText":"無以牧之，則處而不可使也；","chunks":[["無以牧之，則處而不可使也；","zh-Hant"]]},{"id":"guanzi_ch-3_p-4_s-4","passageId":"guanzi_ch-3_p-4","order":4,"canonicalText":"遠人至而不去，則有以畜之也。","chunks":[["遠人至而不去，則有以畜之也。","zh-Hant"]]},{"id":"guanzi_ch-3_p-4_s-5","passageId":"guanzi_ch-3_p-4","order":5,"canonicalText":"民眾而可一，則有以牧之也。","chunks":[["民眾而可一，則有以牧之也。","zh-Hant"]]},{"id":"guanzi_ch-3_p-5_s-1","passageId":"guanzi_ch-3_p-5","order":1,"canonicalText":"見其可也，喜之有徵。","chunks":[["見其可也，喜之有徵。","zh-Hant"]]},{"id":"guanzi_ch-3_p-5_s-2","passageId":"guanzi_ch-3_p-5","order":2,"canonicalText":"見其不可也，惡之有刑。","chunks":[["見其不可也，惡之有刑。","zh-Hant"]]},{"id":"guanzi_ch-3_p-5_s-3","passageId":"guanzi_ch-3_p-5","order":3,"canonicalText":"賞罰信於其所見，雖其所不見，其敢為之乎？","chunks":[["賞罰信於其所見，雖其所不見，其敢為之乎？","zh-Hant"]]},{"id":"guanzi_ch-3_p-5_s-4","passageId":"guanzi_ch-3_p-5","order":4,"canonicalText":"見其可也，喜之無徵；","chunks":[["見其可也，喜之無徵；","zh-Hant"]]},{"id":"guanzi_ch-3_p-5_s-5","passageId":"guanzi_ch-3_p-5","order":5,"canonicalText":"見其不可也，惡之無刑；","chunks":[["見其不可也，惡之無刑；","zh-Hant"]]},{"id":"guanzi_ch-3_p-5_s-6","passageId":"guanzi_ch-3_p-5","order":6,"canonicalText":"賞罰不信於其所見，而求其所不見之為之化，不可得也。","chunks":[["賞罰不信於其所見，而求其所不見之為之化，不可得也。","zh-Hant"]]},{"id":"guanzi_ch-3_p-5_s-7","passageId":"guanzi_ch-3_p-5","order":7,"canonicalText":"厚愛利，足以親之。","chunks":[["厚愛利，足以親之。","zh-Hant"]]},{"id":"guanzi_ch-3_p-5_s-8","passageId":"guanzi_ch-3_p-5","order":8,"canonicalText":"明智禮，足以教之。","chunks":[["明智禮，足以教之。","zh-Hant"]]},{"id":"guanzi_ch-3_p-5_s-9","passageId":"guanzi_ch-3_p-5","order":9,"canonicalText":"上身服以先之。","chunks":[["上身服以先之。","zh-Hant"]]},{"id":"guanzi_ch-3_p-5_s-10","passageId":"guanzi_ch-3_p-5","order":10,"canonicalText":"審度量以閑之。","chunks":[["審度量以閑之。","zh-Hant"]]},{"id":"guanzi_ch-3_p-5_s-11","passageId":"guanzi_ch-3_p-5","order":11,"canonicalText":"鄉置師以說道之，然後申之以憲令，勸之以慶賞，振之以刑罰，故百姓皆說為善，則暴亂之行無由至矣。","chunks":[["鄉置師以說道之，然後申之以憲令，勸之以慶賞，振之以刑罰，故百姓皆說為善，則暴亂之行無由至矣。","zh-Hant"]]},{"id":"guanzi_ch-3_p-6_s-1","passageId":"guanzi_ch-3_p-6","order":1,"canonicalText":"地之生財有時，民之用力有倦，而人君之慾無窮，以有時與有倦，養無窮之君，而度量不生於其間，則上下相疾也。","chunks":[["地之生財有時，民之用力有倦，而人君之慾無窮，以有時與有倦，養無窮之君，而度量不生於其間，則上下相疾也。","zh-Hant"]]},{"id":"guanzi_ch-3_p-6_s-2","passageId":"guanzi_ch-3_p-6","order":2,"canonicalText":"是以臣有殺其君，子有殺其父者矣。","chunks":[["是以臣有殺其君，子有殺其父者矣。","zh-Hant"]]},{"id":"guanzi_ch-3_p-6_s-3","passageId":"guanzi_ch-3_p-6","order":3,"canonicalText":"故取於民有度，用之有止，國雖小必安；","chunks":[["故取於民有度，用之有止，國雖小必安；","zh-Hant"]]},{"id":"guanzi_ch-3_p-6_s-4","passageId":"guanzi_ch-3_p-6","order":4,"canonicalText":"取於民無度，用之不止，國雖大必危。","chunks":[["取於民無度，用之不止，國雖大必危。","zh-Hant"]]},{"id":"guanzi_ch-3_p-7_s-1","passageId":"guanzi_ch-3_p-7","order":1,"canonicalText":"地之不闢者，非吾地也。","chunks":[["地之不闢者，非吾地也。","zh-Hant"]]},{"id":"guanzi_ch-3_p-7_s-2","passageId":"guanzi_ch-3_p-7","order":2,"canonicalText":"民之不牧者，非吾民也。","chunks":[["民之不牧者，非吾民也。","zh-Hant"]]},{"id":"guanzi_ch-3_p-7_s-3","passageId":"guanzi_ch-3_p-7","order":3,"canonicalText":"凡牧民者。","chunks":[["凡牧民者。","zh-Hant"]]},{"id":"guanzi_ch-3_p-7_s-4","passageId":"guanzi_ch-3_p-7","order":4,"canonicalText":"以其所積者食之。","chunks":[["以其所積者食之。","zh-Hant"]]},{"id":"guanzi_ch-3_p-7_s-5","passageId":"guanzi_ch-3_p-7","order":5,"canonicalText":"不可不審也。","chunks":[["不可不審也。","zh-Hant"]]},{"id":"guanzi_ch-3_p-7_s-6","passageId":"guanzi_ch-3_p-7","order":6,"canonicalText":"其積多者其食多，其積寡者其食寡，無積者不食。","chunks":[["其積多者其食多，其積寡者其食寡，無積者不食。","zh-Hant"]]},{"id":"guanzi_ch-3_p-7_s-7","passageId":"guanzi_ch-3_p-7","order":7,"canonicalText":"或有積而不食者，則民離上；","chunks":[["或有積而不食者，則民離上；","zh-Hant"]]},{"id":"guanzi_ch-3_p-7_s-8","passageId":"guanzi_ch-3_p-7","order":8,"canonicalText":"有積多而食寡者，則民不力；","chunks":[["有積多而食寡者，則民不力；","zh-Hant"]]},{"id":"guanzi_ch-3_p-7_s-9","passageId":"guanzi_ch-3_p-7","order":9,"canonicalText":"有積寡而食多者，則民多軸；","chunks":[["有積寡而食多者，則民多軸；","zh-Hant"]]},{"id":"guanzi_ch-3_p-7_s-10","passageId":"guanzi_ch-3_p-7","order":10,"canonicalText":"有無積而徒食者，則民偷幸；","chunks":[["有無積而徒食者，則民偷幸；","zh-Hant"]]},{"id":"guanzi_ch-3_p-7_s-11","passageId":"guanzi_ch-3_p-7","order":11,"canonicalText":"故離上不力，多軸偷幸，舉事不成，應敵不用。","chunks":[["故離上不力，多軸偷幸，舉事不成，應敵不用。","zh-Hant"]]},{"id":"guanzi_ch-3_p-7_s-12","passageId":"guanzi_ch-3_p-7","order":12,"canonicalText":"故曰：察能授官，班祿賜予，使民之機也。","chunks":[["故曰：察能授官，班祿賜予，使民之機也。","zh-Hant"]]},{"id":"guanzi_ch-3_p-7_s-13","passageId":"guanzi_ch-3_p-7","order":13,"canonicalText":"野與市爭民。","chunks":[["野與市爭民。","zh-Hant"]]},{"id":"guanzi_ch-3_p-7_s-14","passageId":"guanzi_ch-3_p-7","order":14,"canonicalText":"家與府爭貨，金與粟爭貴，鄉與朝爭治；","chunks":[["家與府爭貨，金與粟爭貴，鄉與朝爭治；","zh-Hant"]]},{"id":"guanzi_ch-3_p-7_s-15","passageId":"guanzi_ch-3_p-7","order":15,"canonicalText":"故野不積草，農事先也；","chunks":[["故野不積草，農事先也；","zh-Hant"]]},{"id":"guanzi_ch-3_p-7_s-16","passageId":"guanzi_ch-3_p-7","order":16,"canonicalText":"府不積貨，藏於民也；","chunks":[["府不積貨，藏於民也；","zh-Hant"]]},{"id":"guanzi_ch-3_p-7_s-17","passageId":"guanzi_ch-3_p-7","order":17,"canonicalText":"市不成肆，家用足也；","chunks":[["市不成肆，家用足也；","zh-Hant"]]},{"id":"guanzi_ch-3_p-7_s-18","passageId":"guanzi_ch-3_p-7","order":18,"canonicalText":"朝不合眾，鄉分治也。","chunks":[["朝不合眾，鄉分治也。","zh-Hant"]]},{"id":"guanzi_ch-3_p-7_s-19","passageId":"guanzi_ch-3_p-7","order":19,"canonicalText":"故野不積草，府不積貨，市不成肆。","chunks":[["故野不積草，府不積貨，市不成肆。","zh-Hant"]]},{"id":"guanzi_ch-3_p-7_s-20","passageId":"guanzi_ch-3_p-7","order":20,"canonicalText":"朝不合眾，治之至也。","chunks":[["朝不合眾，治之至也。","zh-Hant"]]},{"id":"guanzi_ch-3_p-8_s-1","passageId":"guanzi_ch-3_p-8","order":1,"canonicalText":"人情不二，故民情可得而御也。","chunks":[["人情不二，故民情可得而御也。","zh-Hant"]]},{"id":"guanzi_ch-3_p-8_s-2","passageId":"guanzi_ch-3_p-8","order":2,"canonicalText":"審其所好惡，則其長短可知也；","chunks":[["審其所好惡，則其長短可知也；","zh-Hant"]]},{"id":"guanzi_ch-3_p-8_s-3","passageId":"guanzi_ch-3_p-8","order":3,"canonicalText":"觀其交遊，則其賢不肖可察也；","chunks":[["觀其交遊，則其賢不肖可察也；","zh-Hant"]]},{"id":"guanzi_ch-3_p-8_s-4","passageId":"guanzi_ch-3_p-8","order":4,"canonicalText":"二者不失，則民能可得而官也。","chunks":[["二者不失，則民能可得而官也。","zh-Hant"]]},{"id":"guanzi_ch-3_p-9_s-1","passageId":"guanzi_ch-3_p-9","order":1,"canonicalText":"地之守在城，城之守在兵，兵之守在人，人之守在粟；","chunks":[["地之守在城，城之守在兵，兵之守在人，人之守在粟；","zh-Hant"]]},{"id":"guanzi_ch-3_p-9_s-2","passageId":"guanzi_ch-3_p-9","order":2,"canonicalText":"故地不闢，則城不固。","chunks":[["故地不闢，則城不固。","zh-Hant"]]},{"id":"guanzi_ch-3_p-9_s-3","passageId":"guanzi_ch-3_p-9","order":3,"canonicalText":"有身不治，奚待於人？","chunks":[["有身不治，奚待於人？","zh-Hant"]]},{"id":"guanzi_ch-3_p-9_s-4","passageId":"guanzi_ch-3_p-9","order":4,"canonicalText":"有人不治，奚待於家？","chunks":[["有人不治，奚待於家？","zh-Hant"]]},{"id":"guanzi_ch-3_p-9_s-5","passageId":"guanzi_ch-3_p-9","order":5,"canonicalText":"有家不治，奚待於鄉？","chunks":[["有家不治，奚待於鄉？","zh-Hant"]]},{"id":"guanzi_ch-3_p-9_s-6","passageId":"guanzi_ch-3_p-9","order":6,"canonicalText":"有鄉不治，奚待於國？","chunks":[["有鄉不治，奚待於國？","zh-Hant"]]},{"id":"guanzi_ch-3_p-9_s-7","passageId":"guanzi_ch-3_p-9","order":7,"canonicalText":"有國不治，奚待於天下？","chunks":[["有國不治，奚待於天下？","zh-Hant"]]},{"id":"guanzi_ch-3_p-9_s-8","passageId":"guanzi_ch-3_p-9","order":8,"canonicalText":"天下者，國之本也；","chunks":[["天下者，國之本也；","zh-Hant"]]},{"id":"guanzi_ch-3_p-9_s-9","passageId":"guanzi_ch-3_p-9","order":9,"canonicalText":"國者，鄉之本也；","chunks":[["國者，鄉之本也；","zh-Hant"]]},{"id":"guanzi_ch-3_p-9_s-10","passageId":"guanzi_ch-3_p-9","order":10,"canonicalText":"鄉者，家之本也；","chunks":[["鄉者，家之本也；","zh-Hant"]]},{"id":"guanzi_ch-3_p-9_s-11","passageId":"guanzi_ch-3_p-9","order":11,"canonicalText":"家者，人之本也；","chunks":[["家者，人之本也；","zh-Hant"]]},{"id":"guanzi_ch-3_p-9_s-12","passageId":"guanzi_ch-3_p-9","order":12,"canonicalText":"人者，身之本也；","chunks":[["人者，身之本也；","zh-Hant"]]},{"id":"guanzi_ch-3_p-9_s-13","passageId":"guanzi_ch-3_p-9","order":13,"canonicalText":"身者，治之本也。","chunks":[["身者，治之本也。","zh-Hant"]]},{"id":"guanzi_ch-3_p-9_s-14","passageId":"guanzi_ch-3_p-9","order":14,"canonicalText":"故上不好本事，則末產不禁；","chunks":[["故上不好本事，則末產不禁；","zh-Hant"]]},{"id":"guanzi_ch-3_p-9_s-15","passageId":"guanzi_ch-3_p-9","order":15,"canonicalText":"末產不禁，則民緩於時事而輕地利；","chunks":[["末產不禁，則民緩於時事而輕地利；","zh-Hant"]]},{"id":"guanzi_ch-3_p-9_s-16","passageId":"guanzi_ch-3_p-9","order":16,"canonicalText":"輕地利，而求田野之闢，倉廩之實，不可得也。","chunks":[["輕地利，而求田野之闢，倉廩之實，不可得也。","zh-Hant"]]},{"id":"guanzi_ch-3_p-10_s-1","passageId":"guanzi_ch-3_p-10","order":1,"canonicalText":"商賈在朝，則貨財上流；","chunks":[["商賈在朝，則貨財上流；","zh-Hant"]]},{"id":"guanzi_ch-3_p-10_s-2","passageId":"guanzi_ch-3_p-10","order":2,"canonicalText":"婦言人事，則賞罰不信；","chunks":[["婦言人事，則賞罰不信；","zh-Hant"]]},{"id":"guanzi_ch-3_p-10_s-3","passageId":"guanzi_ch-3_p-10","order":3,"canonicalText":"男女無別，則民無廉恥；","chunks":[["男女無別，則民無廉恥；","zh-Hant"]]},{"id":"guanzi_ch-3_p-10_s-4","passageId":"guanzi_ch-3_p-10","order":4,"canonicalText":"貨財上流，賞罰不信，民無廉恥，而求百姓之安難，兵士之死節，不可得也。","chunks":[["貨財上流，賞罰不信，民無廉恥，而求百姓之安難，兵士之死節，不可得也。","zh-Hant"]]},{"id":"guanzi_ch-3_p-10_s-5","passageId":"guanzi_ch-3_p-10","order":5,"canonicalText":"朝廷不肅，貴賤不明，長幼不分，度量不審，衣服無等，上下淩節，而求百姓之尊主政令，不可得也。","chunks":[["朝廷不肅，貴賤不明，長幼不分，度量不審，衣服無等，上下淩節，而求百姓之尊主政令，不可得也。","zh-Hant"]]},{"id":"guanzi_ch-3_p-10_s-6","passageId":"guanzi_ch-3_p-10","order":6,"canonicalText":"上好軸謀閒欺，臣下賦斂競得，使民偷壹，則百姓疾怨，而求下之親上，不可得也。","chunks":[["上好軸謀閒欺，臣下賦斂競得，使民偷壹，則百姓疾怨，而求下之親上，不可得也。","zh-Hant"]]},{"id":"guanzi_ch-3_p-10_s-7","passageId":"guanzi_ch-3_p-10","order":7,"canonicalText":"有地不務本事，君國不能壹民，而求宗廟社稷之無危，不可得也。","chunks":[["有地不務本事，君國不能壹民，而求宗廟社稷之無危，不可得也。","zh-Hant"]]},{"id":"guanzi_ch-3_p-10_s-8","passageId":"guanzi_ch-3_p-10","order":8,"canonicalText":"上恃龜筮，好用巫醫，則鬼神驟祟；","chunks":[["上恃龜筮，好用巫醫，則鬼神驟祟；","zh-Hant"]]},{"id":"guanzi_ch-3_p-10_s-9","passageId":"guanzi_ch-3_p-10","order":9,"canonicalText":"故功之不立，名之不章，為之患者三：有獨王者、有貧賤者、有日不足者。","chunks":[["故功之不立，名之不章，為之患者三：有獨王者、有貧賤者、有日不足者。","zh-Hant"]]},{"id":"guanzi_ch-3_p-11_s-1","passageId":"guanzi_ch-3_p-11","order":1,"canonicalText":"一年之計，莫如樹穀；","chunks":[["一年之計，莫如樹穀；","zh-Hant"]]},{"id":"guanzi_ch-3_p-11_s-2","passageId":"guanzi_ch-3_p-11","order":2,"canonicalText":"十年之計，莫如樹木；","chunks":[["十年之計，莫如樹木；","zh-Hant"]]},{"id":"guanzi_ch-3_p-11_s-3","passageId":"guanzi_ch-3_p-11","order":3,"canonicalText":"終身之計，莫如樹人。","chunks":[["終身之計，莫如樹人。","zh-Hant"]]},{"id":"guanzi_ch-3_p-11_s-4","passageId":"guanzi_ch-3_p-11","order":4,"canonicalText":"一樹一穫者，穀也；","chunks":[["一樹一穫者，穀也；","zh-Hant"]]},{"id":"guanzi_ch-3_p-11_s-5","passageId":"guanzi_ch-3_p-11","order":5,"canonicalText":"一樹十穫者，木也；","chunks":[["一樹十穫者，木也；","zh-Hant"]]},{"id":"guanzi_ch-3_p-11_s-6","passageId":"guanzi_ch-3_p-11","order":6,"canonicalText":"一樹百穫者，人也。","chunks":[["一樹百穫者，人也。","zh-Hant"]]},{"id":"guanzi_ch-3_p-11_s-7","passageId":"guanzi_ch-3_p-11","order":7,"canonicalText":"我苟種之，如神用之，舉事如神，唯王之門。","chunks":[["我苟種之，如神用之，舉事如神，唯王之門。","zh-Hant"]]},{"id":"guanzi_ch-3_p-12_s-1","passageId":"guanzi_ch-3_p-12","order":1,"canonicalText":"凡牧民者，使士無邪行，女無淫事。","chunks":[["凡牧民者，使士無邪行，女無淫事。","zh-Hant"]]},{"id":"guanzi_ch-3_p-12_s-2","passageId":"guanzi_ch-3_p-12","order":2,"canonicalText":"士無邪行，教也。","chunks":[["士無邪行，教也。","zh-Hant"]]},{"id":"guanzi_ch-3_p-12_s-3","passageId":"guanzi_ch-3_p-12","order":3,"canonicalText":"女無淫事，訓也。","chunks":[["女無淫事，訓也。","zh-Hant"]]},{"id":"guanzi_ch-3_p-12_s-4","passageId":"guanzi_ch-3_p-12","order":4,"canonicalText":"教訓成俗，而刑罰省，數也。","chunks":[["教訓成俗，而刑罰省，數也。","zh-Hant"]]},{"id":"guanzi_ch-3_p-12_s-5","passageId":"guanzi_ch-3_p-12","order":5,"canonicalText":"凡牧民者，欲民之正也；","chunks":[["凡牧民者，欲民之正也；","zh-Hant"]]},{"id":"guanzi_ch-3_p-12_s-6","passageId":"guanzi_ch-3_p-12","order":6,"canonicalText":"欲民之正，則微邪不可不禁也；","chunks":[["欲民之正，則微邪不可不禁也；","zh-Hant"]]},{"id":"guanzi_ch-3_p-12_s-7","passageId":"guanzi_ch-3_p-12","order":7,"canonicalText":"微邪者，大邪之所生也；","chunks":[["微邪者，大邪之所生也；","zh-Hant"]]},{"id":"guanzi_ch-3_p-12_s-8","passageId":"guanzi_ch-3_p-12","order":8,"canonicalText":"微邪不禁，而求大邪之無傷國，不可得也。","chunks":[["微邪不禁，而求大邪之無傷國，不可得也。","zh-Hant"]]},{"id":"guanzi_ch-3_p-12_s-9","passageId":"guanzi_ch-3_p-12","order":9,"canonicalText":"凡牧民者，欲民之有禮也；","chunks":[["凡牧民者，欲民之有禮也；","zh-Hant"]]},{"id":"guanzi_ch-3_p-12_s-10","passageId":"guanzi_ch-3_p-12","order":10,"canonicalText":"欲民之有禮，則小禮不可不謹也；","chunks":[["欲民之有禮，則小禮不可不謹也；","zh-Hant"]]},{"id":"guanzi_ch-3_p-12_s-11","passageId":"guanzi_ch-3_p-12","order":11,"canonicalText":"小禮不謹於國，而求百姓之行大禮，不可得也。","chunks":[["小禮不謹於國，而求百姓之行大禮，不可得也。","zh-Hant"]]},{"id":"guanzi_ch-3_p-13_s-1","passageId":"guanzi_ch-3_p-13","order":1,"canonicalText":"凡牧民者，欲民之有義也；","chunks":[["凡牧民者，欲民之有義也；","zh-Hant"]]},{"id":"guanzi_ch-3_p-13_s-2","passageId":"guanzi_ch-3_p-13","order":2,"canonicalText":"欲民之有義，則小義不可不行；","chunks":[["欲民之有義，則小義不可不行；","zh-Hant"]]},{"id":"guanzi_ch-3_p-13_s-3","passageId":"guanzi_ch-3_p-13","order":3,"canonicalText":"小義不行於國，而求百姓之行大義，不可得也。","chunks":[["小義不行於國，而求百姓之行大義，不可得也。","zh-Hant"]]},{"id":"guanzi_ch-3_p-13_s-4","passageId":"guanzi_ch-3_p-13","order":4,"canonicalText":"凡牧民者，欲民之有廉也；","chunks":[["凡牧民者，欲民之有廉也；","zh-Hant"]]},{"id":"guanzi_ch-3_p-13_s-5","passageId":"guanzi_ch-3_p-13","order":5,"canonicalText":"欲民之有廉，則小廉不可不修也；","chunks":[["欲民之有廉，則小廉不可不修也；","zh-Hant"]]},{"id":"guanzi_ch-3_p-13_s-6","passageId":"guanzi_ch-3_p-13","order":6,"canonicalText":"小廉不修於國，而求百姓之行大廉，不可得也。","chunks":[["小廉不修於國，而求百姓之行大廉，不可得也。","zh-Hant"]]},{"id":"guanzi_ch-3_p-13_s-7","passageId":"guanzi_ch-3_p-13","order":7,"canonicalText":"凡牧民者，欲民之有恥也，欲民之有恥，則小恥不可不飾也。","chunks":[["凡牧民者，欲民之有恥也，欲民之有恥，則小恥不可不飾也。","zh-Hant"]]},{"id":"guanzi_ch-3_p-13_s-8","passageId":"guanzi_ch-3_p-13","order":8,"canonicalText":"小恥不飾於國，而求百姓之行大恥，不可得也。","chunks":[["小恥不飾於國，而求百姓之行大恥，不可得也。","zh-Hant"]]},{"id":"guanzi_ch-3_p-13_s-9","passageId":"guanzi_ch-3_p-13","order":9,"canonicalText":"凡牧民者，欲民之修小禮、行小義、飾小廉、謹小恥、禁微邪、此厲民之道也。","chunks":[["凡牧民者，欲民之修小禮、行小義、飾小廉、謹小恥、禁微邪、此厲民之道也。","zh-Hant"]]},{"id":"guanzi_ch-3_p-13_s-10","passageId":"guanzi_ch-3_p-13","order":10,"canonicalText":"民之修小禮、行小義、飾小廉、謹小恥、禁微邪、治之本也。","chunks":[["民之修小禮、行小義、飾小廉、謹小恥、禁微邪、治之本也。","zh-Hant"]]},{"id":"guanzi_ch-3_p-13_s-11","passageId":"guanzi_ch-3_p-13","order":11,"canonicalText":"凡牧民者，欲民之可御也；","chunks":[["凡牧民者，欲民之可御也；","zh-Hant"]]},{"id":"guanzi_ch-3_p-13_s-12","passageId":"guanzi_ch-3_p-13","order":12,"canonicalText":"欲民之可御，則法不可不審；","chunks":[["欲民之可御，則法不可不審；","zh-Hant"]]},{"id":"guanzi_ch-3_p-13_s-13","passageId":"guanzi_ch-3_p-13","order":13,"canonicalText":"法者，將立朝廷者也；","chunks":[["法者，將立朝廷者也；","zh-Hant"]]},{"id":"guanzi_ch-3_p-13_s-14","passageId":"guanzi_ch-3_p-13","order":14,"canonicalText":"將立朝廷者，則爵服不可不貴也；","chunks":[["將立朝廷者，則爵服不可不貴也；","zh-Hant"]]},{"id":"guanzi_ch-3_p-13_s-15","passageId":"guanzi_ch-3_p-13","order":15,"canonicalText":"爵服加於不義，則民賤其爵服；","chunks":[["爵服加於不義，則民賤其爵服；","zh-Hant"]]},{"id":"guanzi_ch-3_p-13_s-16","passageId":"guanzi_ch-3_p-13","order":16,"canonicalText":"民賤其爵服，則人主不尊；","chunks":[["民賤其爵服，則人主不尊；","zh-Hant"]]},{"id":"guanzi_ch-3_p-13_s-17","passageId":"guanzi_ch-3_p-13","order":17,"canonicalText":"人主不尊，則令不行矣。","chunks":[["人主不尊，則令不行矣。","zh-Hant"]]},{"id":"guanzi_ch-3_p-13_s-18","passageId":"guanzi_ch-3_p-13","order":18,"canonicalText":"法者，將用民力者也；","chunks":[["法者，將用民力者也；","zh-Hant"]]},{"id":"guanzi_ch-3_p-13_s-19","passageId":"guanzi_ch-3_p-13","order":19,"canonicalText":"將用民力者，則祿賞不可不重也；","chunks":[["將用民力者，則祿賞不可不重也；","zh-Hant"]]},{"id":"guanzi_ch-3_p-13_s-20","passageId":"guanzi_ch-3_p-13","order":20,"canonicalText":"祿賞加於無功，則民輕其祿賞；","chunks":[["祿賞加於無功，則民輕其祿賞；","zh-Hant"]]},{"id":"guanzi_ch-3_p-13_s-21","passageId":"guanzi_ch-3_p-13","order":21,"canonicalText":"民輕其祿賞，則上無以勸民；","chunks":[["民輕其祿賞，則上無以勸民；","zh-Hant"]]},{"id":"guanzi_ch-3_p-13_s-22","passageId":"guanzi_ch-3_p-13","order":22,"canonicalText":"上無以勸民，則令不行矣。","chunks":[["上無以勸民，則令不行矣。","zh-Hant"]]},{"id":"guanzi_ch-3_p-13_s-23","passageId":"guanzi_ch-3_p-13","order":23,"canonicalText":"法者，將用民能者也；","chunks":[["法者，將用民能者也；","zh-Hant"]]},{"id":"guanzi_ch-3_p-13_s-24","passageId":"guanzi_ch-3_p-13","order":24,"canonicalText":"將用民能者，則授官不可不審也；","chunks":[["將用民能者，則授官不可不審也；","zh-Hant"]]},{"id":"guanzi_ch-3_p-13_s-25","passageId":"guanzi_ch-3_p-13","order":25,"canonicalText":"授官不審，則民閒其治；","chunks":[["授官不審，則民閒其治；","zh-Hant"]]},{"id":"guanzi_ch-3_p-13_s-26","passageId":"guanzi_ch-3_p-13","order":26,"canonicalText":"民閒其治，則理不上通；","chunks":[["民閒其治，則理不上通；","zh-Hant"]]},{"id":"guanzi_ch-3_p-13_s-27","passageId":"guanzi_ch-3_p-13","order":27,"canonicalText":"理不上通，則下怨其上；","chunks":[["理不上通，則下怨其上；","zh-Hant"]]},{"id":"guanzi_ch-3_p-13_s-28","passageId":"guanzi_ch-3_p-13","order":28,"canonicalText":"下怨其上，則令不行矣。","chunks":[["下怨其上，則令不行矣。","zh-Hant"]]},{"id":"guanzi_ch-3_p-13_s-29","passageId":"guanzi_ch-3_p-13","order":29,"canonicalText":"法者，將用民之死命者也；","chunks":[["法者，將用民之死命者也；","zh-Hant"]]},{"id":"guanzi_ch-3_p-13_s-30","passageId":"guanzi_ch-3_p-13","order":30,"canonicalText":"用民之死命者，則刑罰不可不審；","chunks":[["用民之死命者，則刑罰不可不審；","zh-Hant"]]},{"id":"guanzi_ch-3_p-13_s-31","passageId":"guanzi_ch-3_p-13","order":31,"canonicalText":"刑罰不審，則有闢就；","chunks":[["刑罰不審，則有闢就；","zh-Hant"]]},{"id":"guanzi_ch-3_p-13_s-32","passageId":"guanzi_ch-3_p-13","order":32,"canonicalText":"有闢就，則殺不辜而赦有罪；","chunks":[["有闢就，則殺不辜而赦有罪；","zh-Hant"]]},{"id":"guanzi_ch-3_p-13_s-33","passageId":"guanzi_ch-3_p-13","order":33,"canonicalText":"殺不辜而赦有罪，則國不免於賊臣矣。","chunks":[["殺不辜而赦有罪，則國不免於賊臣矣。","zh-Hant"]]},{"id":"guanzi_ch-3_p-13_s-34","passageId":"guanzi_ch-3_p-13","order":34,"canonicalText":"故夫爵服賤、祿賞輕、民閒其治、賊臣首難，此謂敗國之教也。","chunks":[["故夫爵服賤、祿賞輕、民閒其治、賊臣首難，此謂敗國之教也。","zh-Hant"]]},{"id":"guanzi_ch-4_p-1_s-1","passageId":"guanzi_ch-4_p-1","order":1,"canonicalText":"國之所以治亂者三，殺戮刑罰，不足用也。","chunks":[["國之所以治亂者三，殺戮刑罰，不足用也。","zh-Hant"]]},{"id":"guanzi_ch-4_p-1_s-2","passageId":"guanzi_ch-4_p-1","order":2,"canonicalText":"國之所以安危者四，城郭險阻，不足守也。","chunks":[["國之所以安危者四，城郭險阻，不足守也。","zh-Hant"]]},{"id":"guanzi_ch-4_p-1_s-3","passageId":"guanzi_ch-4_p-1","order":3,"canonicalText":"國之所以富貧者五，輕稅租，薄賦斂，不足恃也。","chunks":[["國之所以富貧者五，輕稅租，薄賦斂，不足恃也。","zh-Hant"]]},{"id":"guanzi_ch-4_p-1_s-4","passageId":"guanzi_ch-4_p-1","order":4,"canonicalText":"治國有三本，而安國有四固，而富國有五事，五事五經也。","chunks":[["治國有三本，而安國有四固，而富國有五事，五事五經也。","zh-Hant"]]},{"id":"guanzi_ch-4_p-2_s-1","passageId":"guanzi_ch-4_p-2","order":1,"canonicalText":"君之所審者三：一曰德不當其位；","chunks":[["君之所審者三：一曰德不當其位；","zh-Hant"]]},{"id":"guanzi_ch-4_p-2_s-2","passageId":"guanzi_ch-4_p-2","order":2,"canonicalText":"二曰功不當其祿；","chunks":[["二曰功不當其祿；","zh-Hant"]]},{"id":"guanzi_ch-4_p-2_s-3","passageId":"guanzi_ch-4_p-2","order":3,"canonicalText":"三曰能不當其官；","chunks":[["三曰能不當其官；","zh-Hant"]]},{"id":"guanzi_ch-4_p-2_s-4","passageId":"guanzi_ch-4_p-2","order":4,"canonicalText":"此三本者，治亂之原也；","chunks":[["此三本者，治亂之原也；","zh-Hant"]]},{"id":"guanzi_ch-4_p-2_s-5","passageId":"guanzi_ch-4_p-2","order":5,"canonicalText":"故國有德義未明於朝者，則不可加以尊位；","chunks":[["故國有德義未明於朝者，則不可加以尊位；","zh-Hant"]]},{"id":"guanzi_ch-4_p-2_s-6","passageId":"guanzi_ch-4_p-2","order":6,"canonicalText":"功力未見於國者，則不可授與重祿；","chunks":[["功力未見於國者，則不可授與重祿；","zh-Hant"]]},{"id":"guanzi_ch-4_p-2_s-7","passageId":"guanzi_ch-4_p-2","order":7,"canonicalText":"臨事不信於民者，則不可使任大官；","chunks":[["臨事不信於民者，則不可使任大官；","zh-Hant"]]},{"id":"guanzi_ch-4_p-2_s-8","passageId":"guanzi_ch-4_p-2","order":8,"canonicalText":"故德厚而位卑者謂之過；","chunks":[["故德厚而位卑者謂之過；","zh-Hant"]]},{"id":"guanzi_ch-4_p-2_s-9","passageId":"guanzi_ch-4_p-2","order":9,"canonicalText":"德薄而位尊者謂之失；","chunks":[["德薄而位尊者謂之失；","zh-Hant"]]},{"id":"guanzi_ch-4_p-2_s-10","passageId":"guanzi_ch-4_p-2","order":10,"canonicalText":"寧過於君子，而毋失於小人；","chunks":[["寧過於君子，而毋失於小人；","zh-Hant"]]},{"id":"guanzi_ch-4_p-2_s-11","passageId":"guanzi_ch-4_p-2","order":11,"canonicalText":"過於君子，其為怨淺；","chunks":[["過於君子，其為怨淺；","zh-Hant"]]},{"id":"guanzi_ch-4_p-2_s-12","passageId":"guanzi_ch-4_p-2","order":12,"canonicalText":"失於小人，其為禍深；","chunks":[["失於小人，其為禍深；","zh-Hant"]]},{"id":"guanzi_ch-4_p-2_s-13","passageId":"guanzi_ch-4_p-2","order":13,"canonicalText":"是故國有德義未明於朝而處尊位者，則良臣不進；","chunks":[["是故國有德義未明於朝而處尊位者，則良臣不進；","zh-Hant"]]},{"id":"guanzi_ch-4_p-2_s-14","passageId":"guanzi_ch-4_p-2","order":14,"canonicalText":"有功力未見於國而有重祿者，則勞臣不勸；","chunks":[["有功力未見於國而有重祿者，則勞臣不勸；","zh-Hant"]]},{"id":"guanzi_ch-4_p-2_s-15","passageId":"guanzi_ch-4_p-2","order":15,"canonicalText":"有臨事不信於民而任大官者，則材臣不用；","chunks":[["有臨事不信於民而任大官者，則材臣不用；","zh-Hant"]]},{"id":"guanzi_ch-4_p-2_s-16","passageId":"guanzi_ch-4_p-2","order":16,"canonicalText":"三本者審，則下不敢求；","chunks":[["三本者審，則下不敢求；","zh-Hant"]]},{"id":"guanzi_ch-4_p-2_s-17","passageId":"guanzi_ch-4_p-2","order":17,"canonicalText":"三本者不審，則邪臣上通，而便辟制威；","chunks":[["三本者不審，則邪臣上通，而便辟制威；","zh-Hant"]]},{"id":"guanzi_ch-4_p-2_s-18","passageId":"guanzi_ch-4_p-2","order":18,"canonicalText":"如此，則明塞於上，而治壅於下，正道捐棄，而邪事日長。","chunks":[["如此，則明塞於上，而治壅於下，正道捐棄，而邪事日長。","zh-Hant"]]},{"id":"guanzi_ch-4_p-2_s-19","passageId":"guanzi_ch-4_p-2","order":19,"canonicalText":"三本者審，則便辟無威於國，道塗無行禽，疏遠無蔽獄，孤寡無隱治，故曰：「刑省治寡，朝不合眾」。","chunks":[["三本者審，則便辟無威於國，道塗無行禽，疏遠無蔽獄，孤寡無隱治，故曰：「刑省治寡，朝不合眾」。","zh-Hant"]]},{"id":"guanzi_ch-4_p-3_s-1","passageId":"guanzi_ch-4_p-3","order":1,"canonicalText":"右三本","chunks":[["右三本","zh-Hant"]]},{"id":"guanzi_ch-4_p-4_s-1","passageId":"guanzi_ch-4_p-4","order":1,"canonicalText":"君之所慎者四：一曰大德不至仁，不可以授國柄。","chunks":[["君之所慎者四：一曰大德不至仁，不可以授國柄。","zh-Hant"]]},{"id":"guanzi_ch-4_p-4_s-2","passageId":"guanzi_ch-4_p-4","order":2,"canonicalText":"二曰見賢不能讓，不可與尊位。","chunks":[["二曰見賢不能讓，不可與尊位。","zh-Hant"]]},{"id":"guanzi_ch-4_p-4_s-3","passageId":"guanzi_ch-4_p-4","order":3,"canonicalText":"三曰罰避親貴，不可使主兵。","chunks":[["三曰罰避親貴，不可使主兵。","zh-Hant"]]},{"id":"guanzi_ch-4_p-4_s-4","passageId":"guanzi_ch-4_p-4","order":4,"canonicalText":"四曰不好本事，不務地利，而輕賦斂，不可與都邑。","chunks":[["四曰不好本事，不務地利，而輕賦斂，不可與都邑。","zh-Hant"]]},{"id":"guanzi_ch-4_p-4_s-5","passageId":"guanzi_ch-4_p-4","order":5,"canonicalText":"此四務者，安危之本也。","chunks":[["此四務者，安危之本也。","zh-Hant"]]},{"id":"guanzi_ch-4_p-4_s-6","passageId":"guanzi_ch-4_p-4","order":6,"canonicalText":"故曰：「卿相不得眾，國之危也。","chunks":[["故曰：「卿相不得眾，國之危也。","zh-Hant"]]},{"id":"guanzi_ch-4_p-4_s-7","passageId":"guanzi_ch-4_p-4","order":7,"canonicalText":"大臣不和同，國之危也。","chunks":[["大臣不和同，國之危也。","zh-Hant"]]},{"id":"guanzi_ch-4_p-4_s-8","passageId":"guanzi_ch-4_p-4","order":8,"canonicalText":"兵主不足畏，國之危也。","chunks":[["兵主不足畏，國之危也。","zh-Hant"]]},{"id":"guanzi_ch-4_p-4_s-9","passageId":"guanzi_ch-4_p-4","order":9,"canonicalText":"民不懷其產，國之危也。","chunks":[["民不懷其產，國之危也。","zh-Hant"]]},{"id":"guanzi_ch-4_p-4_s-10","passageId":"guanzi_ch-4_p-4","order":10,"canonicalText":"」故大德至仁，則操國得眾。","chunks":[["」故大德至仁，則操國得眾。","zh-Hant"]]},{"id":"guanzi_ch-4_p-4_s-11","passageId":"guanzi_ch-4_p-4","order":11,"canonicalText":"見賢能讓，則大臣和同。","chunks":[["見賢能讓，則大臣和同。","zh-Hant"]]},{"id":"guanzi_ch-4_p-4_s-12","passageId":"guanzi_ch-4_p-4","order":12,"canonicalText":"罰不避親貴，則威行於鄰敵。","chunks":[["罰不避親貴，則威行於鄰敵。","zh-Hant"]]},{"id":"guanzi_ch-4_p-4_s-13","passageId":"guanzi_ch-4_p-4","order":13,"canonicalText":"好本事，務地利，重賦斂，則民懷其產。","chunks":[["好本事，務地利，重賦斂，則民懷其產。","zh-Hant"]]},{"id":"guanzi_ch-4_p-5_s-1","passageId":"guanzi_ch-4_p-5","order":1,"canonicalText":"右四固","chunks":[["右四固","zh-Hant"]]},{"id":"guanzi_ch-4_p-6_s-1","passageId":"guanzi_ch-4_p-6","order":1,"canonicalText":"君之所務者五：一曰山澤不救於火，草木不植成，國之貧也。","chunks":[["君之所務者五：一曰山澤不救於火，草木不植成，國之貧也。","zh-Hant"]]},{"id":"guanzi_ch-4_p-6_s-2","passageId":"guanzi_ch-4_p-6","order":2,"canonicalText":"二曰溝瀆不遂於隘，鄣水不安其藏，國之貧也。","chunks":[["二曰溝瀆不遂於隘，鄣水不安其藏，國之貧也。","zh-Hant"]]},{"id":"guanzi_ch-4_p-6_s-3","passageId":"guanzi_ch-4_p-6","order":3,"canonicalText":"三曰桑麻不植於野，五穀不宜其地，國之貧也。","chunks":[["三曰桑麻不植於野，五穀不宜其地，國之貧也。","zh-Hant"]]},{"id":"guanzi_ch-4_p-6_s-4","passageId":"guanzi_ch-4_p-6","order":4,"canonicalText":"四曰六畜不育於家，瓜瓠葷菜百果不備具，國之貧也。","chunks":[["四曰六畜不育於家，瓜瓠葷菜百果不備具，國之貧也。","zh-Hant"]]},{"id":"guanzi_ch-4_p-6_s-5","passageId":"guanzi_ch-4_p-6","order":5,"canonicalText":"五曰工事競於刻鏤，女事繁於文章，國之貧也。","chunks":[["五曰工事競於刻鏤，女事繁於文章，國之貧也。","zh-Hant"]]},{"id":"guanzi_ch-4_p-6_s-6","passageId":"guanzi_ch-4_p-6","order":6,"canonicalText":"故曰：「山澤救於火，草木植成，國之富也。","chunks":[["故曰：「山澤救於火，草木植成，國之富也。","zh-Hant"]]},{"id":"guanzi_ch-4_p-6_s-7","passageId":"guanzi_ch-4_p-6","order":7,"canonicalText":"溝瀆遂於隘，鄣水安其藏，國之富也。","chunks":[["溝瀆遂於隘，鄣水安其藏，國之富也。","zh-Hant"]]},{"id":"guanzi_ch-4_p-6_s-8","passageId":"guanzi_ch-4_p-6","order":8,"canonicalText":"桑麻植於野，五穀宜其地，國之富也。","chunks":[["桑麻植於野，五穀宜其地，國之富也。","zh-Hant"]]},{"id":"guanzi_ch-4_p-6_s-9","passageId":"guanzi_ch-4_p-6","order":9,"canonicalText":"六畜育於家，瓜瓠葷菜百果備具，國之富也。","chunks":[["六畜育於家，瓜瓠葷菜百果備具，國之富也。","zh-Hant"]]},{"id":"guanzi_ch-4_p-6_s-10","passageId":"guanzi_ch-4_p-6","order":10,"canonicalText":"工事無刻鏤，女事無文章，國之富也。","chunks":[["工事無刻鏤，女事無文章，國之富也。","zh-Hant"]]},{"id":"guanzi_ch-4_p-6_s-11","passageId":"guanzi_ch-4_p-6","order":11,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"guanzi_ch-4_p-7_s-1","passageId":"guanzi_ch-4_p-7","order":1,"canonicalText":"右五事","chunks":[["右五事","zh-Hant"]]},{"id":"guanzi_ch-4_p-8_s-1","passageId":"guanzi_ch-4_p-8","order":1,"canonicalText":"分國以為五鄉，鄉為之師，分鄉以為五州，州為之長。","chunks":[["分國以為五鄉，鄉為之師，分鄉以為五州，州為之長。","zh-Hant"]]},{"id":"guanzi_ch-4_p-8_s-2","passageId":"guanzi_ch-4_p-8","order":2,"canonicalText":"分州以為十里，裏為之尉。","chunks":[["分州以為十里，裏為之尉。","zh-Hant"]]},{"id":"guanzi_ch-4_p-8_s-3","passageId":"guanzi_ch-4_p-8","order":3,"canonicalText":"分裏以為十遊，遊為之宗。","chunks":[["分裏以為十遊，遊為之宗。","zh-Hant"]]},{"id":"guanzi_ch-4_p-8_s-4","passageId":"guanzi_ch-4_p-8","order":4,"canonicalText":"十家為什，五家為伍，什伍皆有長焉。","chunks":[["十家為什，五家為伍，什伍皆有長焉。","zh-Hant"]]},{"id":"guanzi_ch-4_p-8_s-5","passageId":"guanzi_ch-4_p-8","order":5,"canonicalText":"築障塞匿，一道路，博出入，審閭閈，慎筦鍵，筦藏於裏尉。","chunks":[["築障塞匿，一道路，博出入，審閭閈，慎筦鍵，筦藏於裏尉。","zh-Hant"]]},{"id":"guanzi_ch-4_p-8_s-6","passageId":"guanzi_ch-4_p-8","order":6,"canonicalText":"置閭有司，以時開閉。","chunks":[["置閭有司，以時開閉。","zh-Hant"]]},{"id":"guanzi_ch-4_p-8_s-7","passageId":"guanzi_ch-4_p-8","order":7,"canonicalText":"閭有司觀出入者，以復於裏尉。","chunks":[["閭有司觀出入者，以復於裏尉。","zh-Hant"]]},{"id":"guanzi_ch-4_p-8_s-8","passageId":"guanzi_ch-4_p-8","order":8,"canonicalText":"凡出入不時，衣服不中，圈屬羣徒，不順於常者，閭有司見之，復無時。","chunks":[["凡出入不時，衣服不中，圈屬羣徒，不順於常者，閭有司見之，復無時。","zh-Hant"]]},{"id":"guanzi_ch-4_p-8_s-9","passageId":"guanzi_ch-4_p-8","order":9,"canonicalText":"若在長家子弟臣妾屬役賓客，則裏尉以譙於遊宗，遊宗以譙於什伍，什伍以譙於長家，譙敬而勿復。","chunks":[["若在長家子弟臣妾屬役賓客，則裏尉以譙於遊宗，遊宗以譙於什伍，什伍以譙於長家，譙敬而勿復。","zh-Hant"]]},{"id":"guanzi_ch-4_p-8_s-10","passageId":"guanzi_ch-4_p-8","order":10,"canonicalText":"一再則宥，三則不赦。","chunks":[["一再則宥，三則不赦。","zh-Hant"]]},{"id":"guanzi_ch-4_p-8_s-11","passageId":"guanzi_ch-4_p-8","order":11,"canonicalText":"凡孝悌忠信、賢良俊材，若在長家子弟臣妾屬役賓客，則什伍以復於遊宗，遊宗以復於裏尉。","chunks":[["凡孝悌忠信、賢良俊材，若在長家子弟臣妾屬役賓客，則什伍以復於遊宗，遊宗以復於裏尉。","zh-Hant"]]},{"id":"guanzi_ch-4_p-8_s-12","passageId":"guanzi_ch-4_p-8","order":12,"canonicalText":"裏尉以復於州長。","chunks":[["裏尉以復於州長。","zh-Hant"]]},{"id":"guanzi_ch-4_p-8_s-13","passageId":"guanzi_ch-4_p-8","order":13,"canonicalText":"州長以計於鄉師。","chunks":[["州長以計於鄉師。","zh-Hant"]]},{"id":"guanzi_ch-4_p-8_s-14","passageId":"guanzi_ch-4_p-8","order":14,"canonicalText":"鄉師以著於士師。","chunks":[["鄉師以著於士師。","zh-Hant"]]},{"id":"guanzi_ch-4_p-8_s-15","passageId":"guanzi_ch-4_p-8","order":15,"canonicalText":"凡過黨，其在家屬，及於長家。","chunks":[["凡過黨，其在家屬，及於長家。","zh-Hant"]]},{"id":"guanzi_ch-4_p-8_s-16","passageId":"guanzi_ch-4_p-8","order":16,"canonicalText":"其在長家，及於什伍之長。","chunks":[["其在長家，及於什伍之長。","zh-Hant"]]},{"id":"guanzi_ch-4_p-8_s-17","passageId":"guanzi_ch-4_p-8","order":17,"canonicalText":"其在什伍之長，及於遊宗。","chunks":[["其在什伍之長，及於遊宗。","zh-Hant"]]},{"id":"guanzi_ch-4_p-8_s-18","passageId":"guanzi_ch-4_p-8","order":18,"canonicalText":"其在遊宗，及於裏尉。","chunks":[["其在遊宗，及於裏尉。","zh-Hant"]]},{"id":"guanzi_ch-4_p-8_s-19","passageId":"guanzi_ch-4_p-8","order":19,"canonicalText":"其在裏尉，及於州長。","chunks":[["其在裏尉，及於州長。","zh-Hant"]]},{"id":"guanzi_ch-4_p-8_s-20","passageId":"guanzi_ch-4_p-8","order":20,"canonicalText":"其在州長，及於鄉師，其在鄉師，及於士師。","chunks":[["其在州長，及於鄉師，其在鄉師，及於士師。","zh-Hant"]]},{"id":"guanzi_ch-4_p-8_s-21","passageId":"guanzi_ch-4_p-8","order":21,"canonicalText":"三月一復，六月一計，十二月一著。","chunks":[["三月一復，六月一計，十二月一著。","zh-Hant"]]},{"id":"guanzi_ch-4_p-8_s-22","passageId":"guanzi_ch-4_p-8","order":22,"canonicalText":"凡上賢不過等，使能不兼官，罰有罪不獨及，賞有功不專與。","chunks":[["凡上賢不過等，使能不兼官，罰有罪不獨及，賞有功不專與。","zh-Hant"]]},{"id":"guanzi_ch-4_p-9_s-1","passageId":"guanzi_ch-4_p-9","order":1,"canonicalText":"孟春之朝，君自聽朝，論爵賞校官，終五日。","chunks":[["孟春之朝，君自聽朝，論爵賞校官，終五日。","zh-Hant"]]},{"id":"guanzi_ch-4_p-9_s-2","passageId":"guanzi_ch-4_p-9","order":2,"canonicalText":"季冬之夕，君自聽朝，論罰罪刑殺，亦終五日。","chunks":[["季冬之夕，君自聽朝，論罰罪刑殺，亦終五日。","zh-Hant"]]},{"id":"guanzi_ch-4_p-9_s-3","passageId":"guanzi_ch-4_p-9","order":3,"canonicalText":"正月之朔，百吏在朝，君乃出令布憲於國，五鄉之師，五屬大夫，皆受憲於太史。","chunks":[["正月之朔，百吏在朝，君乃出令布憲於國，五鄉之師，五屬大夫，皆受憲於太史。","zh-Hant"]]},{"id":"guanzi_ch-4_p-9_s-4","passageId":"guanzi_ch-4_p-9","order":4,"canonicalText":"大朝之日，五鄉之師，五屬大夫，皆身習憲於君前。","chunks":[["大朝之日，五鄉之師，五屬大夫，皆身習憲於君前。","zh-Hant"]]},{"id":"guanzi_ch-4_p-9_s-5","passageId":"guanzi_ch-4_p-9","order":5,"canonicalText":"太史既布憲，入籍於太府。","chunks":[["太史既布憲，入籍於太府。","zh-Hant"]]},{"id":"guanzi_ch-4_p-9_s-6","passageId":"guanzi_ch-4_p-9","order":6,"canonicalText":"憲籍分於君前。","chunks":[["憲籍分於君前。","zh-Hant"]]},{"id":"guanzi_ch-4_p-9_s-7","passageId":"guanzi_ch-4_p-9","order":7,"canonicalText":"五鄉之師出朝，遂於鄉官致於鄉屬，及於遊宗，皆受憲。","chunks":[["五鄉之師出朝，遂於鄉官致於鄉屬，及於遊宗，皆受憲。","zh-Hant"]]},{"id":"guanzi_ch-4_p-9_s-8","passageId":"guanzi_ch-4_p-9","order":8,"canonicalText":"憲既布，乃反致令焉，然後敢就舍；","chunks":[["憲既布，乃反致令焉，然後敢就舍；","zh-Hant"]]},{"id":"guanzi_ch-4_p-9_s-9","passageId":"guanzi_ch-4_p-9","order":9,"canonicalText":"憲未布，令未致，不敢就舍。","chunks":[["憲未布，令未致，不敢就舍。","zh-Hant"]]},{"id":"guanzi_ch-4_p-9_s-10","passageId":"guanzi_ch-4_p-9","order":10,"canonicalText":"就舍，謂之留令。","chunks":[["就舍，謂之留令。","zh-Hant"]]},{"id":"guanzi_ch-4_p-9_s-11","passageId":"guanzi_ch-4_p-9","order":11,"canonicalText":"罪死不赦。","chunks":[["罪死不赦。","zh-Hant"]]},{"id":"guanzi_ch-4_p-9_s-12","passageId":"guanzi_ch-4_p-9","order":12,"canonicalText":"五屬大夫，皆以行車朝，出朝不敢就舍，遂行至都之日。","chunks":[["五屬大夫，皆以行車朝，出朝不敢就舍，遂行至都之日。","zh-Hant"]]},{"id":"guanzi_ch-4_p-9_s-13","passageId":"guanzi_ch-4_p-9","order":13,"canonicalText":"遂於廟致屬吏，皆受憲。","chunks":[["遂於廟致屬吏，皆受憲。","zh-Hant"]]},{"id":"guanzi_ch-4_p-9_s-14","passageId":"guanzi_ch-4_p-9","order":14,"canonicalText":"憲既布，乃發使者致令以布憲之日蚤晏之時，憲既布，使者以發，然後敢就舍；","chunks":[["憲既布，乃發使者致令以布憲之日蚤晏之時，憲既布，使者以發，然後敢就舍；","zh-Hant"]]},{"id":"guanzi_ch-4_p-9_s-15","passageId":"guanzi_ch-4_p-9","order":15,"canonicalText":"憲未布。","chunks":[["憲未布。","zh-Hant"]]},{"id":"guanzi_ch-4_p-9_s-16","passageId":"guanzi_ch-4_p-9","order":16,"canonicalText":"使者未發，不敢就舍；","chunks":[["使者未發，不敢就舍；","zh-Hant"]]},{"id":"guanzi_ch-4_p-9_s-17","passageId":"guanzi_ch-4_p-9","order":17,"canonicalText":"就舍，謂之留令，罪死不赦。","chunks":[["就舍，謂之留令，罪死不赦。","zh-Hant"]]},{"id":"guanzi_ch-4_p-9_s-18","passageId":"guanzi_ch-4_p-9","order":18,"canonicalText":"憲既布，有不行憲者，謂之不從令，罪死不赦。","chunks":[["憲既布，有不行憲者，謂之不從令，罪死不赦。","zh-Hant"]]},{"id":"guanzi_ch-4_p-9_s-19","passageId":"guanzi_ch-4_p-9","order":19,"canonicalText":"考憲而有不合於太府之籍者，侈曰專制，不足曰虧令，罪死不赦。","chunks":[["考憲而有不合於太府之籍者，侈曰專制，不足曰虧令，罪死不赦。","zh-Hant"]]},{"id":"guanzi_ch-4_p-9_s-20","passageId":"guanzi_ch-4_p-9","order":20,"canonicalText":"首憲既布，然後可以布憲。","chunks":[["首憲既布，然後可以布憲。","zh-Hant"]]},{"id":"guanzi_ch-4_p-10_s-1","passageId":"guanzi_ch-4_p-10","order":1,"canonicalText":"右首憲","chunks":[["右首憲","zh-Hant"]]},{"id":"guanzi_ch-4_p-11_s-1","passageId":"guanzi_ch-4_p-11","order":1,"canonicalText":"凡將舉事，令必先出，曰事將為。","chunks":[["凡將舉事，令必先出，曰事將為。","zh-Hant"]]},{"id":"guanzi_ch-4_p-11_s-2","passageId":"guanzi_ch-4_p-11","order":2,"canonicalText":"其賞罰之數，必先明之，立事者，謹守令以行賞罰，計事致令，復賞罰之所加，有不合於令之所謂者，雖有功利，則謂之專制，罪死不赦。","chunks":[["其賞罰之數，必先明之，立事者，謹守令以行賞罰，計事致令，復賞罰之所加，有不合於令之所謂者，雖有功利，則謂之專制，罪死不赦。","zh-Hant"]]},{"id":"guanzi_ch-4_p-11_s-3","passageId":"guanzi_ch-4_p-11","order":3,"canonicalText":"首事既布，然後可以舉事。","chunks":[["首事既布，然後可以舉事。","zh-Hant"]]},{"id":"guanzi_ch-4_p-12_s-1","passageId":"guanzi_ch-4_p-12","order":1,"canonicalText":"右首事","chunks":[["右首事","zh-Hant"]]},{"id":"guanzi_ch-4_p-13_s-1","passageId":"guanzi_ch-4_p-13","order":1,"canonicalText":"修火憲，敬山澤，林藪積草，夫財之所出，以時禁發焉。","chunks":[["修火憲，敬山澤，林藪積草，夫財之所出，以時禁發焉。","zh-Hant"]]},{"id":"guanzi_ch-4_p-13_s-2","passageId":"guanzi_ch-4_p-13","order":2,"canonicalText":"使民足於宮室之用，薪蒸之所積，虞師之事也，決水潦，通溝瀆，修障防，安水藏，使時水雖過度，無害於五穀。","chunks":[["使民足於宮室之用，薪蒸之所積，虞師之事也，決水潦，通溝瀆，修障防，安水藏，使時水雖過度，無害於五穀。","zh-Hant"]]},{"id":"guanzi_ch-4_p-13_s-3","passageId":"guanzi_ch-4_p-13","order":3,"canonicalText":"歲雖兇旱，有所秎穫，司空之事也。","chunks":[["歲雖兇旱，有所秎穫，司空之事也。","zh-Hant"]]},{"id":"guanzi_ch-4_p-13_s-4","passageId":"guanzi_ch-4_p-13","order":4,"canonicalText":"相高下，視肥墝，觀地宜，明詔期，前後農夫，以時均修焉，使五穀桑麻，皆安其處，由田之事也。","chunks":[["相高下，視肥墝，觀地宜，明詔期，前後農夫，以時均修焉，使五穀桑麻，皆安其處，由田之事也。","zh-Hant"]]},{"id":"guanzi_ch-4_p-13_s-5","passageId":"guanzi_ch-4_p-13","order":5,"canonicalText":"行鄉里，視宮室，觀樹蓺，簡六畜，以時鈞修焉。","chunks":[["行鄉里，視宮室，觀樹蓺，簡六畜，以時鈞修焉。","zh-Hant"]]},{"id":"guanzi_ch-4_p-13_s-6","passageId":"guanzi_ch-4_p-13","order":6,"canonicalText":"勸勉百姓，使力作毋偷。","chunks":[["勸勉百姓，使力作毋偷。","zh-Hant"]]},{"id":"guanzi_ch-4_p-13_s-7","passageId":"guanzi_ch-4_p-13","order":7,"canonicalText":"懷樂家室，重去鄉里，鄉師之事也。","chunks":[["懷樂家室，重去鄉里，鄉師之事也。","zh-Hant"]]},{"id":"guanzi_ch-4_p-13_s-8","passageId":"guanzi_ch-4_p-13","order":8,"canonicalText":"論百工，審時事，辨功苦，上完利，監壹五鄉，以時鈞修焉。","chunks":[["論百工，審時事，辨功苦，上完利，監壹五鄉，以時鈞修焉。","zh-Hant"]]},{"id":"guanzi_ch-4_p-13_s-9","passageId":"guanzi_ch-4_p-13","order":9,"canonicalText":"使刻鏤文采，毋敢造於鄉，工師之事也。","chunks":[["使刻鏤文采，毋敢造於鄉，工師之事也。","zh-Hant"]]},{"id":"guanzi_ch-4_p-14_s-1","passageId":"guanzi_ch-4_p-14","order":1,"canonicalText":"右省官","chunks":[["右省官","zh-Hant"]]},{"id":"guanzi_ch-4_p-15_s-1","passageId":"guanzi_ch-4_p-15","order":1,"canonicalText":"度爵而制服，量祿而用財，飲食有量，衣服有制，宮室有度，六畜人徒有數，舟車陳器有禁，修生則有軒冕服位穀祿田宅之分，死則有棺槨絞衾壙壟之度。","chunks":[["度爵而制服，量祿而用財，飲食有量，衣服有制，宮室有度，六畜人徒有數，舟車陳器有禁，修生則有軒冕服位穀祿田宅之分，死則有棺槨絞衾壙壟之度。","zh-Hant"]]},{"id":"guanzi_ch-4_p-15_s-2","passageId":"guanzi_ch-4_p-15","order":2,"canonicalText":"雖有賢身貴體，毋其爵，不敢服其服。","chunks":[["雖有賢身貴體，毋其爵，不敢服其服。","zh-Hant"]]},{"id":"guanzi_ch-4_p-15_s-3","passageId":"guanzi_ch-4_p-15","order":3,"canonicalText":"雖有富家多資，毋其祿，不敢用其財。","chunks":[["雖有富家多資，毋其祿，不敢用其財。","zh-Hant"]]},{"id":"guanzi_ch-4_p-15_s-4","passageId":"guanzi_ch-4_p-15","order":4,"canonicalText":"天子服文有章，而夫人不敢以燕以饗廟，將軍大夫不敢以朝官吏，以命士，止於帶緣，散民不敢服雜採，百工商賈不得服長鬈貂，刑餘戮民不敢服絻，不敢畜連乘車。","chunks":[["天子服文有章，而夫人不敢以燕以饗廟，將軍大夫不敢以朝官吏，以命士，止於帶緣，散民不敢服雜採，百工商賈不得服長鬈貂，刑餘戮民不敢服絻，不敢畜連乘車。","zh-Hant"]]},{"id":"guanzi_ch-4_p-16_s-1","passageId":"guanzi_ch-4_p-16","order":1,"canonicalText":"右服制","chunks":[["右服制","zh-Hant"]]},{"id":"guanzi_ch-4_p-17_s-1","passageId":"guanzi_ch-4_p-17","order":1,"canonicalText":"寢兵之說勝，則險阻不守；","chunks":[["寢兵之說勝，則險阻不守；","zh-Hant"]]},{"id":"guanzi_ch-4_p-17_s-2","passageId":"guanzi_ch-4_p-17","order":2,"canonicalText":"兼愛之說勝，則士卒不戰。","chunks":[["兼愛之說勝，則士卒不戰。","zh-Hant"]]},{"id":"guanzi_ch-4_p-17_s-3","passageId":"guanzi_ch-4_p-17","order":3,"canonicalText":"全生之說勝，則廉恥不立。","chunks":[["全生之說勝，則廉恥不立。","zh-Hant"]]},{"id":"guanzi_ch-4_p-17_s-4","passageId":"guanzi_ch-4_p-17","order":4,"canonicalText":"私議自貴之說勝，則上令不行。","chunks":[["私議自貴之說勝，則上令不行。","zh-Hant"]]},{"id":"guanzi_ch-4_p-17_s-5","passageId":"guanzi_ch-4_p-17","order":5,"canonicalText":"羣徒比周之說勝，則賢不肖不分。","chunks":[["羣徒比周之說勝，則賢不肖不分。","zh-Hant"]]},{"id":"guanzi_ch-4_p-17_s-6","passageId":"guanzi_ch-4_p-17","order":6,"canonicalText":"金玉貨財之說勝。","chunks":[["金玉貨財之說勝。","zh-Hant"]]},{"id":"guanzi_ch-4_p-17_s-7","passageId":"guanzi_ch-4_p-17","order":7,"canonicalText":"則爵服下流，觀樂玩好之說勝。","chunks":[["則爵服下流，觀樂玩好之說勝。","zh-Hant"]]},{"id":"guanzi_ch-4_p-17_s-8","passageId":"guanzi_ch-4_p-17","order":8,"canonicalText":"則姦民在上位。","chunks":[["則姦民在上位。","zh-Hant"]]},{"id":"guanzi_ch-4_p-17_s-9","passageId":"guanzi_ch-4_p-17","order":9,"canonicalText":"請謁任舉之說勝，則繩墨不正，諂諛飾過之說勝，則巧佞者用。","chunks":[["請謁任舉之說勝，則繩墨不正，諂諛飾過之說勝，則巧佞者用。","zh-Hant"]]},{"id":"guanzi_ch-4_p-18_s-1","passageId":"guanzi_ch-4_p-18","order":1,"canonicalText":"右九敗","chunks":[["右九敗","zh-Hant"]]},{"id":"guanzi_ch-4_p-19_s-1","passageId":"guanzi_ch-4_p-19","order":1,"canonicalText":"期而致，使而往，百姓捨己以上為心者，教之所期也。","chunks":[["期而致，使而往，百姓捨己以上為心者，教之所期也。","zh-Hant"]]},{"id":"guanzi_ch-4_p-19_s-2","passageId":"guanzi_ch-4_p-19","order":2,"canonicalText":"始於不足見，終於不可及，一人服之，萬人從之，訓之所期也。","chunks":[["始於不足見，終於不可及，一人服之，萬人從之，訓之所期也。","zh-Hant"]]},{"id":"guanzi_ch-4_p-19_s-3","passageId":"guanzi_ch-4_p-19","order":3,"canonicalText":"未之令而為，未之使而往，上不加勉，而民自盡，竭俗之所期也。","chunks":[["未之令而為，未之使而往，上不加勉，而民自盡，竭俗之所期也。","zh-Hant"]]},{"id":"guanzi_ch-4_p-19_s-4","passageId":"guanzi_ch-4_p-19","order":4,"canonicalText":"好惡形於心，百姓化於下，罰未行而民畏恐，賞未加而民勸勉，誠信之所期也。","chunks":[["好惡形於心，百姓化於下，罰未行而民畏恐，賞未加而民勸勉，誠信之所期也。","zh-Hant"]]},{"id":"guanzi_ch-4_p-19_s-5","passageId":"guanzi_ch-4_p-19","order":5,"canonicalText":"為而無害，成而不議，得而莫之能爭，天道之所期也。","chunks":[["為而無害，成而不議，得而莫之能爭，天道之所期也。","zh-Hant"]]},{"id":"guanzi_ch-4_p-19_s-6","passageId":"guanzi_ch-4_p-19","order":6,"canonicalText":"為之而成，求之而得，上之所欲，小大必舉，事之所期也。","chunks":[["為之而成，求之而得，上之所欲，小大必舉，事之所期也。","zh-Hant"]]},{"id":"guanzi_ch-4_p-19_s-7","passageId":"guanzi_ch-4_p-19","order":7,"canonicalText":"令則行，禁則止，憲之所及，俗之所被，如百體之從心，政之所期也。","chunks":[["令則行，禁則止，憲之所及，俗之所被，如百體之從心，政之所期也。","zh-Hant"]]},{"id":"guanzi_ch-4_p-20_s-1","passageId":"guanzi_ch-4_p-20","order":1,"canonicalText":"右七觀","chunks":[["右七觀","zh-Hant"]]}]}') as WorkBundle
